,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'function ToggleAll(e){',
'  if (e.checked){CheckAll(); }',
'  else{ClearAll();}',
'  }',
'',
'function Check(e){e.checked = true; }',
'function Clear(e){e.checked = false;}',
'function CheckAll(){',
'  var ml = document.wwv_flow;',
'  var len = ml.elements.length;',
'  for (var i = 0; i < len; i++){',
'    var e = ml.elements[i];',
'    if (e.name == "f01") {Check(e);}',
'   }',
'  ml.f01.checked = true;',
' }',
'',
'function ClearAll(){',
'  var ml = document.wwv_flow;',
'  var len = ml.elements.length;',
'  for (var i = 0; i < len; i++){',
'    var e = ml.elements[i];',
'    if (e.name == "f01") {Clear(e);}',
'  }',
'  ml.f01.checked = false;',
'}'))
,p_step_template=>wwv_flow_imp.id(690783685471803190.4501)
