,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  q varchar2(32767);',
'begin',
'  q := ',
'''select',
'  wwv_flow_item.checkbox(1,x.column_name) include,  ',
'  x.column_id,',
'  x.column_name column_name, ',
'  wwv_flow_item.text(2,null,90)||wwv_flow_item.hidden(3,x.data_type)||wwv_flow_item.hidden(4,x.column_name) condition,   ',
'  x.data_type data_type,',
'  x.comments',
'from (',
'select ',
'  t.column_id,',
'  t.column_name,',
'  t.data_type,',
'  c.comments',
'from sys.all_tab_columns t, sys.all_col_comments c',
'where t.owner = c.owner',
'and t.table_name = c.table_name',
'and t.column_name = c.column_name',
'and (t.owner in (''''SYS'''','''''' || wwv_flow.g_flow_schema_owner || ''''''))',
'and t.table_name = :F4500_P14_OBJECT_NAME',
') x'';',
'return q;',
'end;'))
