wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(72974620438464018.4501)
,p_name=>'F4500_P15_PARSE_STMT_AS'
,p_item_sequence=>20
,p_item_plug_id=>wwv_flow_imp.id(8433315974658433.4501)
,p_prompt=>'Esquema'
,p_source=>'wwv_flow_user_api.get_default_schema'
,p_source_type=>'EXPRESSION'
,p_source_language=>'PLSQL'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_named_lov=>'LIST_AVAILABLE_SCHEMAS'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select wwv_flow_escape.html( c.schema ) d,',
'       c.schema v ',
'  from wwv_flow_company_schemas c, ',
'       wwv_flow_fnd_user u',
' where c.security_group_id = :FLOW_SECURITY_GROUP_ID',
'   and u.security_group_id = :FLOW_SECURITY_GROUP_ID  ',
'   and u.user_name         = :FLOW_USER   ',
'   and ( u.allow_access_to_schemas is null or ',
'         instr( '':'' || u.allow_access_to_schemas || '':'' , '':'' || c.schema || '':'' ) > 0 )',
' order by 1'))
,p_cSize=>30
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(488671029226029669.4501)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_restricted_characters=>'WRKSP_USER_SCHEMA'
,p_help_text=>'Seleccione un esquema de base de datos (o nombre de usuario) con el que analizar esta consulta de tipo consulta mediante ejemplo.'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
