,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'query'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_sql   varchar2(32767) := null;',
'  l_count number := 1;',
'begin  ',
'  l_sql:=''select '';',
'',
'  for i in 1..wwv_flow.g_f01.count loop',
'    l_sql:=l_sql||wwv_flow.g_f01(i)||'', '';',
'  end loop;',
'  l_sql:=rtrim(l_sql,'', '');',
'',
'  l_sql:=l_sql||'' from ''||:F4500_P14_OBJECT_NAME;  ',
'  ',
'  for j in 1..wwv_flow.g_f04.count loop -- column_name',
'    if wwv_flow.g_f02(j) is not null then    -- condition',
'        ',
'      if l_count = 1 then      ',
'        l_sql:=l_sql||'' where ''||wwv_flow.g_f04(j)||'' like '';',
'        l_sql:=l_sql||wwv_flow_utilities.ite(wwv_flow.g_f03(j)=''VARCHAR2'',',
'                                             ''''''''||upper(wwv_flow.g_f02(j))||'''''''',',
'                                             wwv_flow.g_f02(j));',
'      elsif l_count > 1 then',
'        l_sql:=l_sql||'' and ''||wwv_flow.g_f04(j)||'' like '';',
'        l_sql:=l_sql||wwv_flow_utilities.ite(wwv_flow.g_f03(j)=''VARCHAR2'',',
'                                             ''''''''||upper(wwv_flow.g_f02(j))||'''''''',',
'                                             wwv_flow.g_f02(j));',
'      end if;',
'      l_count := l_count + 1;',
'    end if;    ',
'  end loop; ',
'  ',
'  :f4500_p14_query := l_sql;',
'  ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Error al crear una consulta de diccionario de datos v\00E1lida.')
,p_process_when_button_id=>wwv_flow_imp.id(72676514275580298.4501)
,p_internal_uid=>72792311558912454.4501
);
