wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(198129821429313685.4501)
,p_validation_name=>'COLUMN_NAME UNIQUE'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_need_check varchar2(1) := ''N'';',
'begin',
'   if :P17_COLUMN_ID is not null then',
'      for c1 in (',
'         select column_name old_col_name',
'           from wwv_flow_hnt_column_dict',
'          where column_id = :P17_COLUMN_ID',
'            and security_group_id = :flow_security_group_id )',
'      loop',
'         if c1.old_col_name != :P17_COLUMN_NAME then',
'            l_need_check := ''Y'';  -- name change',
'         end if;',
'      end loop;',
'   else l_need_check := ''Y'';  -- new record',
'   end if;',
'',
'   if l_need_check = ''Y'' then',
'      for c1 in (',
'         select count(*) cnt',
'           from wwv_flow_hnt_col_dict_syn',
'          where syn_name = upper(:P17_COLUMN_NAME) ',
'            and security_group_id = :flow_security_group_id )',
'      loop',
'         if c1.cnt > 0 then',
'            return false;',
'         else return true;',
'         end if;',
'      end loop;',
'   else return true;',
'   end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('Este nombre de columna ya existe como una columna o un sin\00F3nimo de una columna.')
