'x:=x||''  (buffer_gets/nvl(replace(executions,0,1),1)) efficiency2, '';',
'x:=x||''  child_number,hash_value,address, '';',
'x:=x||'' case '';',
'x:=x||'' when (select count(*) from sys.gv_$sql_plan sp where  sp.address=s.address '';',
'x:=x||'' and sp.HASH_VALUE=s.hash_value and sp.CHILD_NUMBER=s.child_number) > 0'';',
'x:=x||'' then ''''<a href="f?p=4500:551:&SESSION.::NO:551:P551_ADDRESS,P551_HASH_VALUE,P551_CHILD_NUMBER,P551_INST_ID:''''||s.address||'''',''''||s.hash_value||'''',''''||s.child_number||'''',''''||s.inst_id||''''"><span class="a-Icon icon-search"></span><span class="u'
||'-VisuallyHidden">''||wwv_flow_lang.system_message(''VIEW_FOR_ALT_TAG'')||''</span></a> '''' '';',
'x:=x||'' else null '';',
'x:=x||'' end x, '';',
'x:=x||'' null link, '';',
'x:=x||''  (elapsed_time/1000000) elapsed_time,  '';',
'x:=x||''  ''''''||wwv_flow_lang.system_message(''SESSION_MON_ELAPSED'')||'' ''''||to_char((elapsed_time/1000000),''''999G999G999G999D00'''') || '';',
'x:=x||''  ''''<br />''||wwv_flow_lang.system_message(''SESSION_MON_CPU'')||'' ''''||to_char((cpu_time/1000000),''''999G999G999G999D00'''') the_time,  '';',
'x:=x||''  ''''''||wwv_flow_lang.system_message(''SESSION_MON_DISK'')||'' ''''||to_char(disk_reads,''''999G999G999G999'''')||''''<br />''''|| '';',
'x:=x||''  ''''''||wwv_flow_lang.system_message(''SESSION_MON_BUFFER'')||'' ''''||to_char(buffer_gets,''''999G999G999G999'''') reads,module  '';',
