'        p := p||'' where '';',
'    else',
'        p := p||'' and '';',
'    end if;',
'    p := p||'' instr(upper(module),upper(:P21_MODULE))>0 '';',
'end if;',
'',
'if p is not null then',
'    x:=x||p;',
'end if;',
'',
'-- End Predicates',
'x:=x||'' order by '';',
'',
