'    when ''DISK_READS'' then x:=x||'' DISK_READS '';',
'    when ''BUFFER_GETS'' then x:=x||'' BUFFER_GETS '';',
'    when ''EXECUTIONS'' then x:=x||'' EXECUTIONS '';',
'    when ''EFFICIENCY'' then x:=x||'' EFFICIENCY '';',
'    when ''EFFICIENCY2'' then x:=x||'' EFFICIENCY2 '';',
'    ',
'else x:=x||'' CPU_TIME '';',
'end case;',
'',
'',
'x:=x||''  desc nulls last) '';',
