,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select o.object_id,',
'       t.table_name,',
'       t.num_rows,',
'       t.last_analyzed,',
'       ''TABLE'' object_type',
'  from sys.user_tables t,',
'       sys.user_objects o',
' where o.object_name = t.table_name',
'   and o.object_type = ''TABLE''',
'   and (instr(upper(t.table_name), upper(:P24_FIND)) > 0 or :P24_FIND IS NULL)',
'union all',
'select o.object_id,',
'       v.view_name table_name,',
'       null num_rows,',
'       null last_analyzed,',
'       ''VIEW'' object_type',
'  from sys.user_views v,',
'       sys.user_objects o',
' where o.object_name = v.view_name',
'   and o.object_type = ''VIEW''',
'   and (instr(upper(v.view_name), upper(:P24_FIND)) > 0 or :P24_FIND IS NULL)',
'   and :P24_INCLUDE_VIEWS = ''YES'''))
