'declare ',
'q2 varchar2(32767);',
'begin',
'wwv_flow_sw_api.check_priv(:P1003_SCHEMA);',
'q2 := ''select ''||chr(10);',
'for c1 in (',
'select column_name',
'from sys.dba_TAB_COLUMNS c',
'where table_name = :P24_TABLE_NAME and',
'    c.owner = :P1003_SCHEMA',
'order by column_id) loop',
'q2 := q2 ||'' ''||wwv_flow_escape.html(c1.column_name)||'',''||chr(10);',
'end loop;',
'q2 := rtrim(rtrim(q2,chr(10)),'','')||chr(10)||'' from ''||wwv_flow_escape.html(:P24_TABLE_NAME)||chr(10);',
'sys.htp.p(''<textarea id="qReturn" style="width:100%;height:200px;">''||q2||''</textarea>'');',
'end;',
''))
