,p_process_sequence=>40
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Compute Space Info at Bottom'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_max_output_size   number := 0;',
'    l_used              number := 0;',
'    l_free              number := 0;',
'begin',
'    l_max_output_size := nvl(wwv_flow_platform.get_preference(''WORKSPACE_MAX_OUTPUT_SIZE''),10000000);',
'    for c1 in (select sum(result_size) the_sum',
'                 from wwv_flow_sw_detail_results',
'                where security_group_id = :flow_security_group_id)',
'    loop',
'        l_used := nvl(c1.the_sum,0);',
'        exit;',
'    end loop;--c1',
'    ',
'    l_free := nvl(l_max_output_size - l_used,0);',
'    if sign(l_free) = -1 then',
'        l_free := 0;',
'    end if;',
'    ',
'    ',
'    ',
'    ',
'    :P31_FREE := to_char(l_free,''999G999G999G999G999'');',
'    :P31_USED := to_char(l_used,''999G999G999G999G999'');',
'    ',
'    :P31_TOTAL_QUOTA := to_char(l_max_output_size,''999G999G999G999G999'');',
'    ',
'    :P31_AVAILABLE_SPACE := wwv_flow_sw_script.draw_quotameter2(',
'                                   p_max_size       => l_max_output_size,',
'                                   p_current_size   => l_used);',
'    ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>150010615148724106.4501
);
end;
