,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_null varchar2(1) := ''N'';',
'begin',
'for i in 1..wwv_flow.g_f05.count loop',
'    if wwv_flow.g_f03(i) is null',
'       then l_null := ''Y'';',
'            exit;',
'    end if;',
'end loop;',
'',
'if l_null = ''Y''',
'   then return false;',
'else ',
'   return true;',
'end if;',
'end;'))
