wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(424102231578420636.4501)
,p_validation_name=>'SequenceNumeric'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'   l_check varchar2(200);',
'   l_ones  varchar2(200);',
'   l_found varchar2(1) := ''N'';',
'   ',
'begin',
'for i in 1..wwv_flow.g_f05.count',
'loop',
'   if wwv_flow.g_f03(i) is not null',
'      then l_check := wwv_flow.g_f03(i);',
'           l_check := replace(l_check,''0'',''1'');',
'           l_check := replace(l_check,''2'',''1'');',
'           l_check := replace(l_check,''3'',''1'');',
'           l_check := replace(l_check,''4'',''1'');',
'           l_check := replace(l_check,''5'',''1'');',
'           l_check := replace(l_check,''6'',''1'');',
'           l_check := replace(l_check,''7'',''1'');',
'           l_check := replace(l_check,''8'',''1'');',
'           l_check := replace(l_check,''9'',''1'');',
'           l_ones := ''1'';',
'           if l_check = lpad(l_ones,length(l_check),''1'')',
'              then null;',
'           else l_found := ''Y'';',
'                exit;',
'           end if;',
'   end if;',
'end loop;',
'',
'if l_found = ''Y''',
'   then return false;',
'else',
'   return true;',
'end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('La secuencia debe ser num\00E9rica.')
,p_when_button_pressed=>wwv_flow_imp.id(293410205641016582.4501)
);
