wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(1100180815559278538.4501)
,p_name=>'Lista de Objetos'
,p_parent_plug_id=>wwv_flow_imp.id(85613016500937615.4501)
,p_template=>wwv_flow_imp.id(717419707883820782.4501)
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'FUNC_BODY_RETURNING_SQL'
,p_function_body_language=>'PLSQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if :F4500_P18_OBJECT_TYPE = ''DATABASE LINK'' then',
'return ''select ''''DATABASE LINK'''' object_type, wwv_flow_item.checkbox(1,db_link) ck, db_link object_name ',
'          from sys.all_db_links'';',
'else',
'return q''[with obj_type_str as (',
'    select '':''||:F4500_P18_OBJECT_TYPE||'':'' obj_type_str from sys.dual ),',
'obj_types as (',
'    select regexp_substr (',
'               obj_type_str,',
'               ''[^:]*'',',
'               instr(obj_type_str,'':'',1,level)+1 ) t',
'    from obj_type_str',
'    connect by level <= length(regexp_replace(obj_type_str,''[^:]+'',null))-1)',
'select object_type,',
'       wwv_flow_item.checkbox(1,object_name) ck,',
'       object_name',
'  from apex_sys_all_objects',
' where owner = :F4500_P18_SCHEMA',
'   and object_type in (select /*+cardinality(obj_types 1)*/ t from obj_types)',
'   and object_name not like ''BIN$%''',
'   and ( instr( object_name, upper(:P44_FILTER) ) > 0 or :P44_FILTER is null )',
' order by object_type, object_name',
']'';',
'end if;'))
,p_display_when_condition=>'wwv_flow_security.current_company_can_build(p_in_schema=>:F4500_P18_SCHEMA)'
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P44_FILTER'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_plug_query_max_columns=>20
,p_query_num_rows=>6000
,p_query_options=>'GENERIC_REPORT_COLUMNS'
,p_query_show_nulls_as=>'(null)'
,p_query_break_cols=>'1'
,p_query_no_data_found=>unistr('No se ha encontrado ning\00FAn objeto.')
,p_query_row_count_max=>6000
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'Y'
,p_plug_query_parse_override=>'F4500_P18_SCHEMA'
);
