,p_process_name=>'save ddl'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'--',
'-- Check that the user has the appropriate privileges',
'--',
'wwv_flow_sw_api.check_priv ( p_schema => :F4500_P18_SCHEMA );',
'',
'--',
'-- if generate DDL is from page 43, pass only select object types',
'--',
'if :f4500_p45_ddl_type = ''OBJECT_TYPE'' then',
'    wwv_flow_generate_ddl.execute_get_ddl(',
'        p_schema             => :f4500_p18_schema,',
'        p_object_types       => :F4500_P18_OBJECT_TYPE,',
'        p_output_type        => wwv_flow_generate_ddl.c_output_to_script,',
'        p_filename           => :F4500_P45_SCRIPT_NAME,',
'        p_description        => :F4500_P45_DESCRIPTION,',
'        p_inc_dependent_ddls => true );',
'--',
'-- if generate DDL is from page 44, pass only select object names',
'--',
'elsif :f4500_p45_ddl_type = ''OBJECT_NAME'' then',
'    wwv_flow_generate_ddl.execute_get_ddl(',
'        p_schema       => :f4500_p18_schema,',
'        p_object_types => :F4500_P18_OBJECT_TYPE,',
'        p_objects      => :f4500_p18_object_name,',
'        p_output_type  => wwv_flow_generate_ddl.c_output_to_script,',
'        p_filename     => :F4500_P45_SCRIPT_NAME,',
'        p_description  => :F4500_P45_DESCRIPTION,',
'        p_inc_dependent_ddls => true );',
'end if;'))
