wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(107296117288133287.4501)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'download script'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_clob        clob;',
'  l_script_name varchar2(4000) := null;',
'begin',
'  for c1 in (select clob001 script, c001 file_id, c002 name                   ',
'             from htmldb_collections',
'             where collection_name = ''SR_SCRIPT_SOURCE'') loop',
'    l_clob := c1.script;',
'    l_script_name := c1.name;           ',
'  end loop;',
'  if instr(l_script_name,''.sql'',1) = 0 then',
'  	l_script_name := l_script_name||''.sql'';',
'  end if;',
'  wwv_flow_init_htp_buffer;',
'  wwv_flow.g_page_text_generated := true;',
'  wwv_flow.g_unrecoverable_error := true;',
'  ',
'  wwv_flow_utilities.print_download_header(',
'    p_mime_type =>     ''text/plain'',',
'    p_file_name =>     l_script_name,',
'    p_is_attachment => true',
'  );',
'  ',
'  sys.owa_util.http_header_close;',
'  ',
'  wwv_flow_sw_script.print_clob(p_str => l_clob);',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'No se ha podido descargar el script.'
,p_process_when=>'DOWNLOAD'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>107296117288133287.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(164287405457168586.4501)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set file_id for create and run'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (select clob001 script, c001 file_id',
'           from htmldb_collections',
'           where collection_name = ''SR_SCRIPT_SOURCE'') loop',
'    :P60_FILE_ID := c1.file_id;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'RUN'
,p_process_when_type=>'NEVER'
,p_internal_uid=>164287405457168586.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(251810317427563975.4501)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set file_id for replace and run'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_file_id number := null;',
'begin',
'  for c1 in (select clob001 script, c001 file_id, c002 name                   ',
'             from htmldb_collections',
'             where collection_name = ''SR_SCRIPT_SOURCE'') loop',
'      for c2 in (select id',
'                 from wwv_flow_files',
'                 where lower(filename) = lower(c1.name)',
'                 and file_type = ''SCRIPT'')',
'      loop',
'          l_file_id := c2.id;',
'          exit;',
'      end loop; ',
'      :P60_FILE_ID := l_file_id;',
'  end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'REPLACE_RUN,RUN'
,p_process_when_type=>'REQUEST_IN_CONDITION'
,p_internal_uid=>251810317427563975.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(657008053639142129.4501)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Convert BLOB to CLOB'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_clob         clob;',
'    l_dest_offsset integer := 1;',
'    l_src_offsset  integer := 1;',
'    l_lang_context integer := sys.dbms_lob.default_lang_ctx;',
'    l_warning      integer;',
'begin',
'    wwv_flow_collection.create_or_truncate_collection( ''APEX_4500_60'' );',
'    for c1 in ( select blob_content, file_charset',
'                from wwv_flow_files',
'                where id = :P60_FILE_ID ) loop',
'        sys.dbms_lob.createTemporary(lob_loc => l_clob,cache => false);',
'',
'        sys.dbms_lob.converttoclob(',
'            dest_lob     => l_clob,',
'            src_blob     => c1.blob_content,',
'            amount       => sys.dbms_lob.lobmaxsize,',
'            dest_offset  => l_dest_offsset,',
'            src_offset   => l_src_offsset,',
'            blob_csid    => nvl( nls_charset_id( wwv_flow_lang.map_db_charset( c1.file_charset ) ), sys.dbms_lob.default_csid ),',
'            lang_context => l_lang_context,',
'            warning      => l_warning',
'        );',
'        --if l_warning is null then',
'            wwv_flow_collection.add_member( p_collection_name => ''APEX_4500_60'',',
'                                        p_clob001         => l_clob );',
'        --end if;',
'    end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'PREPOPULATE'
,p_process_when_type=>'REQUEST_NOT_EQUAL_CONDITION'
,p_internal_uid=>657008053639142129.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(929194220744394206.4501)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'STORE_SCRIPT'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_code        clob := empty_clob;',
'    l_file_id     number := null;',
'    l_script_name varchar2(4000) := null;',
'begin    ',
'    sys.dbms_lob.createtemporary( l_code, false, sys.dbms_lob.SESSION );',
'',
'    htmldb_collection.create_or_truncate_collection(',
'        p_collection_name => ''SR_SCRIPT_SOURCE'');',
'',
'    for i in 1..wwv_flow.g_f01.count loop   	   ',
'        sys.dbms_lob.writeappend(l_code,length(wwv_flow.g_f01(i)),wwv_flow.g_f01(i));        ',
'    end loop;',
'',
'    l_file_id := wwv_flow_sw_script.array_element(wwv_flow.g_f02,1);',
'    if l_file_id is null then',
'      l_file_id := wwv_flow_id.next_val;',
'    end if;',
'    l_script_name := wwv_flow_sw_script.array_element(wwv_flow.g_f03,1);',
'',
'    htmldb_collection.add_member(',
'        p_collection_name => ''SR_SCRIPT_SOURCE'',',
'        p_c001            => l_file_id,',
'        p_c002            => l_script_name,',
'        p_clob001         => l_code);',
'',
'    sys.owa_util.status_line(204, ''No Content'');',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>929194220744394206.4501
);
end;
