'// get text from alert body and trim unnecessary \n and blanks  ',
'const lMessage = $("#autoconnect_message").text().replace(/^\s+|\s+$/g, ''''); ',
'',
'const lSpinner$ = apex.util.showSpinner($("body"),{alert:lMessage}),',
'    lRequest = new Request(apex.items.P64_EXCHANGE_URL.value, {',
'        method: ''POST'',',
'        headers: {',
'            ''Content-type'': ''application/x-www-form-urlencoded''',
'        },',
'        body: apex.items.P64_EXCHANGE_BODY.value',
'    }),',
'    lResponse = fetch(lRequest);',
'',
'lResponse.then(async (res) => {',
'    if (res.ok) {',
'        apex.navigation.openInNewWindow(res.url);',
'        apex.navigation.dialog.close(true);',
'        return Promise.resolve();',
'    } else {',
'        return Promise.reject(await new Response(res.body).json());',
'    }',
'}).catch((err) => {',
'    apex.message.showErrors([',
'        {',
'            type: "error",',
'            location: "page",',
'            message: err.message,',
'            techInfo: [{',
'                name: apex.lang.formatMessage( "SDW_ERROR_CAUSE" ),',
'                value: err.cause',
'            },',
'            {',
'                name: apex.lang.formatMessage( "SDW_ERROR_ACTION" ),',
'                value: err.action',
'            }],',
'            unsafe: true',
'        }',
'    ]);',
'}).finally((data) => {',
'    lSpinner$.remove();',
'});'))
);
