wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(223021505855686598.4501)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'add selected members to collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_f01  number := null;',
'  ',
'  function array_element( ',
'      p_vcarr in wwv_flow_global.vc_arr2,',
'      p_index in number )',
'      return varchar2',
'  is',
'      l_return_value varchar2(4000) := NULL;',
'  begin',
'      if p_vcarr is not null then',
'          l_return_value := substr(p_vcarr( p_index ), 1, 4000);',
'      end if;  ',
'      ',
'      return l_return_value;  ',
'  exception',
'      when others then',
'          return NULL;',
'  end;',
'begin',
'  for i in 1..wwv_flow.g_f02.count loop',
'  	l_f01 := array_element(wwv_flow.g_f01,i);',
'  	if l_f01 is not null then',
'      HTMLDB_COLLECTION.ADD_MEMBER(',
'       p_collection_name => ''SCRIPTS_TO_EXPORT'',',
'       p_n001          => wwv_flow.g_f02(l_f01),',
'       p_c002          => wwv_flow.g_f03(l_f01),',
'       p_c003          => wwv_flow.g_f04(l_f01));',
'    end if;',
'  end loop;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('No se han podido agregar los archivos de comandos seleccionados a la recopilaci\00F3n.')
,p_process_when_button_id=>wwv_flow_imp.id(221610015943050593.4501)
,p_internal_uid=>223021505855686598.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(236921832183120045.4501)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'export script'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_user     varchar2(  255) := null;',
'    l_filename varchar2(32767) := null;',
'begin',
'    l_filename := nvl (',
'        :P65_FILE_NAME,',
'        wwv_flow.get_company_name(p_escape=>false)||''_script.sql'' );',
'',
'    sys.htp.init;',
'    wwv_flow.g_page_text_generated := true;',
'',
'    wwv_flow_utilities.print_download_header (',
'        p_mime_type     => ''application/text'',',
'        p_is_attachment => true,',
'        p_file_name     => l_filename );',
'',
'    sys.owa_util.http_header_close;',
'',
'    wwv_flow_gen_api2.export_script (',
'        p_commit => ''NO'' );',
'',
'    wwv_flow.g_page_text_generated := true;',
'    wwv_flow.g_unrecoverable_error := true;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'No se han podido exportar los archivos de comandos seleccionados.'
,p_process_when_button_id=>wwv_flow_imp.id(236922711190123460.4501)
,p_internal_uid=>236921832183120045.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(237315715588692488.4501)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'remove select script'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'select seq_id, n001 script_id, c002 script_name, c003 script_owner',
'from htmldb_collections ',
'where collection_name =''SCRIPTS_TO_EXPORT'') loop',
'',
'for i in 1..wwv_flow.g_f04.count loop',
'   if wwv_flow.g_f04(i) = c1.script_id then',
'      HTMLDB_COLLECTION.DELETE_MEMBER(',
'       p_collection_name => ''SCRIPTS_TO_EXPORT'',',
'       p_seq => c1.seq_ID);',
'   end if;',
'end loop;',
'',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'No se han podido eliminar los archivos de comandos seleccionados.'
,p_process_when_button_id=>wwv_flow_imp.id(237021909392643306.4501)
,p_process_success_message=>'Archivos de comandos seleccionados eliminados.'
,p_internal_uid=>237315715588692488.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(223020132259675341.4501)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create collection if needed'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'if not HTMLDB_COLLECTION.COLLECTION_EXISTS  (',
'  p_collection_name => ''SCRIPTS_TO_EXPORT'' ) then',
'  ',
'  HTMLDB_COLLECTION.CREATE_COLLECTION(',
'    p_collection_name => ''SCRIPTS_TO_EXPORT'' );',
'  ',
'end if;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('No se ha podido crear la recopilaci\00F3n.')
