,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'UpdateComment'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'    wwv_flow_sw_page_calls.update_comment(:p70_owner,:p70_table_name,:p70_table_comment);',
'    :P70_EDIT_IND := ''N'';',
'    :P70_TABLE_NAME := null;',
'    :P70_TABLE_COMMENT := null;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error al actualizar comentarios.'
,p_process_when_button_id=>wwv_flow_imp.id(460471930670643180.4501)
,p_process_success_message=>'Comentario actualizado.'
,p_internal_uid=>460475408127643226.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(460476012661643231.4501)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'LoadTableComment'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_names  wwv_flow_dynamic_exec.vc_arr2;',
'    l_values wwv_flow_dynamic_exec.vc_arr2;',
'begin',
'    l_names(1)  := ''OWNER'';',
'    l_values(1) := nvl(:P70_OWNER, wwv_flow_user_api.get_default_schema);',
'    l_names(2)  := ''TABLE_NAME'';',
'    l_values(2) := :P70_TABLE_NAME;',
'    ',
'    wwv_flow_sw_api.check_priv(l_values(1));',
'',
'    wwv_flow_code_exec.execute (',
'        p_code => q''{',
'begin',
'    for c1 in (',
'    select comments',
'      from sys.all_tab_comments',
'     where table_name = :TABLE_NAME',
'       and owner      = :OWNER )',
'    loop',
'       :P70_TABLE_COMMENT := c1.comments;',
'    end loop;',
'end;}'',',
'    p_language        => wwv_flow_code_exec.c_plsql,',
'    p_names           => l_names,',
'    p_values          => l_values,',
'    p_parse_as_schema => :P70_OWNER );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'Error al cargar comentarios.'
,p_internal_uid=>460476012661643231.4501
);
end;
