,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set p115_compatible'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_version varchar2(4000) := null;',
'begin',
'    l_version := wwv_flow_imp_parser.get_version(p_file_id=>:P115_FILE_ID);',
'    if l_version is not null then',
'        :P115_COMPATIBLE := ''Y'';',
'    else',
'        :P115_COMPATIBLE := ''N'';',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'No se ha podido comprobar la compatibilidad.'
,p_internal_uid=>241344730948793602.4501
);
