wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(367602808298431816.4501)
,p_name=>'Tables and Views'
,p_display_sequence=>22
,p_component_template_options=>'#DEFAULT#'
,p_new_grid_row=>false
,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.owner,',
'       t.table_name,',
'       t.column_name,',
'       t.data_type,',
'       decode (',
'           t.data_precision,',
'           null,',
'           decode (',
'               t.data_type,',
'               ''CHAR'',      t.char_length,',
'               ''NCHAR'',     t.char_length,',
'               ''VARCHAR'',   t.char_length,',
'               ''VARCHAR2'',  t.char_length,',
'               ''NVARCHAR2'', t.char_length,',
'               t.data_length ),',
'               decode (',
'                   t.data_type,',
'                   ''NUMBER'',',
'                   null,',
'                   t.data_precision ) ) as data_length,',
'       t.data_precision,',
'       t.data_scale,',
'       cons.position pk,',
'       decode(t.nullable,''Y'',''<img src="#IMAGE_PREFIX#check_small_black.gif" border="0" height="15" width="15" alt="''||wwv_flow_lang.system_message(''F4500.NULLABLE'')||''" />'',null) nullable,',
'       t.data_default,',
'       t.column_id,',
'       c.comments comments',
'  from sys.all_tab_columns t,',
'       sys.all_col_comments c,',
'       ( select cl.column_name, cl.position',
'             from sys.all_cons_columns cl,',
'                  sys.all_constraints cn',
'            where cn.owner           = replace(trim(:P139_OWNER),''"'')',
'              and cn.table_name      = replace(trim(:P139_OBJECT),''"'')',
'              and cn.constraint_type = ''P''',
'              and cl.owner           = cn.owner',
'              and cl.table_name      = cn.table_name',
'              and cl.constraint_name = cn.constraint_name',
'        ) cons',
' where t.column_name = c.column_name',
'   and c.table_name  = t.table_name',
'   and c.owner       = t.owner',
'   and t.table_name  = replace(trim(:P139_OBJECT),''"'')',
'   and t.owner       = replace(trim(:P139_OWNER),''"'')',
'   and t.column_name = cons.column_name (+)',
' order by t.column_id'))
,p_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
':P139_TYPE in (''TABLE'',''VIEW'') and',
'(:P139_OBJECT is not null)'))
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_translate_title=>'N'
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
