 p_id=>wwv_flow_imp.id(499410144971419.4501)
,p_name=>'Columnas de Tabla'
,p_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_display_sequence=>50
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select t.column_name,',
'         initcap(t.data_type) data_type,',
'         decode(t.data_type,''NUMBER'',null,t.data_length) data_length,',
'         t.data_precision,',
'         t.data_scale,',
'         wwv_flow_sw_util.get_pk_position (t.owner,t.table_name,t.column_name) pk,',
'decode(t.nullable,''Y'',''<span class="a-Icon icon-check"></span>'',null) nullable,',
'         t.data_default,',
'         t.column_id,',
'         substr(c.comments,1,3000) comments',
'from sys.dba_tab_columns t, sys.dba_col_comments c',
'where t.column_name = c.column_name               ',
