wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(574207624732252.4501)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'purge object'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_base_object number;',
'    l_msg         varchar2(32767);',
'begin',
'select base_object into l_base_object ',
'  from sys.dba_recyclebin',
' where purge_object = :P401_OBJECT_ID;',
'',
'',
'for c1 in (',
'     select owner, object_name, type',
'     from sys.dba_recyclebin',
'     where purge_object = l_base_object ',
') loop',
'    l_msg := wwv_flow_sw_page_calls.purge_object(c1.object_name,c1.owner,c1.type);',
'end loop;',
'',
'if l_msg <> ''SUCCESS'' then',
'        raise_application_error( -20999, l_msg );',
'end if;',
'',
'--:P402_MSG := wwv_flow_sw_page_calls.purge_object(l_owner,:P401_OBJECT_OWNER,:P401_OBJECT_TYPE);',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(572503684721678.4501)
,p_process_when=>'P401_CAN_PURGE'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'YES'
,p_process_success_message=>'El objeto se ha depurado correctamente.'
,p_internal_uid=>574207624732252.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(615905115450652.4501)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'restore object'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_base_object number;',
'    l_msg         varchar2(32767);',
'begin',
'  select base_object into l_base_object ',
'    from sys.dba_recyclebin',
'   where purge_object = :P401_OBJECT_ID',
'     and can_undrop = ''YES'';',
'',
'',
'  for c1 in (',
'     select owner, object_name, type',
'     from sys.dba_recyclebin',
'     where purge_object = l_base_object ',
'  )loop',
'    l_msg := wwv_flow_sw_page_calls.restore_object(c1.object_name,c1.owner,c1.type);',
'  end loop;',
'',
'  if l_msg <> ''SUCCESS'' then',
'      raise_application_error( -20999, l_msg );',
'  end if;',
'',
'--:P402_MSG := wwv_flow_sw_page_calls.restore_object(:P401_OBJECT_NAME,:P401_OBJECT_OWNER,:P401_OBJECT_TYPE);',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'#SQLERRM_TEXT#'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(612020877142921.4501)
,p_process_when=>'P401_CAN_UNDROP'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'YES'
,p_process_success_message=>'El objeto se ha restaurado correctamente.'
,p_internal_uid=>615905115450652.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(46245924599042376.4501)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set values based on object id'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'     select owner, object_name, type, can_undrop, can_purge',
'     from sys.dba_recyclebin',
'     where purge_object = :P401_OBJECT_ID',
') loop',
'     :P401_OBJECT_OWNER := c1.owner;',
'     :P401_OBJECT_NAME  := c1.object_name;',
'     :P401_OBJECT_TYPE  := c1.type;',
'     :P401_CAN_UNDROP   := c1.can_undrop;',
'     :P401_CAN_PURGE    := c1.can_purge;',
'end loop; ',
'',
'wwv_flow_sw_api.check_priv ( p_schema => :P401_OBJECT_OWNER );'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>46245924599042376.4501
);
end;
