wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(159560000024320866.4501)
,p_name=>'Consulta de Sesiones'
,p_template=>wwv_flow_imp.id(385770331595976651.4501)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with my_s as (select sid, inst_id from sys.gv_$mystat where rownum = 1), ',
'vs as (select inst_id, rownum rnum,sid,status,username,last_call_et,',
'              command,machine,osuser,module,action,resource_consumer_group,',
'              client_info,client_identifier,type,terminal',
'         from sys.gv_$session) ',
' select case when (select sid from my_s where rownum = 1) = vs.sid then  ',
'                  ''C'' ',
'             when vs.status = ''ACTIVE'' then ',
'                  case when last_call_et > 30  ',
'                       then ''L'' ',
'                       else ''A'' ',
'                  end ',
'             when  vs.status = ''INACTIVE'' ',
'                       then ''I'' ',
'            else null ',
'        end session_status, vs.sid,',
'        vs.username,',
'        case when vs.status = ''ACTIVE'' ',
'                  then last_call_et ',
'             else null end seconds_in_wait,',
'        decode(vs.command,  ',
'         0,null, ',
'         1,''CRE TAB'', ',
'         2,''INSERT'', ',
'         3,''SELECT'', ',
'         4,''CRE CLUSTER'', ',
'         5,''ALT CLUSTER'', ',
'         6,''UPDATE'', ',
'         7,''DELETE'', ',
'         8,''DRP CLUSTER'', ',
'         9,''CRE INDEX'', ',
'         10,''DROP INDEX'', ',
'         11,''ALT INDEX'', ',
'         12,''DROP TABLE'', ',
'         13,''CRE SEQ'', ',
'         14,''ALT SEQ'', ',
'         15,''ALT TABLE'', ',
'         16,''DROP SEQ'', ',
'         17,''GRANT'', ',
'         18,''REVOKE'', ',
'         19,''CRE SYN'', ',
'         20,''DROP SYN'', ',
'         21,''CRE VIEW'', ',
'         22,''DROP VIEW'', ',
'         23,''VAL INDEX'', ',
'         24,''CRE PROC'', ',
'         25,''ALT PROC'', ',
'         26,''LOCK TABLE'', ',
'         28,''RENAME'', ',
'         29,''COMMENT'', ',
'         30,''AUDIT'', ',
'         31,''NOAUDIT'', ',
'         32,''CRE DBLINK'', ',
'         33,''DROP DBLINK'', ',
'         34,''CRE DB'', ',
'         35,''ALTER DB'', ',
'         36,''CRE RBS'', ',
'         37,''ALT RBS'', ',
'         38,''DROP RBS'', ',
'         39,''CRE TBLSPC'', ',
'         40,''ALT TBLSPC'', ',
'         41,''DROP TBLSPC'', ',
'         42,''ALT SESSION'', ',
'         43,''ALT USER'', ',
'         44,''COMMIT'', ',
'         45,''ROLLBACK'', ',
'         46,''SAVEPOINT'', ',
'         47,''PL/SQL EXEC'', ',
'         48,''SET XACTN'', ',
'         49,''SWITCH LOG'', ',
'         50,''EXPLAIN'', ',
'         51,''CRE USER'', ',
'         52,''CRE ROLE'', ',
'         53,''DROP USER'', ',
'         54,''DROP ROLE'', ',
'         55,''SET ROLE'', ',
'         56,''CRE SCHEMA'', ',
'         57,''CRE CTLFILE'', ',
'         58,''ALTER TRACING'', ',
'         59,''CRE TRIGGER'', ',
'         60,''ALT TRIGGER'', ',
'         61,''DRP TRIGGER'', ',
'         62,''ANALYZE TAB'', ',
'         63,''ANALYZE IX'', ',
'         64,''ANALYZE CLUS'', ',
'         65,''CRE PROFILE'', ',
'         66,''DRP PROFILE'', ',
'         67,''ALT PROFILE'', ',
'         68,''DRP PROC'', ',
'         69,''DRP PROC'', ',
'         70,''ALT RESOURCE'', ',
'         71,''CRE SNPLOG'', ',
'         72,''ALT SNPLOG'', ',
'         73,''DROP SNPLOG'', ',
'         74,''CREATE SNAP'', ',
'         75,''ALT SNAP'', ',
'         76,''DROP SNAP'', ',
'         79,''ALTER ROLE'', ',
'         79,''ALTER ROLE'', ',
'         85,''TRUNC TAB'', ',
'         86,''TRUNC CLUST'', ',
'         88,''ALT VIEW'', ',
'         91,''CRE FUNC'', ',
'         92,''ALT FUNC'', ',
'         93,''DROP FUNC'', ',
'         94,''CRE PKG'', ',
'         95,''ALT PKG'', ',
'         96,''DROP PKG'', ',
'         97,''CRE PKG BODY'', ',
'         98,''ALT PKG BODY'', ',
'         99,''DRP PKG BODY'', ',
'         to_char(vs.command)) command,',
'        case when length(vs.machine) > 15 then substr(vs.machine,1,15)||''...''  ',
'             else lower(vs.machine) end machine,',
'        vs.machine machine2,',
'        vs.osuser, ',
'        initcap(vs.status) status,',
'        case when length(vs.module) > 15 then substr(vs.module,1,15)||''...''',
'             else vs.module end module,',
'        vs.module module2,',
'        case when length(vs.action) > 15 then substr(vs.action,1,15)||''...'' ',
'             else vs.action end action,',
'        vs.action action2,',
'        vs.resource_consumer_group,vs.client_info,vs.client_identifier,',
'         -- 10g only blocking_session,',
'        vs.inst_id',
'   from vs ',
'  where vs.USERNAME is not null',
'    and nvl(vs.osuser,''x'') <> ''SYSTEM''',
'    and vs.type <> ''BACKGROUND''',
'    and (:P540_STATUS = ''ALL'' or (:P540_STATUS = ''ACTIVE'' and vs.status = ''ACTIVE''))',
'    and (:P540_SEARCH is null',
'        or',
'        (:P540_SEARCH is not null',
'         and',
'            (vs.username like ''%''||upper(:P540_SEARCH)||''%'' ',
'             or ',
'             upper(vs.osuser) like ''%''||upper(:P540_SEARCH)||''%'' ',
'             or ',
'             upper(vs.machine) like ''%''||upper(:P540_SEARCH)||''%'' ',
'             or ',
'             upper(vs.module) like ''%''||upper(:P540_SEARCH)||''%'' ',
'             or ',
'             upper(vs.client_info) like ''%''||upper(:P540_SEARCH)||''%'' ',
'             or ',
'             upper(vs.client_identifier) like ''%''||upper(:P540_SEARCH)||''%'' ',
'             or',
'             to_char(vs.sid) = :P540_SEARCH',
'            )',
'         )',
'    )',
'   '))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>unistr('No se ha encontrado ninguna sesi\00F3n')
,p_query_num_rows_item=>'P540_ROWS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>10000
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'Y'
);
