wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(201909305328005313.4501)
,p_name=>'Session Locks'
,p_template=>wwv_flow_imp.id(385770331595976651.4501)
,p_display_sequence=>15
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with locks as(',
'    select session_id,lock_type,',
'           mode_held,mode_requested,lock_id1,lock_id2,blocking_others',
'      from sys.dba_lock),',
'waiters as (',
'    select w.session_id waiting_session,',
'            h.session_id holding_session,',
'            w.lock_type lock_type,',
'            h.mode_held mode_held,',
'            w.mode_requested mode_requested,',
'            w.lock_id1,',
'            w.lock_id2',
'      from locks w, locks h',
'     where h.blocking_others =  ''Blocking''',
'      and  h.mode_held      !=  ''None''',
'      and  h.mode_held      !=  ''Null''',
'      and  w.mode_requested !=  ''None''',
'      and  w.lock_type       =  h.lock_type',
'      and  w.lock_id1        =  h.lock_id1',
'      and  w.lock_id2        =  h.lock_id2),',
'blockers as(',
'    select holding_session waiting_session, to_number(null) holding_session,',
'           ''None'' lock_type, null mode_held, null mode_requested,',
'           null lock_id1, null lock_id2',
'      from waiters',
'     minus',
'    select waiting_session waiting_session, to_number(null) holding_session,',
'           ''None'' lock_type, null mode_held, null mode_requested,',
'           null lock_id1, null lock_id2',
'      from waiters),',
'waiters_blockers as(',
'    select waiting_session,holding_session,lock_type,mode_held,mode_requested,lock_id1,lock_id2',
'      from waiters',
'     union all',
'    select waiting_session,holding_session,lock_type,mode_held,mode_requested,lock_id1,lock_id2',
'      from blockers),',
'lock_objects as(',
'    select session_id,cnt lock_obj_count,',
'           case when cnt = 1 then object_name',
'                else null end object_name,',
'           object_id,owner,object_type',
'      from(',
'        select session_id,count(distinct object_name) cnt,max(object_name) object_name,',
'               max(lo.object_id) object_id, max(ao.owner) owner,max(object_type) object_type',
'          from sys.gv_$locked_object lo,sys.dba_objects ao',
'         where lo.object_id = ao.object_id',
'         group by session_id)),',
'wait_block_ses as(',
'select waiting_session,holding_session,lock_type,mode_held,mode_requested,',
'       s.username,s.osuser,s.CLIENT_INFO,s.CLIENT_IDENTIFIER,o.object_name,o.owner,o.object_id,module,o.object_type,o.lock_obj_count,s.inst_id,',
'        decode(s.command,',
'         0,null,',
'         1,''CRE TAB'',',
'         2,''INSERT'',',
'         3,''SELECT'',',
'         4,''CRE CLUSTER'',',
'         5,''ALT CLUSTER'',',
'         6,''UPDATE'',',
'         7,''DELETE'',',
'         8,''DRP CLUSTER'',',
'         9,''CRE INDEX'',',
'         10,''DROP INDEX'',',
'         11,''ALT INDEX'',',
'         12,''DROP TABLE'',',
'         13,''CRE SEQ'',',
'         14,''ALT SEQ'',',
'         15,''ALT TABLE'',',
'         16,''DROP SEQ'',',
'         17,''GRANT'',',
'         18,''REVOKE'',',
'         19,''CRE SYN'',',
'         20,''DROP SYN'',',
'         21,''CRE VIEW'',',
'         22,''DROP VIEW'',',
'         23,''VAL INDEX'',',
'         24,''CRE PROC'',',
'         25,''ALT PROC'',',
'         26,''LOCK TABLE'',',
'         28,''RENAME'',',
'         29,''COMMENT'',',
'         30,''AUDIT'',',
'         31,''NOAUDIT'',',
'         32,''CRE DBLINK'',',
'         33,''DROP DBLINK'',',
'         34,''CRE DB'',',
'         35,''ALTER DB'',',
'         36,''CRE RBS'',',
'         37,''ALT RBS'',',
'         38,''DROP RBS'',',
'         39,''CRE TBLSPC'',',
'         40,''ALT TBLSPC'',',
'         41,''DROP TBLSPC'',',
'         42,''ALT SESSION'',',
'         43,''ALT USER'',',
'         44,''COMMIT'',',
'         45,''ROLLBACK'',',
'         46,''SAVEPOINT'',',
'         47,''PL/SQL EXEC'',',
'         48,''SET XACTN'',',
'         49,''SWITCH LOG'',',
'         50,''EXPLAIN'',',
'         51,''CRE USER'',',
'         52,''CRE ROLE'',',
'         53,''DROP USER'',',
'         54,''DROP ROLE'',',
'         55,''SET ROLE'',',
'         56,''CRE SCHEMA'',',
'         57,''CRE CTLFILE'',',
'         58,''ALTER TRACING'',',
'         59,''CRE TRIGGER'',',
'         60,''ALT TRIGGER'',',
'         61,''DRP TRIGGER'',',
'         62,''ANALYZE TAB'',',
'         63,''ANALYZE IX'',',
'         64,''ANALYZE CLUS'',',
'         65,''CRE PROFILE'',',
'         66,''DRP PROFILE'',',
'         67,''ALT PROFILE'',',
'         68,''DRP PROC'',',
'         69,''DRP PROC'',',
'         70,''ALT RESOURCE'',',
'         71,''CRE SNPLOG'',',
'         72,''ALT SNPLOG'',',
'         73,''DROP SNPLOG'',',
'         74,''CREATE SNAP'',',
'         75,''ALT SNAP'',',
'         76,''DROP SNAP'',',
'         79,''ALTER ROLE'',',
'         79,''ALTER ROLE'',',
'         85,''TRUNC TAB'',',
'         86,''TRUNC CLUST'',',
'         88,''ALT VIEW'',',
'         91,''CRE FUNC'',',
'         92,''ALT FUNC'',',
'         93,''DROP FUNC'',',
'         94,''CRE PKG'',',
'         95,''ALT PKG'',',
'         96,''DROP PKG'',',
'         97,''CRE PKG BODY'',',
'         98,''ALT PKG BODY'',',
'         99,''DRP PKG BODY'',',
'         to_char(s.command)) command',
'  from waiters_blockers wb, sys.gv_$session s,',
'       lock_objects o',
' where s.sid = wb.waiting_session',
'   and o.session_id(+) = wb.waiting_session',
'  ),',
'ws_schemas as(',
'    select schema',
'      from wwv_flow_company_schemas',
'     where security_group_id = :flow_security_group_id)',
'select  case when holding_session is null then ''B''',
'             else ''D''',
'       end session_status,',
'       decode(level,1,1,power(level*3,2)) padding,',
'       level lvl,',
'       waiting_session,',
'       holding_session,',
'       username,',
'       osuser,',
'       client_info,',
'       client_identifier,',
'       inst_id,',
'       case when lock_obj_count = 1 then',
'            case when owner in (select schema from ws_schemas) then',
'                ''<a href="''||wwv_flow_page_api.get_url(',
'                                 p_page        => 2000,',
'                                 p_clear_cache => ''RP,2000'',',
'                                 p_items       => ''P2000_OB_INIT_SCHEMA,P2000_OB_INIT_ID'',',
'                                 p_values      => owner||'',''||object_id )||''">''||object_name||''</a>''',
'            else object_name end',
'        else ''<br />'' end object_name,',
'       object_id,owner,module,object_type',
'  from wait_block_ses',
' start with holding_session is null',
' connect by prior waiting_session = holding_session'))
,p_translate_title=>'N'
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>' - '
,p_query_no_data_found=>unistr('No existe ning\00FAn bloqueo')
,p_query_num_rows_item=>'P541_ROWS'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_query_row_count_max=>5000
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'Y'
);
