,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with my_s as (select sid from sys.gv_$mystat where rownum = 1), ',
'vs as (select * from sys.gv_$session),',
'oc as (select sid, inst_id, count(*) open_cursors from sys.gv_$open_cursor group by sid, inst_id)',
' select case when (select sid from my_s where rownum = 1) = vs.sid then  ',
'                  ''C'' ',
'             when vs.status = ''ACTIVE'' then ',
'                  case when last_call_et > 30  ',
'                       then ''L'' ',
'                       else ''A'' ',
'                  end ',
'             when  vs.status = ''INACTIVE'' ',
'                       then ''I'' ',
'            else null ',
'        end session_status, ',
'        vs.sid, oc.open_cursors, vs.username, vs.inst_id',
'   from vs, oc',
'  where vs.sid = oc.sid',
'    and vs.inst_id = oc.inst_id',
'    and vs.USERNAME > ''!''',
'    and nvl(vs.osuser,''x'') <> ''SYSTEM''',
'    and vs.type <> ''BACKGROUND''',
'    and (:P543_STATUS = ''ALL'' or (:P543_STATUS = ''ACTIVE'' and vs.status = ''ACTIVE''))',
'    and (:P543_SEARCH is null',
'        or',
'        (:P543_SEARCH is not null',
'         and',
'            (vs.username like ''%''||upper(:P543_SEARCH)||''%'' ',
'             or ',
'             upper(vs.osuser) like ''%''||upper(:P543_SEARCH)||''%'' ',
'             or ',
'             upper(vs.terminal) like ''%''||upper(:P543_SEARCH)||''%'' ',
'             or ',
'             upper(vs.module) like ''%''||upper(:P543_SEARCH)||''%'' ',
'             or ',
'             upper(vs.client_info) like ''%''||upper(:P543_SEARCH)||''%'' ',
'             or ',
'             upper(vs.sid) like ''%''||upper(:P543_SEARCH)||''%'' ',
'            )',
'         )',
'        )'))
