'         99,''DRP PKG BODY'', ',
'         to_char(vs.command)) command,',
'        block_gets, consistent_gets, physical_reads, block_changes, consistent_changes',
'   from vs,io_s',
'  where io_s.sid = vs.sid',
'    and io_s.inst_id = vs.inst_id',
'    and vs.USERNAME > ''!''',
'    and nvl(vs.osuser,''x'') <> ''SYSTEM''',
'    and vs.type <> ''BACKGROUND''',
'    and (:P545_SEARCH is null',
'        or',
'        (:P545_SEARCH is not null',
'         and',
'            (vs.username like ''%''||upper(:P545_SEARCH)||''%'' ',
'             or ',
'             upper(vs.osuser) like ''%''||upper(:P545_SEARCH)||''%'' ',
'             or ',
'             upper(vs.terminal) like ''%''||upper(:P545_SEARCH)||''%'' ',
