begin
wwv_flow_imp_page.create_page(
 p_id=>548.4501
,p_name=>'Eventos de Espera'
,p_alias=>'WAIT-EVENTS'
,p_step_title=>'Esperas'
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_first_item=>'AUTO_FIRST_ITEM'
,p_autocomplete_on_off=>'ON'
,p_group_id=>wwv_flow_imp.id(206250111084432914)
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'table.waitsColumn{border:0px;}',
'table.waitsColumn th{background:#efefef;border:0px;padding:0px 5px 0px 0px;text-align:right;}',
'table.waitsColumn td{border:0px;padding:1px;white-space:nowrap;font-weight:bold;}',
'table.waitsColumn td.l{text-align:right;font-weight:normal;padding-right:5px;}'))
,p_step_template=>wwv_flow_imp.id(690783685471803190.4501)
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(206059717799303330)
,p_required_patch=>wwv_flow_imp.id(140265918963157648.4501)
,p_nav_list_template_options=>'#DEFAULT#'
,p_help_text=>'AEUTL/dbadm_sessions.htm'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(164313818540444573.4501)
,p_name=>'Eventos de Espera'
,p_template=>wwv_flow_imp.id(385770331595976651.4501)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with my_s as (select sid from sys.gv_$mystat where rownum = 1),',
'wait_obj as (select s1.sid,d1.owner||''.''||d1.object_name obj_name,s1.row_wait_obj#,d1.object_id,d1.data_object_id,d1.object_name,d1.owner object_owner,',
'                    d1.object_type',
'               from sys.gv_$session s1,sys.dba_objects d1',
'              where s1.row_wait_obj# = d1.object_id',
'                and s1.wait_time = 0',
'                and s1.wait_class != ''Idle''),',
'ws_schemas as(',
'    select schema ',
'      from wwv_flow_company_schemas',
'     where security_group_id = :flow_security_group_id)',
'select case when (select sid from my_s where rownum = 1) = s.sid then  ',
'                  ''C'' ',
'             when s.status = ''ACTIVE'' then ',
'                  case when sw.seconds_in_wait > 30  ',
'                       then ''L'' ',
'                       else ''A'' ',
'                  end ',
'             when  s.status = ''INACTIVE'' ',
'                       then ''I'' ',
'            else null ',
'        end session_status,',
'       s.sid,s.username,sw.event, decode(sw.wait_time,0,''W'',''C'') waiting,',
'       sw.wait_time, sw.state,sw.seconds_in_wait,s.status,s.module,s.client_info,',
'       case when o.object_type in (''TABLE'',''VIEW'',''INDEX'',''MATERIALIZED VIEW'') then',
'            case when o.object_owner in  (select schema from ws_schemas)',
'                 then ''<a href="''||wwv_flow_page_api.get_url(',
'                                 p_page        => 2000,',
'                                 p_clear_cache => ''RP,2000'',',
'                                 p_items       => ''P2000_OB_INIT_SCHEMA,P2000_OB_INIT_ID'',',
'                                 p_values      => o.object_owner||'',''||o.object_id )||''">''||wwv_flow_escape.html(o.object_name)||''</a>'' ',
'                 else wwv_flow_escape.html(o.object_name) end',
'            else wwv_flow_escape.html(object_name) end object_name,',
'       sw.p1text,sw.p1,sw.p2text,sw.p2,sw.p3text,sw.p3,sw.wait_class,',
'       s.inst_id,',
'       null dummy',
'  from sys.gv_$session s, sys.gv_$session_wait sw, wait_obj o',
' where s.sid = sw.sid',
'   and s.inst_id = sw.inst_id',
'   and s.sid = o.sid(+)',
'   and s.username is not null',
'   and nvl(s.osuser,''x'') <> ''SYSTEM''',
'   and s.type <> ''BACKGROUND''',
'   and (:P548_ACTIVE = ''ALL'' or s.status = ''ACTIVE'')',
'   and (:P548_SEARCH is null',
'        or',
'        (:P548_SEARCH is not null',
'         and',
'            (s.username like ''%''||upper(:P548_SEARCH)||''%'' ',
'             or ',
'             upper(s.module) like ''%''||upper(:P548_SEARCH)||''%'' ',
'             or ',
'             upper(s.client_info) like ''%''||upper(:P548_SEARCH)||''%''              ',
'             or',
'             to_char(s.sid) = :P548_SEARCH',
'            )',
'         )',
'    )'))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_options=>'DERIVED_REPORT_COLUMNS'
