'           where s.sid = :P550_SID',
'             and s.inst_id = :P550_INST_ID',
'             and exists (select 1 ',
'                           from sys.gv_$sql_plan p',
'                          where s.SQL_ADDRESS = p.address',
'                            and s.SQL_HASH_VALUE = p.hash_value',
'                            and s.SQL_CHILD_NUMBER = p.child_number',
'                            and s.inst_id = p.inst_id)',
'          )',
'loop',
'    sys.htp.p(''<a href="f?p=&APP_ID.:551:''||',
'      :APP_SESSION||',
'      ''::::P551_ADDRESS,P551_HASH_VALUE,P551_CHILD_NUMBER,P551_INST_ID:''||',
'      c1.SQL_ADDRESS||'',''||c1.SQL_HASH_VALUE||'',''||',
'      c1.SQL_CHILD_NUMBER||'',''||c1.inst_id||''">''||',
'      wwv_flow_lang.system_message(''Explain Plan'')||''</a>'');',
'    exit;',
'end loop;',
'',
'',
'for c1 in(select replace(q.sql_fulltext,chr(0)) sql_text',
'            from sys.gv_$session s, sys.gv_$sql q',
'           where s.sql_address = q.address',
'             and s.sql_hash_value = q.hash_value',
'             and s.SQL_CHILD_NUMBER = q.child_number',
'             and s.inst_id = q.inst_id',
'             and s.inst_id = :P550_INST_ID',
'             and s.sid = :P550_SID)',
'loop',
'    c := c+ 1;',
'    sys.htp.prn(''<div class="u-fixedFont" style="white-space: pre-wrap">'');',
'    sys.htp.prn(replace(wwv_flow_escape.html(c1.sql_text),chr(10),''<br />''));',
'    sys.htp.prn(''</div>'');',
'',
'end loop;',
'',
'',
'if c = 0 then',
'    sys.htp.prn(''<span class="fieldData">''||wwv_flow_lang.system_message(''SQL not available'')||''</span>'');',
'end if;',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_plug_comment=>'10g+ Version'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(161382425489157968.4501)
,p_name=>unistr('Contenci\00F3n (Bloqueos)')
,p_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_display_sequence=>90
,p_region_template_options=>'#DEFAULT#:a-Region--shadowScroll:a-Region--noPadding:h320'
,p_component_template_options=>'#DEFAULT#'
,p_new_grid_row=>false
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with locks as(',
'    select session_id,lock_type,',
'           mode_held,mode_requested,lock_id1,lock_id2,blocking_others',
'      from sys.dba_lock),',
'waiters as (',
'    select w.session_id waiting_session,',
'            h.session_id holding_session,',
'            w.lock_type lock_type,',
'            h.mode_held mode_held,',
'            w.mode_requested mode_requested,',
'            w.lock_id1,',
'            w.lock_id2',
'      from locks w, locks h',
'     where h.blocking_others =  ''Blocking''',
'      and  h.mode_held      !=  ''None''',
'      and  h.mode_held      !=  ''Null''',
'      and  w.mode_requested !=  ''None''',
'      and  w.lock_type       =  h.lock_type',
'      and  w.lock_id1        =  h.lock_id1',
'      and  w.lock_id2        =  h.lock_id2',
'      and  (w.session_id = :P550_SID',
'            or',
'            h.session_id = :P550_SID)),',
'blockers as(',
'    select holding_session waiting_session, to_number(null) holding_session, ',
'           ''None'' lock_type, null mode_held, null mode_requested, ',
'           null lock_id1, null lock_id2',
'      from waiters',
'     minus',
'    select waiting_session waiting_session, to_number(null) holding_session, ',
'           ''None'' lock_type, null mode_held, null mode_requested, ',
'           null lock_id1, null lock_id2',
'      from waiters),',
'waiters_blockers as(',
'    select waiting_session,holding_session,lock_type,mode_held,mode_requested,lock_id1,lock_id2',
'      from waiters',
'     union all',
'    select waiting_session,holding_session,lock_type,mode_held,mode_requested,lock_id1,lock_id2',
'      from blockers),',
'lock_objects as(',
'    select session_id,cnt lock_obj_count, inst_id,',
'           case when cnt = 1 then object_name',
'                else null end object_name,',
'           object_id,owner,object_type',
'      from(',
'        select session_id,inst_id,count(distinct object_name) cnt,max(object_name) object_name,',
'               max(lo.object_id) object_id, max(ao.owner) owner,max(object_type) object_type',
'          from sys.gv_$locked_object lo,sys.dba_objects ao,waiters_blockers wb',
'         where lo.object_id = ao.object_id',
'           and (wb.waiting_session = lo.session_id',
'                or',
'                wb.holding_session = lo.session_id)',
'         group by session_id, inst_id)),',
'wait_block_ses as(',
'select waiting_session,holding_session,lock_type,mode_held,mode_requested,',
'       s.username,s.osuser,s.CLIENT_INFO,s.CLIENT_IDENTIFIER,o.object_name,o.owner,o.object_id,module,o.object_type,o.lock_obj_count,',
'        decode(s.command,  ',
'         0,null, ',
'         1,''CRE TAB'', ',
'         2,''INSERT'', ',
'         3,''SELECT'', ',
'         4,''CRE CLUSTER'', ',
'         5,''ALT CLUSTER'', ',
'         6,''UPDATE'', ',
'         7,''DELETE'', ',
'         8,''DRP CLUSTER'', ',
'         9,''CRE INDEX'', ',
'         10,''DROP INDEX'', ',
'         11,''ALT INDEX'', ',
'         12,''DROP TABLE'', ',
'         13,''CRE SEQ'', ',
'         14,''ALT SEQ'', ',
'         15,''ALT TABLE'', ',
'         16,''DROP SEQ'', ',
'         17,''GRANT'', ',
'         18,''REVOKE'', ',
'         19,''CRE SYN'', ',
'         20,''DROP SYN'', ',
'         21,''CRE VIEW'', ',
'         22,''DROP VIEW'', ',
'         23,''VAL INDEX'', ',
'         24,''CRE PROC'', ',
'         25,''ALT PROC'', ',
'         26,''LOCK TABLE'', ',
'         28,''RENAME'', ',
'         29,''COMMENT'', ',
'         30,''AUDIT'', ',
'         31,''NOAUDIT'', ',
'         32,''CRE DBLINK'', ',
'         33,''DROP DBLINK'', ',
'         34,''CRE DB'', ',
'         35,''ALTER DB'', ',
'         36,''CRE RBS'', ',
'         37,''ALT RBS'', ',
'         38,''DROP RBS'', ',
'         39,''CRE TBLSPC'', ',
'         40,''ALT TBLSPC'', ',
'         41,''DROP TBLSPC'', ',
'         42,''ALT SESSION'', ',
'         43,''ALT USER'', ',
'         44,''COMMIT'', ',
'         45,''ROLLBACK'', ',
'         46,''SAVEPOINT'', ',
'         47,''PL/SQL EXEC'', ',
'         48,''SET XACTN'', ',
'         49,''SWITCH LOG'', ',
'         50,''EXPLAIN'', ',
'         51,''CRE USER'', ',
'         52,''CRE ROLE'', ',
'         53,''DROP USER'', ',
'         54,''DROP ROLE'', ',
'         55,''SET ROLE'', ',
'         56,''CRE SCHEMA'', ',
'         57,''CRE CTLFILE'', ',
'         58,''ALTER TRACING'', ',
'         59,''CRE TRIGGER'', ',
'         60,''ALT TRIGGER'', ',
'         61,''DRP TRIGGER'', ',
'         62,''ANALYZE TAB'', ',
'         63,''ANALYZE IX'', ',
'         64,''ANALYZE CLUS'', ',
'         65,''CRE PROFILE'', ',
'         66,''DRP PROFILE'', ',
'         67,''ALT PROFILE'', ',
'         68,''DRP PROC'', ',
'         69,''DRP PROC'', ',
'         70,''ALT RESOURCE'', ',
'         71,''CRE SNPLOG'', ',
'         72,''ALT SNPLOG'', ',
'         73,''DROP SNPLOG'', ',
'         74,''CREATE SNAP'', ',
'         75,''ALT SNAP'', ',
'         76,''DROP SNAP'', ',
'         79,''ALTER ROLE'', ',
'         79,''ALTER ROLE'', ',
'         85,''TRUNC TAB'', ',
'         86,''TRUNC CLUST'', ',
'         88,''ALT VIEW'', ',
'         91,''CRE FUNC'', ',
'         92,''ALT FUNC'', ',
'         93,''DROP FUNC'', ',
'         94,''CRE PKG'', ',
'         95,''ALT PKG'', ',
'         96,''DROP PKG'', ',
'         97,''CRE PKG BODY'', ',
'         98,''ALT PKG BODY'', ',
'         99,''DRP PKG BODY'', ',
'         to_char(s.command)) command',
'  from waiters_blockers wb, sys.gv_$session s,',
'       lock_objects o',
' where s.sid = wb.waiting_session',
'   and s.inst_id = :P550_INST_ID',
'   and o.session_id(+) = wb.waiting_session',
'   and o.inst_id = s.inst_id',
'  ),',
'ws_schemas as(',
'select schema ',
'  from wwv_flow_company_schemas',
' where security_group_id = :flow_security_group_id)',
'select case when holding_session is null then ''<img src="#IMAGE_PREFIX#htmldb/sessions/locks.gif" />'' ',
'            else ''<span style="padding-left:''||power(2*level,2)||''px;"''||',
'                 ''><img src="#IMAGE_PREFIX#htmldb/sessions/lock_wait.gif" /></span>''',
'       end status_icon,',
'       waiting_session,',
'       username,',
'       case when lock_obj_count = 1 then',
'            case when owner in (select schema from ws_schemas) then',
'                ''<a href="''||wwv_flow_page_api.get_url(',
'                                 p_page        => 2000,',
'                                 p_clear_cache => ''RP,2000'',',
'                                 p_items       => ''P2000_OB_INIT_SCHEMA,P2000_OB_INIT_ID'',',
'                                 p_values      => owner||'',''||object_id )||''">''||wwv_flow_escape.html(object_name)||''</a>''',
'            else wwv_flow_escape.html(object_name) end',
'        else ''<br />'' end object_name,      ',
'       object_id,',
'       owner,',
'       object_type',
'  from wait_block_ses ',
' start with holding_session is null',
' connect by prior waiting_session =  holding_session'))
,p_customized=>'1'
,p_customized_name=>unistr('Contenci\00F3n')
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>' - '
,p_query_no_data_found=>unistr('No se ha encontrado ning\00FAn bloqueo')
,p_query_row_count_max=>500
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'Y'
);
