,p_nav_list_template_options=>'#DEFAULT#'
,p_help_text=>'AEUTL/dbadm_topsql.htm'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(160439524013199750.4501)
,p_name=>'Plan de Consulta'
,p_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody'
,p_component_template_options=>'#DEFAULT#'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with sqlplan as (',
'    select id,position,',
'           address,hash_value,child_number,operation,options,',
'           object_type,OBJECT#,object_name,object_owner,',
'           cost,cardinality,bytes,',
'           access_predicates,filter_predicates,time,parent_id,',
'           SEARCH_COLUMNS',
'      from sys.gv_$sql_plan',
'    where address =  :P551_ADDRESS',
'      and hash_value = :P551_HASH_VALUE',
'      and child_number = :P551_CHILD_NUMBER',
'      and inst_id = :P551_INST_ID),',
'ws_schemas as(',
'    select schema ',
'      from wwv_flow_company_schemas',
'     where security_group_id = :flow_security_group_id) ',
'select operation,options,',
'       case when object_type in (''TABLE'',''VIEW'',''INDEX'',''MATERIALIZED VIEW'',''INDEX (UNIQUE)'') then',
'            case when object_owner in (select schema from ws_schemas) then',
'                 ''<a href="''||wwv_flow_page_api.get_url(',
'                                  p_page        => 2000,',
'                                  p_clear_cache => ''RP,2000'',',
'                                  p_items       => ''P2000_OB_INIT_SCHEMA,P2000_OB_INIT_ID'',',
'                                  p_values      => object_owner||'',''||OBJECT# )||''">''||wwv_flow_escape.html(object_name)||''</a>''',
'            else wwv_flow_escape.html(object_name) end ',
'       else wwv_flow_escape.html(object_name) end object_name,',
'       cost,cardinality,bytes,',
'       decode(level,1,1,power(level,2)+15) padding,access_predicates,filter_predicates,TIME,',
'       case when object_type = ''TABLE'' then',
'            wwv_flow_session_mon.highlight_plan_ind_cols(object_owner,object_name,filter_predicates) ',
'       else wwv_flow_escape.html(replace(filter_predicates,''='','' = '')) end filter_predicates2,',
'       case when object_type = ''TABLE'' then',
'            wwv_flow_session_mon.highlight_plan_ind_cols(object_owner,object_name,access_predicates) ',
'       else wwv_flow_escape.html(replace(access_predicates,''='','' = '')) end access_predicates2',
'       ,SEARCH_COLUMNS,',
'       OBJECT# object_id,object_type',
'        from sqlplan s1',
'  start with (address =  :P551_ADDRESS',
'              and hash_value = :P551_HASH_VALUE',
'              and child_number = :P551_CHILD_NUMBER',
'              and id=0 )',
'connect by prior id = parent_id',
'        and prior address = address',
'        and prior hash_value = hash_value',
'        and prior child_number = child_number',
'order by id, position'))
,p_footer=>wwv_flow_string.join(wwv_flow_t_varchar2(
'* Las columnas no indexadas se muestran en rojo',
'<p><br /></p>'))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_num_rows=>10000
