wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(188648032216172463.4501)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate Top Items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    type local_arr is table of varchar2(50);',
'    keyWords local_arr;',
'    ',
'    function highlight_keywords(p_sql in varchar2)',
'    return varchar2',
'    is',
'        l_sql   varchar2(32767) := replace(p_sql,chr(0));',
'    begin',
'        keyWords := local_arr(''SELECT'',''FROM'',''WHERE'',''AND'',''OR'',''ORDER BY'',''WITH'',''BETWEEN'',',
'                              ''GROUP BY'',''HAVING'',''CONNECT BY'',''START WITH'',''PRIOR'',''EXISTS'',',
'                              ''NOT'',''IN'',',
'                              ''LIKE'',''CONTAINS'',''REGEXP_INSTR'',''REGEXP_LIKE'',''IS'',''NULL'');',
'        for i in keyWords.first..keyWords.last loop',
'            l_sql := replace(upper(l_sql),keyWords(i)||'' '',''<span class="highLight">''||keyWords(i)||''</span> '');',
'        end loop;--i',
'        return l_sql;',
'    end highlight_keywords;',
'begin',
'    ',
'    ',
'    for c1 in (select EXECUTIONS,',
'                      DISK_READS,',
'                      (CPU_TIME / 1000000) CPU_TIME,',
'                      BUFFER_GETS,',
'                      ROWS_PROCESSED,',
'                      case when ROWS_PROCESSED = 0 then null ',
'                           else (BUFFER_GETS / replace(ROWS_PROCESSED,0,1)) end GETS_PROCESSED,',
'                      case when EXECUTIONS = 0 then null ',
'                           else (BUFFER_GETS / replace(EXECUTIONS,0,1)) end GETS_EXECUTIONS,',
'                      sql_fulltext,',
'                      MODULE,ACTION',
'                 from sys.gv_$sql',
'                where address       = :P551_ADDRESS',
'                  and HASH_VALUE    = :P551_HASH_VALUE',
'                  and inst_id       = :P551_INST_ID',
'                  and CHILD_NUMBER  = :P551_CHILD_NUMBER)',
'    loop',
'        :P551_EXECUTIONS        := to_char(c1.EXECUTIONS,''999G999G999G999G999G999G999G990'');',
'        :P551_DISK_READS        := to_char(c1.DISK_READS,''999G999G999G999G999G999G999G990'');',
'        :P551_CPU_TIME          := to_char(c1.CPU_TIME,''999G999G999G999G999G999G999G990D0'');',
'        :P551_BUFFER_GETS       := to_char(c1.BUFFER_GETS,''999G999G999G999G999G999G999G990'');',
'        :P551_ROWS_PROCESSED    := to_char(c1.ROWS_PROCESSED,''999G999G999G999G999G999G999G990'');',
'        :P551_GETS_PROCESSED    := to_char(c1.GETS_PROCESSED,''999G999G999G999G999G999G999G990'');',
'        :P551_EFFICIENCY2       := to_char(c1.GETS_EXECUTIONS,''999G999G999G999G999G999G999G990'');',
'        :P551_SQL_TEXT          := substr(highlight_keywords(replace(wwv_flow_escape.html(sys.dbms_lob.substr(c1.sql_fulltext,3200,1)),chr(10),''<br />'')),1,32000);',
'        :P551_MODULE            := c1.module;',
'        :P551_ACTION            := c1.action;',
'',
'    end loop;--c1',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>188648032216172463.4501
);
end;
