wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(441195900047724309.4501)
,p_plug_name=>'Claves Ajenas no Indexadas'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690714020036152159.4501)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with',
'/*gather all referential constraints of interest, including their column lists*/',
'cons_cols as (',
'    select',
'        cons.owner,',
'        cons.table_name,',
'        cons.constraint_name,',
'        listagg(''"''||cols.column_name||''"'', '','') within group (order by cols.position) as columns',
'    from sys.user_constraints cons',
'    join sys.user_cons_columns cols',
'        on cols.owner = cons.owner',
'        and cols.constraint_name = cons.constraint_name',
'    where cons.constraint_type = ''R''',
'    and cons.table_name not like ''BIN$%''',
'    and cons.table_name not like ''DR$%''',
'    and cons.table_name not like ''APEX$%''',
'    group by',
'        cons.owner,',
'        cons.table_name,',
'        cons.constraint_name',
'),',
'/*generate a suggested name for the index*/',
'cons as (',
'    select',
'        cons_cols.owner,',
'        cons_cols.table_name,',
'        cons_cols.constraint_name,',
'        cons_cols.columns,',
'        replace(''%_IDX'', ''%'',',
'            rtrim(substr(',
'                case when cons_cols.constraint_name like ''SYS/_%'' escape ''/''',
'                then replace(cons_cols.constraint_name,''_FK'','''')',
'                else cons_cols.table_name || ''_'' || translate(cons_cols.columns,''A,"'',''A'')',
'                end',
'                ,1,to_number(:P704_MAX_IDENTIFIER_LENGTH)-length(''%_IDX'')+1)',
'                ,''_'')',
'           ) as suggested_index_name        ',
'    from cons_cols',
')',
'/*report any referential integrity constraints that don''t have a matching index (i.e. leading columns are indexed)*/',
'select',
'    cons.owner,',
'    cons.table_name,',
'    cons.constraint_name,',
'    cons.columns as foreign_key_columns,',
'    suggested_index_name,',
'    ''CREATE INDEX "'' || cons.owner || ''"."'' || cons.suggested_index_name',
'        || ''" ON "'' || cons.owner || ''"."'' || cons.table_name',
'        || ''" ('' || cons.columns || '');'' as suggested_ddl',
'from cons',
'left join (',
'    /*note that this will not detect an index of interest that happens to be owned by a different schema;',
'      we could use all_ind_columns and join on table_owner but performance on large multitenant instances',
'      like our hosted instances suffers*/',
'    select',
'        table_name,',
'        index_name,',
'        listagg(''"''||column_name||''"'', '','') within group (order by column_position) as columns',
'    from sys.user_ind_columns',
'    group by',
'        table_name,',
'        index_name',
'    ) ind',
'    on ind.table_name = cons.table_name',
'    and ind.columns like cons.columns || ''%'' /*if the index includes additional columns, it''s still suitable*/',
'where ind.table_name is null /*only show the ones where a matching index was not found*/',
'order by',
'    cons.owner,',
'    cons.table_name,',
'    cons.constraint_name'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_plug_query_parse_override=>'P704_OWNER'
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
