,p_plug_template=>wwv_flow_imp.id(690714020036152159.4501)
,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'       wwv_flow_lang.system_message(''NO'') defaults_exist,',
'       ''#IMAGE_PREFIX#htmldb/icons/icon_uid_without_defaults.gif'' icon_name,',
'       decode(wo.object_type,',
'              ''TABLE'',wwv_flow_lang.system_message(''TABLE''),',
'              ''VIEW'',wwv_flow_lang.system_message(''VIEW''),',
'              wo.object_type) icon_alt_tag,',
'       ''f?p=4500:801:''||:app_session||',
'       ''::NO:RP,801,802:P800_SCHEMA,P801_TABLE_ID,P802_TABLE_ID:''||',
'       :P800_SCHEMA||'',''||wo.object_id||'','' edit_link,',
'       replace(replace(wo.object_name,''_'','' ''),''$'',''$ '') object_display_name,',
'       replace(wo.object_name,''$'',''$ '') object_name,',
'       wo.object_id,',
'       wo.object_type',
'  from ',
'(',
'-- objects without hints',
'select (select object_id',
'          from sys.dba_objects a',
'         where h.table_name = a.object_name',
'           and a.owner = :P800_SCHEMA',
'           and a.object_type in (''TABLE'',''VIEW'')) object_id,',
'       h.table_name object_name,',
'       (select d.object_type',
'          from sys.dba_objects d',
'         where h.table_name = d.object_name',
'           and d.owner = :P800_SCHEMA',
'           and d.object_type in (''TABLE'',''VIEW'')) object_type',
'  from (select object_name table_name',
'          from sys.dba_objects',
'         where object_type in (''TABLE'',''VIEW'')',
'           and owner = :P800_SCHEMA',
'           and object_name not like ''BIN$%''',
'           and object_name not like ''APEX$%''',
'           and object_name not like ''DR$%''',
'           and object_name not like ''SYS_IOT_%''',
'        MINUS',
'        select table_name',
'          from WWV_FLOW_HNT_TABLE_INFO',
'         where SCHEMA = :P800_SCHEMA) h ',
') wo',
'UNION',
'-- objects with hints',
'select wwv_flow_lang.system_message(''YES'') defaults_exist,',
'        decode(w.object_type,',
'               ''N'',''#IMAGE_PREFIX#htmldb/icons/icon_uid_without_table.gif'',',
'                   ''#IMAGE_PREFIX#htmldb/icons/icon_uid_with_defaults.gif'') icon_name,',
'       decode(w.object_type,',
'              ''N'',wwv_flow_lang.system_message(''NOT_IN_DATA_DICT''),',
'                  w.object_type) icon_alt_tag,',
'       ''f?p=4500:802:''||:app_session||',
'       ''::NO:RP,802:P800_SCHEMA,P802_TABLE_ID:''||',
'       :P800_SCHEMA||'',''||w.table_id edit_link,',
'       replace(w.object_name,''_'','' '') object_display_name,',
'       w.object_name,',
'       w.table_id object_id,',
'       upper(w.object_type) object_type',
'  from (',
'select h.table_id,',
'       h.table_name object_name,',
'       nvl((select decode(d.object_type,',
'                          ''TABLE'',wwv_flow_lang.system_message(''TABLE''),',
'                          ''VIEW'',wwv_flow_lang.system_message(''VIEW''),',
'                          d.object_type)',
'              from sys.dba_objects d',
'             where h.table_name = d.object_name',
'               and h.schema = d.owner',
'               and d.object_type in (''TABLE'',''VIEW'')),',
'            wwv_flow_lang.system_message(''NOT_IN_DATA_DICT'')) object_type,',
'       last_updated_on,',
'       last_updated_by',
'  from WWV_FLOW_HNT_TABLE_INFO h',
' where h.schema  = :P800_SCHEMA',
') w'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
