wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40293109595885680.4501)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'create meta data'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'wwv_flow_hint.synch_hints(',
'  p_schema     => :P800_SCHEMA,',
'  p_table_name => :P801_TABLE_NAME);',
'',
'-- Get new table id',
'for c1 in (select table_id',
'             from wwv_flow_hnt_table_info',
'            where schema     = :P800_SCHEMA',
'              and table_name = :P801_TABLE_NAME)',
'loop',
'   :P801_DEFAULT_ID := c1.table_id;',
'end loop;',
'',
':P801_DEFAULT_STATUS := wwv_flow_hint.check_table(',
'    p_schema=>:P800_SCHEMA,',
'    p_table_name=>:P801_TABLE_NAME);'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>unistr('Acci\00F3n NO terminada')
,p_process_success_message=>unistr('Acci\00F3n Terminada')
,p_internal_uid=>40293109595885680.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2555923208205196619.4501)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'validate schema'
,p_process_sql_clob=>'wwv_flow_sw_api.check_priv(:P800_SCHEMA);'
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2555923208205196619.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(40305830813298591.4501)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'set table name'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for c1 in (',
'select object_name ',
'from sys.dba_objects ',
'where object_id = :P801_TABLE_ID) loop',
'   :P801_table_name := c1.object_name;',
'end loop;',
'',
':P801_SCHEMA := :P800_SCHEMA;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>40305830813298591.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(13804023015557924.4501)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Check and Redirect'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_table_id wwv_flow_hnt_table_info.table_id%type;',
'begin',
'    select table_id ',
'      into l_table_id',
'      from wwv_flow_hnt_table_info',
'     where schema     = :P800_SCHEMA',
'       and table_name = :P801_TABLE_NAME;',
'',
'    -- redirect to Page 802',
'    wwv_flow_utilities.redirect_url(',
'        p_url => wwv_flow_page_api.get_url(',
'            p_page        => 802,',
'            p_clear_cache => ''RP,802'',',
'            p_items       => ''P800_SCHEMA,P802_TABLE_ID'',',
'            p_values      =>  :P800_SCHEMA||'',''||l_table_id ) );',
'exception',
'    when no_data_found then',
'        -- do nothing, render page 801',
'        null;       ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P801_TABLE_NAME'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>13804023015557924.4501
);
end;
