,p_plug_display_sequence=>30
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT TABLE_ID,',
'       COLUMN_ID,',
'       COLUMN_NAME, ',
'       LABEL,',
'      (select max(GROUP_NAME)',
'       from   WWV_FLOW_HNT_GROUPS g',
'       where  g.table_id = c.table_id and',
'              g.group_id = c.group_id) column_group,',
'      (select max(DISPLAY_SEQUENCE) ',
'       from   WWV_FLOW_HNT_GROUPS g',
'       where  g.table_id = c.table_id and',
'              g.group_id = c.group_id) column_group_DISPLAY_SEQUENCE,',
'       decode(display_in_report,''Y'',''<span class="a-Icon icon-check"></span>'',null) display_in_report, ',
'       DISPLAY_SEQ_REPORT, ',
'       MASK_REPORT,',
'       decode(c.alignment,',
'              ''L'',l.m,''C'',ctr.m,''R'',r.m,null) alignment,',
'       DISPLAY_AS_TAB_FORM,  -- need lov',
'       decode(display_in_form,''Y'',''<span class="a-Icon icon-check"></span>'',null) display_in_form, ',
'       DISPLAY_SEQ_FORM, ',
'       DISPLAY_AS_FORM,      -- need lov',
'       MASK_FORM,',
'       DEFAULT_VALUE, ',
'       DISPLAY_WIDTH, ',
'       MAX_WIDTH, ',
'       HEIGHT, ',
'       decode(required,''Y'',''<span class="a-Icon icon-check"></span>'',null) required, ',
'       (case when length(help_text) > 255 ',
'             then substr(help_text,1,255)||'' ...''',
'             else help_text',
'             end) ',
'             help_text, ',
'       length(help_text) help_length,',
'       (case when length(lov_query) > 255 ',
'             then substr(LOV_QUERY,1,255)||'' ...''',
'             else lov_query',
'             end) ',
'             lov_query,',
'       (case when length(WWV_FLOW_HINT.GET_STATIC_LOV_STRING(COLUMN_ID)) > 255',
'             then substr(WWV_FLOW_HINT.GET_STATIC_LOV_STRING(COLUMN_ID),1,255)||'' ...''',
'             else WWV_FLOW_HINT.GET_STATIC_LOV_STRING(COLUMN_ID)',
'             end) STATIC_LOV',
'  FROM WWV_FLOW_HNT_COLUMN_INFO c,',
'       (select wwv_flow_lang.system_message(''LEFT'') m from sys.dual) l,',
'       (select wwv_flow_lang.system_message(''CENTER'') m from sys.dual) ctr,',
'       (select wwv_flow_lang.system_message(''RIGHT'') m from sys.dual) r',
' where table_id = :P802_TABLE_ID'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
