,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'load table properties'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for l_tab_default in (',
'    select t.schema,',
'           t.table_name,',
'           t.form_region_title,',
'           t.report_region_title,',
'           t.description,',
'           ( select o.object_id',
'               from sys.dba_objects o',
'              where o.object_type in ( ''TABLE'', ''VIEW'' )',
'                and o.owner       = t.schema',
'                and o.object_name = t.table_name ) object_id',
'      from wwv_flow_hnt_table_info t',
'     where table_id = :P802_TABLE_ID',
'       and schema   = :P800_SCHEMA ) ',
'loop',
'    ',
'    :P802_TABLE_NAME          := l_tab_default.table_name;',
'    :P802_FORM_REGION_TITLE   := l_tab_default.form_region_title;',
'    :P802_REPORT_REGION_TITLE := l_tab_default.report_region_title;',
'    :P802_DESCRIPTION         := l_tab_default.description;',
'    :P802_TABLE_EXISTS        := case when l_tab_default.object_id is not null then',
'                                     ''Y''',
'                                 else',
'                                     ''N''',
'                                 end;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>40306618261313899.4501
);
end;
