'   and nvl( :P1003_POPUP , 0 ) <> 1',
' union all ',
'select wwv_flow_escape.html( :P1003_SCHEMA ) d,',
'       :P1003_SCHEMA v',
'  from sys.dual',
' where :P1003_POPUP = 1',
' order by 1'))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(488671029226029669.4501)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'NO'
,p_restricted_characters=>'WRKSP_USER_SCHEMA'
,p_encrypt_session_state_yn=>'N'
