begin
wwv_flow_imp_page.create_page(
 p_id=>840.4501
,p_name=>'Sincronizar Valores por Defecto'
,p_alias=>'SYNCHRONIZE-DEFAULTS'
,p_step_title=>'Sincronizar Valores por Defecto'
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'ON'
,p_group_id=>wwv_flow_imp.id(201270629259751113)
,p_step_template=>wwv_flow_imp.id(703368619593851824.4501)
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(12524102140541924)
,p_nav_list_template_options=>'#DEFAULT#'
,p_help_text=>'AEUTL/sql_utl_user_def.htm'
);
wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(40862329277925160.4501)
,p_name=>'Valores por Defecto de Interfaz de Usuario'
,p_template=>wwv_flow_imp.id(717419707883820782.4501)
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ',
'       wwv_flow_lang.system_message(''F4500_DICTIONARY_OBJECTS_WO_DEFAULTS'') defaults_exist, count(*) count_of_objects',
'  from ',
'(',
'-- objects without hints',
'select (select object_id',
'          from sys.dba_objects a',
'         where h.table_name = a.object_name',
'           and a.owner = :P800_SCHEMA',
'           and a.object_type in (''TABLE'',''VIEW'')) object_id,',
'       h.table_name object_name,',
'       (select d.object_type',
'          from sys.dba_objects d',
'         where h.table_name = d.object_name',
'           and d.owner = :P800_SCHEMA',
'           and d.object_type in (''TABLE'',''VIEW'')) object_type',
'  from (select object_name table_name',
'          from sys.dba_objects',
'         where object_type in (''TABLE'',''VIEW'')',
'           and owner = :P800_SCHEMA',
'           and object_name not like ''BIN$%''',
'           and object_name not like ''APEX$%''',
'           and object_name not like ''DR$%''',
'           and object_name not like ''SYS_IOT_%''',
'        MINUS',
'        select table_name',
'          from WWV_FLOW_HNT_TABLE_INFO',
'         where SCHEMA = :P800_SCHEMA) h ',
') wo',
'UNION',
'-- objects with hints',
'select wwv_flow_lang.system_message(''F4500_DICTIONARY_OBJECTS_W_DEFAULTS'') defaults_exist, count(*) count_of_objects',
'  from (',
'select h.table_id,',
'       h.table_name object_name,',
'       nvl((select decode(d.object_type,',
'                          ''TABLE'',wwv_flow_lang.system_message(''TABLE''),',
'                          ''VIEW'',wwv_flow_lang.system_message(''VIEW''),',
'                          d.object_type)',
'              from sys.dba_objects d',
'             where h.table_name = d.object_name',
'               and h.schema = d.owner',
'               and d.object_type in (''TABLE'',''VIEW'')),',
'            ''N'') object_type,',
'       last_updated_on,',
'       last_updated_by',
'  from WWV_FLOW_HNT_TABLE_INFO h',
' where h.schema  = :P800_SCHEMA',
') w'))
,p_header=>unistr('<p>Sincronice los valores por defecto con el diccionario de datos de la base de datos. De este modo, se agregar\00E1n nuevas columnas a las tablas desde la \00FAltima sincronizaci\00F3n y se eliminar\00E1n las que ya no existan.</p> ')
,p_footer=>'<p />'
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_headings_type=>'NO_HEADINGS'
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
