wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(424278603676273502.4501)
,p_validation_name=>'check version'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_runtime_version varchar2(200); -- the date of the current runtime flows',
'  l_calling_version varchar2(200);',
'begin',
'    l_calling_version := replace(replace(replace(wwv_flow_imp_parser.get_version (p_file_id => :P843_file_id),''.'',null),''_'',null),''/'',null);',
'    l_runtime_version := replace(replace(replace(wwv_flows_version,''.'',null),''_'',null),''/'',null);',
'',
'    if l_calling_version > l_runtime_version then',
'        --',
'        -- version incompatability        ',
'        --',
'        ',
'        return false;',
'    else',
'        return true;',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('NO COMPATIBLE (Puede que la exportaci\00F3n contenga llamadas no soportadas por la versi\00F3n de la aplicaci\00F3n).')
,p_when_button_pressed=>wwv_flow_imp.id(40886628072281718.4501)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
