wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(7886012904365381.4501)
,p_process_sequence=>30
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save_Query_PPR'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  i number;',
'  l_ret varchar2(32767);',
'  qid number := -99;',
'  l_o_name varchar2(2000);',
'begin',
'  wwv_flow_sw_api.check_priv(:P1002_SCHEMA);',
'',
'  begin',
'    if wwv_flow.g_f22(1) is not null then',
'      qid := wwv_flow.g_f22(1);',
'    end if;',
'  exception when others then',
'    null;',
'  end;',
'',
'  begin',
'    select title into l_o_name from wwv_flow_qb_saved_query where id = qid;',
'  exception when others then',
'    l_o_name := ''''; ',
'  end;',
'',
'  if (wwv_flow.g_f19(1) = l_o_name) then',
'    delete from wwv_flow_qb_saved_query where id = qid;',
'    commit;',
'  else',
'      qid := wwv_flow_id.next_val;',
'  end if;',
'  ',
'  insert into wwv_flow_qb_saved_query ',
'   (id, title, query_type, description, qb_sql, query_owner, created_by ) ',
'  values ',
'   (qid, wwv_flow.g_f19(1) , ''W'', wwv_flow.g_f21(1), wwv_flow.g_f23(1), :P1002_SCHEMA, :FLOW_USER );',
'',
'  for i in 1..wwv_flow.g_f01.count loop',
'    insert into wwv_flow_qb_saved_tabs ',
'     (id, oid, cnt, top, left, tname ) ',
'    values ',
'     (qid,wwv_flow.g_f01(i),wwv_flow.g_f02(i),wwv_flow.g_f03(i),wwv_flow.g_f04(i),wwv_flow.g_f05(i));',
'  end loop;',
'',
'  for i in 1..wwv_flow.g_f06.count loop',
'    insert into wwv_flow_qb_saved_cond ',
'     (id, col, alias, fv, fp, out, st, so, grp, con, ord) ',
'    values ',
'     (qid, wwv_flow.g_f06(i), wwv_flow.g_f07(i), wwv_flow.g_f08(i), wwv_flow.g_f09(i),',
'      wwv_flow.g_f10(i), wwv_flow.g_f11(i), wwv_flow.g_f12(i), wwv_flow.g_f13(i), wwv_flow.g_f14(i),',
'      i);',
'  end loop;',
'   ',
'  for i in 1..wwv_flow.g_f15.count loop',
'    insert into wwv_flow_qb_saved_join ',
'     (id, field1, field2, cond) ',
'    values ',
'     (qid,wwv_flow.g_f15(i),wwv_flow.g_f16(i),wwv_flow.g_f17(i));',
'  end loop;',
'',
'  sys.htp.prn(qid);',
'  wwv_flow.g_unrecoverable_error := true;',
'EXCEPTION WHEN OTHERS THEN ',
' sys.htp.prn(''---''||wwv_flow_escape.html(SQLERRM));',
' wwv_flow.g_unrecoverable_error := true;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'SAVE_QUERY'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>'Correcto'
,p_internal_uid=>7886012904365381.4501
);
end;
