wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(3016364673375330.4501)
,p_name=>'P1003_MLE_ENV'
,p_item_sequence=>60
,p_item_plug_id=>wwv_flow_imp.id(149883011479458110.4501)
,p_prompt=>'Entorno'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select object_name d,',
'       object_name r',
'  from (',
'         select case when o.owner != :P1003_SCHEMA then o.owner || ''.'' end || object_name as object_name',
'          from ( select o.owner, o.owner as grantee, o.object_type, o.object_name',
'                   from sys.dba_objects o',
'                  union',
'                 select p.owner, p.grantee, p.type, p.table_name',
'                   from sys.dba_tab_privs p ) o',
'         where o.object_type = ''MLE ENVIRONMENT''',
'           and o.grantee in ( :P1003_SCHEMA, ''PUBLIC'' )',
'       )',
'order by object_name'))
,p_lov_display_null=>'YES'
,p_lov_null_text=>'Valor por Defecto'
,p_lov_cascade_parent_items=>'P1003_SCHEMA'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_tag_attributes=>'class="a-Form-select" onchange="sc_SetMleEnvOnly()"'
,p_begin_on_new_line=>'N'
,p_display_when=>'wwv_flow_db_version.c_has_mle_with_modules'
,p_display_when2=>'PLSQL'
,p_display_when_type=>'EXPRESSION'
,p_field_template=>wwv_flow_imp.id(488671029226029669.4501)
,p_item_template_options=>'#DEFAULT#'
,p_lov_display_extra=>'YES'
,p_help_text=>'Determina el entorno del MLE que se debe utilizar para ejecutar la sentencia introducida.'
,p_encrypt_session_state_yn=>'N'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
