'select /* APEX4500P1004a */',
'f.id,',
'decode(doc_size,0,',
'       ''&nbsp'',',
'       ''<a href="''||wwv_flow_utilities.prepare_url(''f?p=4500:60:''||:flow_session||''::::P60_FILE_ID:'' ||f.id)||''" class="a-Button a-Button--small">''||',
'       ''<span class="a-Icon icon-edit" title="&EDIT."></span></a>''',
'       ) edit,',
'wwv_flow_item.checkbox(1,f.id,''title="''||wwv_flow_lang.system_message(''SELECT_ROW_C'', wwv_flow_escape.html(f.filename))||''"'') cb,',
'substr(f.filename,1,50) t,',
'f.CREATED_ON created,',
'f.created_by,',
'nvl(f.updated_on,f.created_on) updated,',
'f.updated_by,',
'f.doc_size doc_size,',
'(select decode(count(*),0,',
'        ''0'',',
'        sys.htf.anchor(wwv_flow_utilities.prepare_url(''f?p=4500:1220:''||:flow_session||''::::IR_FILE_ID:''||f.id),',
'        to_char(count(*),''999G999G999G999G990''))) c ',
'        from WWV_FLOW_SW_RESULTS',
'        where file_id = f.id) ouput_count,       ',
'decode(doc_size,1,sys.htf.anchor(wwv_flow_utilities.prepare_url(''f?p=4500:1022:''||:flow_session||''::::P1022_FILE_ID:''|| f.id),',
'       ''<img src="#IMAGE_PREFIX#htmldb/icons/error_small.gif" alt="''||wwv_flow_lang.system_message(''ERROR'')||''" />''),',
'decode(wwv_flow_sw_parser.parsed(f.id),1,',
'decode(wwv_flow_sw_script.invalid_script(f.id), 1,',
'       sys.htf.anchor(wwv_flow_utilities.prepare_url(''f?p=4500:1022:''||:flow_session||''::::P1022_FILE_ID:''|| f.id),',
'       ''<span class="a-Icon icon-error" title="''||wwv_flow_lang.system_message(''ERROR'')||''"></span>''),',
