,p_plug_name=>unistr('Objetos no V\00E1lidos')
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690714020036152159.4501)
,p_plug_display_sequence=>20
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select :P1040_OWNER as object_owner,',
'       object_name,',
'       object_type,',
'       status,',
'       case',
'       when object_type in (''TYPE BODY'', ''PACKAGE BODY'')',
'       then ( select to_char(o2.object_id)',
'                from sys.user_objects o2',
'               where o2.object_name = o.object_name',
'                 and o2.object_type = replace(o.object_type, '' BODY'', null) )',
'       when object_type = ''LOB''',
'       then ( select to_char(o2.object_id)',
'                from sys.user_objects o2,',
'                     sys.user_lobs l',
'               where o2.object_name = l.table_name',
'                 and l.segment_name = o.object_name )',
'       when object_type = ''DATABASE LINK''',
'       -- keep this logic in sync with wwv_flow_f4500_ob_wiz_dev.get_object_id ( private ) function',
'       then to_char(ora_hash( object_name, 1000000000, power( 2, 30 ) ))',
'       else to_char(object_id)',
'       end object_id,',
'       created date_created,',
'       nvl(last_ddl_time, created) lastddltime',
'  from sys.user_objects o',
' where status = ''INVALID''',
'   and object_name not like ''BIN$%'''))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_plug_query_parse_override=>'P1040_OWNER'
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
