wwv_flow_imp_page.create_page_da_event(
 p_id=>wwv_flow_imp.id(6208891564373627.4501)
,p_name=>'quicksql Menu Items hide/show/enable/disable'
,p_event_sequence=>20
,p_bind_type=>'bind'
,p_execution_type=>'IMMEDIATE'
,p_bind_event_type=>'ready'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(6208994857373628.4501)
,p_event_id=>wwv_flow_imp.id(6208891564373627.4501)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'$( "#qsql_actions_menu" ).on( "menubeforeopen", function ( event, ui ) { ',
'    var menuItems = ui.menu.items; ',
'    menuItems = menuItems.map( function ( item ) { ',
'        if ( item.id == "properties" || item.id == "saveModelAs" ){',
'            if ( apex.item( "P1100_MODEL_ID" ).getValue() == "" ){',
'                item.disabled = true;  ',
'            } else {',
'                item.disabled = false;',
'            }',
'        }',
'        if ( item.id == "updateModel" ){',
'            if ( apex.item( "P1100_MODEL_ID" ).getValue() == "" ){',
'                item.hide = true;  ',
'            } else {',
'                item.hide = false;',
'            }',
'        }',
'        if (item.id == "saveModel"){',
'            if ( apex.item( "P1100_MODEL_ID" ).getValue() == "" ){',
'                item.hide = false;  ',
'            } else {',
'                item.hide = true;',
'            }',
'',
'            if (apex.item( "P1100_RAW_SQL" ).getValue() == ""){',
'                item.disabled = true;',
'            } else {',
'                item.disabled = false;',
'            }',
'        }',
'        return item; ',
'    }); ',
'});'))
);
