,p_attribute_01=>'FUNCTION_BODY'
,p_attribute_06=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_model clob;',
'begin',
'    for l_quick_sql in (',
'        select quick_sql model',
'        into l_model',
'        from wwv_qs_models ',
'        where id = :P1100_MODEL_ID )',
'    loop',
'        l_model := l_quick_sql.model;',
'    end loop;',
'    ',
'    if l_model is null then',
'        for l_quick_sql in (',
'            select model',
'            from wwv_qs_saved_models ',
'            where id = :P1100_MODEL_ID  ',
'            and security_group_id = :flow_security_group_id )',
'        loop',
'            l_model := l_quick_sql.model;',
'        end loop;',
'    end if;',
'    ',
'    return l_model;',
'end;'))
,p_attribute_07=>'P1100_MODEL_ID'
,p_attribute_08=>'N'
,p_attribute_09=>'N'
,p_wait_for_result=>'Y'
);
