,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'load ords libraries'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    c_ords_js_path varchar2(4000) := :P1100_ORDS_PATH || ''_/lib/js/'';',
'begin',
'    -- has both min and not min versions',
'    wwv_flow_javascript.add_library (',
'        p_name                    => ''lodash'',',
'        p_directory               => c_ords_js_path || ''lodash/'',',
'        p_check_to_add_minified   => true );',
'',
'    -- backbone has min and not min, via -min suffix',
'    wwv_flow_javascript.add_library (',
'        p_name                    => ''backbone-min'',',
'        p_directory               => c_ords_js_path || ''backbone/'' );',
'',
'    -- rappid does not have minified version in ORDS',
'    wwv_flow_javascript.add_library (',
'        p_name                    => ''rappid'',',
'        p_directory               => c_ords_js_path || ''rappid/'' );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>2000763421438705.4501
);
