wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6206833571373607.4501)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'SaveScript'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_script_id     number;',
'    l_script_name   varchar2(4000);',
'    l_sql           clob := :P1100_OUTPUT_SQL;',
'begin',
'',
'    -- save SQL ',
'    l_script_name := :P1104_SCRIPT_NAME;',
'    ',
'    for l_script in (',
'        select id',
'        from wwv_flow_files f, wwv_flow_fnd_user u',
'        where u.security_group_id = :flow_security_group_id',
'        and u.user_name = :APP_USER',
'        and f.filename = l_script_name',
'        and f.file_type = ''SCRIPT'' and (f.created_by = :APP_USER',
'               or exists ( select 1',
'                             from  wwv_flow_developers',
'                            where security_group_id = :flow_security_group_id',
'                              and userid = :APP_USER',
'                              and instr(developer_role||'':'',''ADMIN:'') > 0',
'                            union',
'                           select 1',
'                             from wwv_flow_fnd_user',
'                            where security_group_id = :FLOW_SECURITY_GROUP_ID',
'                              and user_name = :APP_USER',
'                              and attribute_01 in (''ORACLE_ADMIN'',''SCHOOL_ADMIN'',''TEACHER''))) )',
'    loop',
'        l_script_id := l_script.id;',
'    end loop;',
'    ',
'    if l_script_id is null then',
'        wwv_flow_sw_script.create_script_from_clob (        ',
'             p_script_name => l_script_name,',
'             p_script      => l_sql );',
'    else',
'        wwv_flow_sw_script.update_script_file (',
'             p_file_id     => l_script_id,',
'             p_script_name => l_script_name,',
'             p_script      => l_sql );',
'             ',
'        :P1100_SCRIPT_NAME := l_script_name;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(4213511874005243933.4501)
,p_internal_uid=>6206833571373607.4501
);
wwv_flow_imp_page.create_page_process(
