wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(21503410687604939.4501)
,p_plug_name=>'SQL Command Results (autocommit)'
,p_component_template_options=>'#DEFAULT#'
,p_plug_display_sequence=>30
,p_plug_display_column=>1
,p_plug_display_point=>'BODY_3'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare ',
'    l_sql       clob;',
'    report      wwv_flow_global.vc_arr2;',
'    binds       wwv_flow_global.vc_arr2;',
'    l_start     number;',
'begin',
'',
'-- get the statement to run',
'  l_sql := :P1003_SQL_COMMAND2;',
'',
'-- get the binds values used last time if they exist',
'  binds := wwv_flow_utilities.string_to_table (',
'                            str => v(''P1200_BIND_VALS''),',
'                            sep => '','');',
'',
'  for i in 1..binds.count loop',
'   if binds(i) = ''HTMLDB:NULL'' then',
'    binds(i) := null;',
'   end if;',
'  end loop;',
'',
'-- get start time',
'l_start := sys.dbms_utility.get_time;',
'',
'if upper(substr(ltrim(:P1003_SQL_COMMAND2),1,6)) = ''COMMIT'' then',
'  sys.htp.p(wwv_flow_lang.system_message(''AUTOCOMMIT'')); ',
'elsif upper(substr(ltrim(:P1003_SQL_COMMAND2),1,8)) = ''ROLLBACK'' then',
'  sys.htp.p(wwv_flow_lang.system_message(''ROLLBACK'')); ',
'else',
'  -- get the results ',
'    wwv_flow_sw_api.check_priv(:P1003_SCHEMA);	',
'    wwv_flow_security.g_parse_as_schema := :P1003_SCHEMA;',
'    report := wwv_flow_render_query.get_report (',
'        p_owner  => :P1003_SCHEMA,',
'        p_query  => l_sql,',
'        p_values => binds,',
'        p_format => ''HTMLR'',',
'        p_limit_type => ''R'',',
'        p_max_rows => :P1003_ROWS',
'    );',
'  wwv_flow_security.g_parse_as_schema := wwv_flow.g_flow_schema_owner;',
'  -- get count minus 1 because of header row returned',
'  -- get count minus 2 because of to many rows message',
'  if (report.count > to_number(v(''P1003_ROWS''))+1) then',
'       :p1200_rows := report.count-2;',
'  else',
'       :p1200_rows := report.count-1;',
'  end if;',
'',
'  sys.htp.p(''<div id=ResultsSQL>'');',
'  -- print the results',
'  for i in 1..report.count loop',
'    sys.htp.p(report(i));',
'  end loop;',
'  sys.htp.p(''</div>'');',
'  if (report.count > 1) then',
'    -- print row count and timing information',
'    sys.htp.prn(''<table><tr><td>'');   ',
'    sys.htp.prn(''<span style="font-size:13px">''||wwv_flow_lang.system_message(''ROWS_IN_SECONDS'',:p1200_rows,to_char(round((sys.dbms_utility.get_time-l_start)/100,2),''999G999G999G990D00''))||''</span>'');',
'sys.htp.prn(''</td><td>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td><td><span style="font-size:11px"><a href="f?p=4500:1204:''||:SESSION||''::::P1204_BROWSER_LANG:''||wwv_flow.g_browser_language||''">''||',
'         wwv_flow_lang.system_message(''F4000.P420.CSV_EXPORT'')||',
'         ''</a></span></td></tr></table>'');',
'  end if;',
'end if;',
'exception when others then',
'  wwv_flow_security.g_parse_as_schema := wwv_flow.g_flow_schema_owner;',
'  wwv_flow_debug.log_exception;',
'end;',
''))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_translate_title=>'N'
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
,p_plug_display_condition_type=>'EXPRESSION'
,p_plug_display_when_condition=>wwv_flow_string.join(wwv_flow_t_varchar2(
'((upper(substr(ltrim(replace(replace(:P1003_SQL_COMMAND2,chr(10),''''),chr(13),'''')),1,6)) = ''SELECT'' or',
'upper(substr(ltrim(replace(replace(:P1003_SQL_COMMAND2,chr(10),''''),chr(13),'''')),1,4)) = ''WITH'' or',
'upper(substr(ltrim(replace(replace(:P1003_SQL_COMMAND2,chr(10),''''),chr(13),'''')),1,6)) = ''COMMIT'' or',
'upper(substr(ltrim(replace(replace(:P1003_SQL_COMMAND2,chr(10),''''),chr(13),'''')),1,8)) = ''ROLLBACK'') and',
':P1003_CMD_LANGUAGE not in ( wwv_flow_code_exec.c_javascript, wwv_flow_code_exec.c_java, wwv_flow_code_exec.c_python ) and',
':P1003_AUTOCOMMIT = ''Y'')'))
,p_plug_display_when_cond2=>'PLSQL'
