,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select id,',
'       CREATED_ON created, ',
'       created_by, ',
'       sys.dbms_lob.substr(command,100,1) sql_cmd,',
'       PARSED_SCHEMA,',
'       ''javascript:sc_postHistory(''||',
'       wwv_flow_escape.js_literal(ID)||',
'       '',''||wwv_flow_escape.js_literal(PARSED_SCHEMA)||',
'       '');'' link',
'from wwv_flow_sw_sql_cmds  ',
'where security_group_id = :flow_security_group_id  ',
'and created_by = :flow_user ',
'and (:P1201_FIND is null or instr(upper(command),upper(:P1201_FIND)) > 0)',
'order by CREATED_ON desc'))
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_num_rows=>100
