wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(239514318560826866.4501)
,p_name=>unistr('Columnas de \00CDndice')
,p_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_new_grid_row=>false
,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with sqlplan as (',
'    select c006 object_owner, c007 object_type,c008 object_name',
'      from htmldb_collections',
'     where COLLECTION_NAME=''HTMLDB_QUERY_PLAN''',
'       and c007 in (''TABLE'',''INDEX'',''MATERIALIZED VIEW'',''INDEX (UNIQUE)'')),',
'ws_schemas as(',
'    select schema',
'      from wwv_flow_company_schemas',
'     where security_group_id = :flow_security_group_id),',
't as(',
'        select s.object_owner table_owner,s.object_name table_name,',
'               d.OBJECT_ID',
'          from sqlplan s,sys.dba_objects d',
'         where s.object_owner = d.owner',
'           and s.object_name = d.object_name',
'           and s.object_type in (''TABLE'',''MATERIALIZED VIEW'')',
'         union',
'        select d1.table_owner table_owner,d1.table_name table_name,',
'               d.OBJECT_ID',
'          from sys.dba_indexes d1, sqlplan s1,',
'               sys.dba_objects d',
'         where d1.index_name = s1.object_name',
'           and d1.owner = s1.object_owner',
'           and replace(s1.object_type,'' (UNIQUE)'') = ''INDEX''',
'           and d.object_type in (''TABLE'',''MATERIALIZED VIEW'')',
'           and d.owner = d1.table_owner',
'           and d.object_name = d1.table_name',
'           ),',
'cols as(',
'    select table_owner,index_name,',
'           rtrim(',
'           max(decode(position,1 ,column_name))||'',''||',
'           max(decode(position,2 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,3 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,4 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,5 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,6 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,7 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,8 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,9 ,substr(column_name,1,128)))||'',''||',
'           max(decode(position,10,substr(column_name,1,128)))',
'           ,'','') columns',
'     from(',
'        select c.table_owner,c.index_name,c.column_name,c.column_position position',
'          from sys.dba_ind_columns c, t',
'         where t.table_owner = c.table_owner',
'           and t.table_name = c.table_name)',
'    group by table_owner,index_name',
')',
'select di.owner,',
'       case when di.owner in (select schema from ws_schemas) then',
'            ''<a href="''||wwv_flow_page_api.get_url(',
'                             p_page        => 2000,',
'                             p_clear_cache => ''RP,2000'',',
'                             p_items       => ''P2000_OB_INIT_SCHEMA,P2000_OB_INIT_ID'',',
'                             p_values      => di.owner||'',''||t.object_id )||''">''||wwv_flow_escape.html(di.table_name)||''</a>''',
'       else wwv_flow_escape.html(di.table_name) end table_name,',
'       case when di.owner in (select schema from ws_schemas) then',
'            ''<a href="''||wwv_flow_page_api.get_url(',
'                             p_page        => 2000,',
'                             p_clear_cache => ''RP,2000'',',
'                             p_items       => ''P2000_OB_INIT_SCHEMA,P2000_OB_INIT_ID'',',
'                             p_values      => di.owner||'',''||do2.object_id )||''">''||wwv_flow_escape.html(di.index_name)||''</a>''',
'       else wwv_flow_escape.html(di.index_name) end index_name,',
'       case when (select count(*) cnt',
'                    from sqlplan sp1',
'                   where sp1.object_type like ''INDEX%''',
'                     and sp1.object_name = di.index_name) > 0',
'            then ''<img src="#IMAGE_PREFIX#check_small_black.gif" alt=""/>''',
'            else ''<br />''',
'       end check_mark,',
'      c.columns, uniqueness, di.status,',
'      index_type, partitioned,',
'      funcidx_status, join_index,t.object_id, do2.object_id index_object_id',
'from   sys.dba_indexes di,sys.dba_objects do2,',
'       t,cols c',
'where di.table_owner = t.table_owner',
'  and di.table_name = t.table_name',
'  and index_type != ''LOB''',
'  and do2.object_type = ''INDEX''',
'  and do2.owner = di.owner',
'  and do2.object_name = di.index_name',
'  and c.table_owner = di.table_owner',
'  and c.index_name  = di.index_name'))
,p_display_when_condition=>'P1202_QUERY_TYPE'
,p_display_when_cond2=>'Y'
,p_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_fixed_header=>'NONE'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_num_rows=>1000
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_show_nulls_as=>' - '
,p_query_break_cols=>'1:2'
,p_query_no_data_found=>unistr('No se ha encontrado ning\00FAn \00EDndice')
,p_query_row_count_max=>1000
,p_break_type_flag=>'DEFAULT_BREAK_FORMATTING'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'Y'
,p_comment=>'10g Version'
);
