wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(239555324756875948.4501)
,p_name=>'Plan de Consulta'
,p_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_display_sequence=>50
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_new_grid_row=>false
,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with sqlplan as (',
'    select to_number(c001) id, to_number(c002) parent_id,to_number(c003) position,',
'           c004 operation, c005 options,',
'           c006 object_owner, c007 object_type,c008 object_name,',
'           c009 access_predicates, c010 filter_predicates,',
'           to_number(c011) cardinality, to_number(c012)cost,',
'           to_number(c013) bytes, to_number(c014)time',
'      from htmldb_collections',
'     where COLLECTION_NAME=''HTMLDB_QUERY_PLAN''),',
'objects as (',
'   select o.object_id,s.id',
'     from sys.dba_objects o,sqlplan s',
'    where o.owner = s.object_owner',
'      and o.object_name = s.object_name',
'      and replace(s.object_type,'' (UNIQUE)'') = o.object_type',
'      and s.object_type in (''TABLE'',''INDEX'',''MATERIALIZED VIEW'',''INDEX (UNIQUE)'')',
'     ),',
'ws_schemas as(',
'    select schema ',
'      from wwv_flow_company_schemas',
'     where security_group_id = :flow_security_group_id), ',
'plan_objects as(',
'    select s.id,parent_id,position,',
'           operation,options,',
'           object_owner,object_type,object_name,',
'           access_predicates,filter_predicates,',
'           cardinality,cost,bytes,time,',
'           o.object_id',
'      from sqlplan s,objects o',
'     where s.id = o.id(+))',
'select operation,options,',
'       case when object_type in (''TABLE'',''VIEW'',''INDEX'',''MATERIALIZED VIEW'',''INDEX (UNIQUE)'') then',
'            case when object_owner in (select schema from ws_schemas) then',
'                 ''<a href="''||wwv_flow_page_api.get_url(',
'                                  p_page        => 2000,',
'                                  p_clear_cache => ''RP,2000'',',
'                                  p_items       => ''P2000_OB_INIT_SCHEMA,P2000_OB_INIT_ID'',',
'                                  p_values      => object_owner||'',''||object_id )||''">''||wwv_flow_escape.html(object_name)||''</a>''',
'            else wwv_flow_escape.html(object_name) end ',
'       else wwv_flow_escape.html(object_name) end object_name,',
'       cost,cardinality,bytes,',
'       decode(level,1,1,power(level,2)+15) padding,access_predicates,filter_predicates,TIME,',
'       case when object_type = ''TABLE'' then',
'            wwv_flow_session_mon.highlight_plan_ind_cols(object_owner,object_name,filter_predicates)',
'       else wwv_flow_escape.html(replace(filter_predicates,''='','' = '')) end filter_predicates2,',
'       case when object_type = ''TABLE'' then',
'            wwv_flow_session_mon.highlight_plan_ind_cols(object_owner,object_name,access_predicates) ',
'       else wwv_flow_escape.html(replace(access_predicates,''='','' = '')) end access_predicates2,',
'       object_id,object_type',
'   from plan_objects s1',
'  start with id = 0',
'connect by prior id = parent_id',
'  order by id, position'))
,p_display_when_condition=>'P1202_QUERY_TYPE'
,p_display_when_cond2=>'Y'
