 p_id=>wwv_flow_imp.id(239675610426212457.4501)
,p_name=>'Columnas de Tabla'
,p_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_display_sequence=>60
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_new_grid_row=>false
,p_display_column=>1
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with sqlplan as (',
'    select c006 object_owner, c007 object_type,c008 object_name',
'      from htmldb_collections',
'     where COLLECTION_NAME=''HTMLDB_QUERY_PLAN''',
'       and c007 in (''TABLE'',''INDEX'',''MATERIALIZED VIEW'',''INDEX (UNIQUE)'')),',
't1 as(',
'        select s.object_owner table_owner,s.object_name table_name',
'          from sqlplan s',
'         where s.object_type in (''TABLE'',''MATERIALIZED VIEW'')',
'         union',
'        select d1.table_owner table_owner,d1.table_name table_name',
'          from sys.dba_indexes d1, sqlplan s1',
'         where d1.index_name = s1.object_name',
'           and d1.owner = s1.object_owner',
'           and replace(s1.object_type,'' (UNIQUE)'') = ''INDEX''',
'           ),',
't as (select t1.table_owner, t1.table_name,',
'             o.object_id',
'        from t1, sys.dba_objects o',
'       where t1.table_owner = o.owner',
'         and t1.table_name = o.object_name',
'         and o.object_type in (''TABLE'',''MATERIALIZED VIEW'') ',
'      )',
'select t.table_owner,t.table_name,c.column_name,c.data_type',
'  from t,sys.dba_tab_columns c',
' where t.table_name = c.table_name',
'   and t.table_owner = c.owner',
' order by t.table_owner,t.table_name,c.column_id'))
,p_display_when_condition=>'P1202_QUERY_TYPE'
,p_display_when_cond2=>'Y'
,p_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
