wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(467846201977971481.4501)
,p_plug_name=>'Resultados'
,p_region_template_options=>'#DEFAULT#:a-IRR-region--noOuterBorders'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(690714020036152159.4501)
,p_plug_display_sequence=>40
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with dr as',
'(select result_id,',
'        sum(result_size) the_sum',
'  from wwv_flow_sw_detail_results ',
' where security_group_id = :flow_security_group_id',
' group by result_id),',
'wv_lang as',
'    (select r.result_id,s.file_id,',
'            wwv_flow_lang.system_message(''FORM_OF'',r.cnt,s.cnt) the_msg,',
'            wwv_flow_lang.system_message(''FORM_OF'',r.cnt,r.cnt) the_msg2',
'      from',
'        (select file_id,count(distinct stmt_number) cnt',
'           from wwv_flow_sw_stmts',
'          where isrunnable = ''Y''',
'            and security_group_id = :flow_security_group_id',
'          group by file_id) s,',
'        (select result_id,file_id,count(*) cnt',
'           from wwv_flow_sw_detail_results',
'          where security_group_id = :flow_security_group_id',
'          group by result_id,file_id) r',
'     where s.file_id = r.file_id(+))',
'SELECT ',
'   r.id edit_script,',
'   r.id "ID", ',
'   r.file_id,',
'   r.file_id details,',
'   f.filename FILE_Name, ',
'   f.filename script_name,',
'   r.job_id "JOB_ID", ',
'   r.run_by "RUN_BY", ',
'   r.run_as run_as,',
'   the_sum output_size,  ',
'   r.started "STARTED", ',
'   r.ended "ENDED",    ',
'   (decode(sign(r.end_time-r.start_time),-1,24*60*60*(nvl(r.ended,sysdate) - r.started),r.end_time-r.start_time)/100) elapsed,',
'   decode(r.status,''EXECUTING'',',
'          sys.htf.anchor(''f?p=4500:1225:''||:app_session||''::::P1224_RESULT_ID:''||r.id,wwv_flow_lang.system_message(''WWV_FLOW_SW_SCRIPT.EXECUTING'')),',
'   wwv_flow_escape.html(case when r.status = ''SUBMITTED'' then wwv_flow_lang.system_message(''WWV_FLOW_SW_SCRIPT.SUBMITTED'') when r.status = ''EXECUTING'' then wwv_flow_lang.system_message(''WWV_FLOW_SW_SCRIPT.EXECUTING'') when r.status = ''COMPLETE'' then w'
||'wv_flow_lang.system_message(''WWV_FLOW_SW_SCRIPT.COMPLETED'') when r.status = ''CANCELED'' then wwv_flow_lang.system_message(''WWV_FLOW_SW_SCRIPT.CANCELED'')  when r.status = ''CANCELING'' then wwv_flow_lang.system_message(''WWV_FLOW_SW_SCRIPT.CANCELING'') end'
||')) status,',
'   r.run_comments "RUN_COMMENTS", ',
'   r.security_group_id "SECURITY_GROUP_ID",',
'   decode(r.status,''COMPLETE'',htmldb_item.checkbox(1,r.id,null,null,null,''f''||lpad(''''||1,2,''0'') || ''_'' || lpad(''''||rownum,4,''0''),wwv_flow_lang.system_message(''DELETE_LABEL'', wwv_flow_escape.html(f.filename))),',
'          ''CANCELED'',htmldb_item.checkbox(1,r.id,null,null,null,''f''||lpad(''''||1,2,''0'') || ''_'' || lpad(''''||rownum,4,''0''),wwv_flow_lang.system_message(''DELETE_LABEL'', wwv_flow_escape.html(f.filename))),',
'          null) purge,',
'    -- wv_lang.the_msg  statements,',
'    (select decode(r.status,''COMPLETE'',the_msg2,the_msg) from wv_lang where wv_lang.file_id = r.file_id and wv_lang.result_id = r.id) statements,',
'decode(r.status,''EXECUTING'',''Y'',''SUBMITTED'',''Y'',''N'') highlight_row',
'FROM ',
'   wwv_flow_sw_results r, wwv_flow_files f,dr',
'where r.file_id = f.id',
'  and dr.result_id(+) = r.id',
'  and r.security_group_id = :flow_security_group_id',
'  and f.file_type = ''SCRIPT'' and (f.created_by = :APP_USER',
'       or exists ( select 1',
'                     from  wwv_flow_developers',
'                    where security_group_id = :flow_security_group_id',
'                      and userid = :APP_USER',
'                      and instr(developer_role||'':'',''ADMIN:'') > 0',
'                    union',
'                   select 1',
'                     from wwv_flow_fnd_user',
'                    where security_group_id = :FLOW_SECURITY_GROUP_ID',
'                      and user_name = :APP_USER',
'                      and attribute_01 in (''ORACLE_ADMIN'',''SCHOOL_ADMIN'',''TEACHER'')))'))
,p_plug_source_type=>'NATIVE_IR'
,p_plug_query_show_nulls_as=>' - '
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
