wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11922008681959891.4501)
,p_plug_name=>'Salida'
,p_region_template_options=>'#DEFAULT#:a-Region--paddedBody:a-Region--hideHeader'
,p_component_template_options=>'#DEFAULT#'
,p_plug_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_plug_display_sequence=>30
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'  l_elapsed number := 0;',
'begin',
'  sys.htp.prn(''<span class="fielddata">'');',
'  sys.htp.prn(''<hr />'');',
'  for c1 in (select id, result_id, stmt_num, stmt_text, msg, result, ',
'                    started, start_time, ended, end_time, Result_Rows',
'             from wwv_flow_sw_detail_results',
'             where result_id = :p1224_result_id',
'             and security_group_id = :flow_security_group_id',
'             order by seq_id)',
'  loop',
'    -- statement',
'    if instr('':''||:P1225_VIEW_MODE||'':'','':STMT:'') > 0 then',
'      sys.htp.prn(''<pre>'');',
'      wwv_flow_sw_script.print_stmt(p_id => c1.id);',
'      sys.htp.prn(''</pre>'');',
'    end if;',
'  ',
'    -- results',
'    if instr('':''||:P1225_VIEW_MODE||'':'','':RESULTS:'') > 0 then',
'          sys.htp.prn(''<div class="htmldbScriptResult">'');',
'    	wwv_flow_sw_script.print_result(p_id => c1.id);',
'          sys.htp.prn(''</div>'');',
'    end if;',
'  ',
'    -- feedback',
'    if instr('':''||:P1225_VIEW_MODE||'':'','':MSG:'') > 0 then',
'      sys.htp.prn(''<br />'');',
'      sys.htp.prn(wwv_flow_escape.html(c1.msg));',
'    end if;',
'  ',
'    -- rows',
'    /*if instr('':''||:P1225_VIEW_MODE||'':'','':MSG:'') > 0 then',
'      if c1.result_rows is not null then',
'        if c1.result_rows = 1 then ',
'        	 sys.htp.prn(wwv_flow_lang.system_message(',
'        	          ''WWV_FLOW_SW_SCRIPT.RESULT_ROW'',',
'        	          to_char(c1.Result_Rows,''999G999G999G999G999G999G990'')',
'        	          ));                ',
'        else         ',
'           sys.htp.prn(wwv_flow_lang.system_message(',
'        	          ''WWV_FLOW_SW_SCRIPT.RESULT_ROWS'',',
'        	          to_char(c1.Result_Rows,''999G999G999G999G999G999G990'')',
'        	          ));',
'        end if;',
'      end if;',
'    end if;*/',
'  ',
'    -- elap time',
'    if instr('':''||:P1225_VIEW_MODE||'':'','':MSG:'') > 0 then ',
'      if sign(c1.end_time-c1.start_time) = -1 then',
'        l_elapsed := 24*60*60*(nvl(c1.ended,sysdate) - c1.started);',
'      else',
'        l_elapsed := c1.end_time-c1.start_time;',
'      end if;',
'      l_elapsed := l_elapsed/100;',
'      ',
'      -- don''t show elapsed time for result with errors',
'      if sys.dbms_lob.instr(c1.msg,''ORA-'',1,1) > 0 then',
'        l_elapsed := null;',
'      end if;',
'      ',
'      if l_elapsed is not null then',
'        sys.htp.prn('' ''||wwv_flow_lang.system_message(',
'                  ''WWV_FLOW_SW_SCRIPT.ELAPSED'',',
'                  to_char(l_elapsed,''999G999G999G999G990D00'')',
'                  ));',
'      end if;',
'    end if;',
'  ',
'    -- end of statement',
'    sys.htp.prn(''<hr />'');',
'  end loop;',
'  sys.htp.prn(''</span>'');',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_plug_query_headings_type=>'QUERY_COLUMNS'
,p_plug_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_plug_query_show_nulls_as=>' - '
,p_plug_display_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_plug_display_when_condition=>'P1225_VIEW'
,p_plug_display_when_cond2=>'DETAIL'
,p_pagination_display_position=>'BOTTOM_RIGHT'
);
