wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(14654103993650366.4501)
,p_name=>'Resultados'
,p_template=>wwv_flow_imp.id(380771699411878611.4501)
,p_display_sequence=>30
,p_region_template_options=>'#DEFAULT#:a-Region--noPadding'
,p_component_template_options=>'#DEFAULT#:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select object_type, object_name, table_name, ',
'       decode(schema1,0,null,''<span class="a-Icon icon-check"></span>'') schema1, ',
'       decode(schema2,0,null,''<span class="a-Icon icon-check"></span>'') schema2',
'from (',
'select',
'  ''TABLE.TRIGGER'' object_type,',
'  table_name object_name,',
'  TABLE_NAME||''.''||TRIGGER_NAME||''.''||TRIGGER_TYPE||''.''||',
'    TRIGGERING_EVENT||''.''||WHEN_CLAUSE||''.''||ACTION_TYPE table_name,',
'  sum(decode(OWNER,:P1350_SCHEMA_1,1,0)) schema1,',
'  sum(decode(OWNER,:P1350_SCHEMA_2,1,0)) schema2',
'from sys.dba_triggers',
'where (OWNER = :P1350_SCHEMA_1 or OWNER = :P1350_SCHEMA_2) and',
'      TABLE_NAME not like ''BIN$%'' and',
'      TABLE_NAME not like ''DR$%'' and',
'(:P1350_SEARCH is null or instr(upper(TABLE_NAME)||''.''||upper(trigger_name),upper(:P1350_SEARCH))>0) and',
'(:P1350_COMPARE = ''0'' or :P1350_COMPARE = ''TRIGGER'')',
'group by table_name, TABLE_NAME||''.''||TRIGGER_NAME||''.''||TRIGGER_TYPE||''.''||',
'    TRIGGERING_EVENT||''.''||WHEN_CLAUSE||''.''||ACTION_TYPE ',
'union all',
'select',
'  ''SEQUENCE'' object_type,',
'  sequence_name object_name,',
'  SEQUENCE_NAME||''.''||INCREMENT_BY||''.''||',
'    CYCLE_FLAG||''.''||ORDER_FLAG||''.''||CACHE_SIZE table_name,',
'  sum(decode(sequence_owner,:P1350_SCHEMA_1,1,0)) schema1,',
'  sum(decode(sequence_owner,:P1350_SCHEMA_2,1,0)) schema2',
'from sys.dba_sequences',
'where (sequence_owner = :P1350_SCHEMA_1 or sequence_owner = :P1350_SCHEMA_2) and',
'      SEQUENCE_NAME not like ''BIN$%'' and',
'      SEQUENCE_NAME not like ''DR$%'' and',
'(:P1350_SEARCH is null or instr(upper(SEQUENCE_NAME),upper(:P1350_SEARCH))>0) and',
'(:P1350_COMPARE = ''0'' or :P1350_COMPARE = ''SEQUENCE'')',
'group by sequence_name, SEQUENCE_NAME||''.''||INCREMENT_BY||''.''||CYCLE_FLAG||''.''||ORDER_FLAG||''.''||CACHE_SIZE',
'union all',
'select type object_type, ',
'       object_name,',
'       table_name, ',
'       sum(decode(owner,:P1350_SCHEMA_1,1,0)) schema1,',
'       sum(decode(owner,:P1350_SCHEMA_2,1,0)) schema2',
'from (',
'select type, name object_name, name||''.''||type||'' ''||t.l_lines||''=''||max(line)||'' ''||t.l_size||''=''||sum(length(text)) table_name, owner',
'from sys.dba_source s,',
'     (select wwv_flow_lang.system_message(''LINES'') l_lines,',
'             wwv_flow_lang.system_message(''SIZE'') l_size',
'      from sys.dual) t',
'where owner in (:P1350_SCHEMA_1,:P1350_SCHEMA_2) and',
'      name not like ''BIN$%'' and',
'      name not like ''DR$%'' and',
'      (:P1350_SEARCH is null or instr(upper(name),upper(:P1350_SEARCH))>0) and',
'      (:P1350_COMPARE = ''0'' or :P1350_COMPARE = type)',
'group by owner, name,type, t.l_lines, t.l_size ) plsql',
'group by type, object_name, table_name',
'union all',
'select',
'  ''TABLE'' object_type,',
'  t.table_name object_name,',
'  t.table_name,',
'  sum(decode(t.owner,:P1350_SCHEMA_1,1,0)) schema1,',
'  sum(decode(t.owner,:P1350_SCHEMA_2,1,0)) schema2',
'from sys.dba_tables t',
'where (owner = :P1350_SCHEMA_1 or owner = :P1350_SCHEMA_2) and',
'      table_name not like ''BIN$%'' and',
'      table_name not like ''DR$%'' and',
'(:P1350_SEARCH is null or instr(upper(table_name),upper(:P1350_SEARCH))>0) and',
'(:P1350_COMPARE = ''0'' or :P1350_COMPARE = ''TABLE'')',
'group by t.table_name',
'union all',
'select',
'  ''VIEW'' object_type,',
'  t.view_name object_name,',
'  t.view_name table_name,',
'  sum(decode(t.owner,:P1350_SCHEMA_1,1,0)) schema1,',
'  sum(decode(t.owner,:P1350_SCHEMA_2,1,0)) schema2',
'from sys.dba_views t',
'where (owner = :P1350_SCHEMA_1 or owner = :P1350_SCHEMA_2) and',
'      view_name not like ''BIN$%'' and',
'      view_name not like ''DR$%'' and',
'(:P1350_SEARCH is null or instr(upper(view_name),upper(:P1350_SEARCH))>0) and',
'(:P1350_COMPARE = ''0'' or :P1350_COMPARE = ''VIEW'')',
'group by t.view_name',
'union all',
'select',
'  ''TABLE.COLUMN'' object_type,',
'  t.table_name||''.''||t.column_name object_name,',
'  t.table_name||''.''||t.column_name table_name,',
'  sum(decode(t.owner,:P1350_SCHEMA_1,1,0)) schema1,',
'  sum(decode(t.owner,:P1350_SCHEMA_2,1,0)) schema2',
'from sys.dba_tab_columns t',
'where (owner = :P1350_SCHEMA_1 or owner = :P1350_SCHEMA_2) and',
'      table_name not like ''BIN$%'' and',
'      table_name not like ''DR$%'' and',
'(:P1350_SEARCH is null or instr(upper(table_name),upper(:P1350_SEARCH))>0) and',
'(:P1350_COMPARE = ''0'' or :P1350_COMPARE = ''COLUMN'')',
'group by t.table_name||''.''||t.column_name',
'union all',
'select',
'  ''TABLE.COLUMN.DATATYPE'' object_type,',
'  t.table_name||''.''||t.column_name||''.''||data_type object_name,',
'  t.table_name||''.''||t.column_name||''.''||data_type||''.''||',
'   data_length||''.''||data_scale||''.''||DATA_PRECISION||''.''||nullable table_name,',
'  sum(decode(t.owner,:P1350_SCHEMA_1,1,0)) schema1,',
'  sum(decode(t.owner,:P1350_SCHEMA_2,1,0)) schema2',
'from sys.dba_tab_columns t',
'where (owner = :P1350_SCHEMA_1 or owner = :P1350_SCHEMA_2) and',
'      table_name not like ''BIN$%'' and',
'      table_name not like ''DR$%'' and',
'(:P1350_SEARCH is null or instr(upper(table_name),upper(:P1350_SEARCH))>0) and',
'(:P1350_COMPARE = ''0'' or :P1350_COMPARE = ''DATATYPE'')',
'group by t.table_name||''.''||t.column_name||''.''||data_type,',
'         t.table_name||''.''||t.column_name||''.''||data_type||''.''||',
'          data_length||''.''||data_scale||''.''||DATA_PRECISION||''.''||nullable',
'union all',
'select ''TABLE.INDEX'' object_type,',
'       object_name,',
'       table_name,',
'       sum(decode(table_owner,:P1350_SCHEMA_1,1,0)) schema1,',
'       sum(decode(table_owner,:P1350_SCHEMA_2,1,0)) schema2',
'from (',
'    select table_owner,',
'           table_name||'' ''||uniqueness||'' (''||',
'           max(decode(position,1 ,column_name))||',
'           max(decode(position,2 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,3 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,4 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,5 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,6 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,7 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,8 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,9 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,10,'',''||substr(column_name,1,128)))||'')''',
'           object_name,',
'           table_name||''.''||',
'           decode(substr(index_name,1,4),''SYS_'',''SYS'',index_name',
'           )||''.''||uniqueness||'':''||',
'           max(decode(position,1 ,column_name))||',
'           max(decode(position,2 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,3 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,4 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,5 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,6 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,7 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,8 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,9 ,'',''||substr(column_name,1,128)))||',
'           max(decode(position,10,'',''||substr(column_name,1,128)))',
'           table_name',
'     from(',
'        select dc.table_name, dc.table_owner,dc.index_name,di.uniqueness, di.status,',
'               di.index_type, di.temporary, di.partitioned,di.funcidx_status, di.join_index,',
'               dc.column_name,dc.column_position position',
'          from sys.dba_ind_columns dc,sys.dba_indexes di',
'         where dc.table_owner in (:P1350_SCHEMA_1,:P1350_SCHEMA_2)',
'           and dc.table_name not like ''BIN$%''',
'           and dc.table_name not like ''DR$%''',
'           and dc.index_name = di.index_name',
'           and dc.index_owner = di.owner ',
'           and (:P1350_SEARCH is null or instr(upper(dc.table_name),upper(:P1350_SEARCH))>0)',
'           and (:P1350_COMPARE = ''0'' or :P1350_COMPARE = ''INDEX'')',
'           )',
'    group by table_name,table_owner,index_name,uniqueness, status,',
'             index_type, temporary, partitioned,funcidx_status, join_index',
') idx',
'group by object_name, table_name)',
'full_query',
'where (',
'      nvl(:P1350_SHOW_DELTA,''N'')=''N'' or ',
'      (nvl(:P1350_SHOW_DELTA,''N'')=''Y'' and schema1 != schema2)',
'      )',
'order by 1, 2'))
,p_display_when_condition=>'nvl(:P1350_SCHEMA_1,''0'') != ''0'' and nvl(:P1350_SCHEMA_2,''0'') != ''0'''
