wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(2100719213955804.4501)
,p_name=>'P2000_OB_SCHEMA'
,p_item_sequence=>30
,p_item_plug_id=>wwv_flow_imp.id(387994680244652086.4501)
,p_prompt=>'Esquema'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'  select c.schema d, c.id v',
'    from wwv_flow_company_schemas c,',
'         wwv_flow_fnd_user u',
'   where c.security_group_id = u.security_group_id',
'     and c.security_group_id = :flow_security_group_id',
'     and u.user_name = :flow_user',
'     and (u.ALLOW_ACCESS_TO_SCHEMAS is null or',
'          instr( '':''||u.ALLOW_ACCESS_TO_SCHEMAS||'':'', '':''||c.schema||'':'' ) > 0 )',
