wwv_flow_imp_page.create_page_item(
 p_id=>wwv_flow_imp.id(190782079755520608.4501)
,p_name=>'P2000_MODULE_OWNER'
,p_item_sequence=>40
,p_item_plug_id=>wwv_flow_imp.id(190781682631520604.4501)
,p_prompt=>'&"APP_TEXT$OB.COL_MODULE_OWNER".'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select schema d,',
'       schema r',
'  from (',
'    select c.schema',
'      from wwv_flow_company_schemas c,',
'           wwv_flow_fnd_user u',
'     where c.security_group_id = u.security_group_id',
'       and c.security_group_id = :flow_security_group_id',
'       and u.user_name = :flow_user',
'       and (u.allow_access_to_schemas is null or',
'            instr( '':''||u.allow_access_to_schemas||'':'', '':''||c.schema||'':'' ) > 0 )',
'',
'     union',
'',
'     select distinct owner as schema',
'      from ( select o.owner, o.owner as grantee, o.object_type, o.object_name',
'               from sys.dba_objects o',
'              union',
'             select p.owner, p.grantee, p.type, p.table_name',
'               from sys.dba_tab_privs p ) o',
'     where o.object_type = ''MLE MODULE''',
'       and o.grantee in ( :P2000_SCHEMA_HELPER, ''PUBLIC'' )',
'  )'))
,p_lov_display_null=>'YES'
,p_lov_cascade_parent_items=>'P2000_SCHEMA_HELPER'
,p_ajax_items_to_submit=>'P2000_SCHEMA_HELPER'
,p_ajax_optimize_refresh=>'Y'
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(488671190365029680.4501)
,p_item_template_options=>'#DEFAULT#'
,p_warn_on_unsaved_changes=>'I'
,p_lov_display_extra=>'YES'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'page_action_on_selection', 'NONE')).to_clob
);
