,p_prompt=>'Propietario del Objeto'
,p_display_as=>'NATIVE_SELECT_LIST'
,p_lov=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select schema d, schema r',
'from (',
'    select :P2010_PARSING_SCHEMA schema',
'      from sys.dual',
'     union',
'    select p.owner schema',
'      from sys.dba_tab_privs p',
'     where p.grantee           = :P2010_PARSING_SCHEMA',
'       -- P2010_PARSING_SCHEMA is always limited to workspace schemas',
'       -- so no additional checks required ',
'       and p.owner      not in (''SYS'', ''SYSTEM'')',
'       and p.privilege  in (''SELECT'', ''READ''))',
'order by 1 '))
,p_cHeight=>1
,p_field_template=>wwv_flow_imp.id(488671190365029680.4501)
