'declare',
'    l_error_text    varchar2(4000)  := null;',
'begin',
'    select listagg(c001,  '', '' on overflow truncate) within group (order by c001)',
'      into l_error_text',
'      from (',
'          select distinct c001',
'            from wwv_flow_collections',
'           where collection_name = ''TBL_WIZ_COLUMNS''',
'           group by c001',
'          having count(*) > 1 );',
'',
'    if l_error_text is not null then',
'        return wwv_flow_lang.message(''OB.DUP_COL_FOUND'',wwv_flow_escape.html(l_error_text));',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
