wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2504403716718542.4501)
,p_process_sequence=>10
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_region_id=>wwv_flow_imp.id(2500606111718504.4501)
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Update Collection TBL_WIZ_COLUMNS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_collection_name varchar2(20) := ''TBL_WIZ_COLUMNS'';',
'begin',
'    case :APEX$ROW_STATUS',
'    when ''C'' then',
'        wwv_flow_collection.add_member(',
'            p_collection_name => l_collection_name,',
'            p_c001            => :COLUMN_NAME,',
'            p_c002            => :DATA_TYPE,',
'            p_c003            => :DATA_PRECISION,',
'            p_c004            => :DATA_SCALE,',
'            p_c005            => :NOT_NULL,',
'            p_c006            => case when :PRIMARY_KEY = ''N'' then :DEFAULT_VALUE end,',
'            p_c007            => :PRIMARY_KEY,',
'            p_c008            => :COLUMN_COMMENTS,',
'            p_n001            => :SORT_ORDER );',
'    when ''U'' then',
'        wwv_flow_collection.update_member(',
'            p_collection_name => l_collection_name,',
'            p_seq             => :SEQ_ID,',
'            p_c001            => :COLUMN_NAME,',
'            p_c002            => :DATA_TYPE,',
'            p_c003            => :DATA_PRECISION,',
'            p_c004            => :DATA_SCALE,',
'            p_c005            => :NOT_NULL,',
'            p_c006            => case when :PRIMARY_KEY = ''N'' then :DEFAULT_VALUE end,',
'            p_c007            => :PRIMARY_KEY,',
'            p_c008            => :COLUMN_COMMENTS,',
'            p_n001            => :SORT_ORDER );',
'    when ''D'' then',
'        wwv_flow_collection.delete_member(',
'            p_collection_name => l_collection_name,',
'            p_seq             => :SEQ_ID );',
'    end case;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>2504403716718542.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(6801180864730230.4501)
,p_process_sequence=>30
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Populate PK_SOURCE in TBL_WIZ_COLUMNS'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_seq_id number;',
'    l_collection_name varchar2(20) := ''TBL_WIZ_COLUMNS'';',
'begin',
'    -- this process is executed only when 1 column is selected as PK column',
'    -- so this query must execute with out any exception',
'    select seq_id',
'      into l_seq_id',
'      from wwv_flow_collections',
'     where collection_name = l_collection_name',
'       and c007            = ''Y''; ',
'',
'    -- for PK column, set c009 value as IDENTITY',
'    -- we need this info to add default value for PK column',
'    wwv_flow_collection.update_member_attribute (',
'        p_collection_name => l_collection_name,',
'        p_seq             => l_seq_id,',
'        p_attr_number     => 9,',
'        p_attr_value      => ''IDENTITY'' );     ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select *',
'  from sys.dual',
' where (',
'-- only one column selected as PK',
'select count(*)',
'  from wwv_flow_collections',
' where collection_name = ''TBL_WIZ_COLUMNS''',
'   and c007            = ''Y'' ) = 1',
'and (',
'-- and data type is NUMBER or FLOAT for PK column',
'select count(*)',
'  from wwv_flow_collections',
' where collection_name = ''TBL_WIZ_COLUMNS''',
'   and c007            = ''Y''',
'   and c002            in (''NUMBER'',''FLOAT'') ) = 1'))
,p_process_when_type=>'EXISTS'
,p_internal_uid=>6801180864730230.4501
);
end;
