wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(5612393413023848.4501)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get Metadata'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_metadata wwv_flow_t_varchar2 := wwv_flow_t_varchar2();',
'begin',
'    case when :P2026_EDIT = ''YES'' then ',
'        l_metadata := wwv_flow_string.split(',
'                        wwv_flow_f4500_ob_wiz_dev.get_geom_metadata(',
'                            p_owner         => :P2025_PARSING_SCHEMA,',
'                            p_table_name    => :P2026_TABLE,',
'                            p_column_name   => :P2026_COLUMN_NAME ), '':'' );',
'',
'        if l_metadata.count = 7 then',
'            :P2026_SRID     := l_metadata( 1 );',
'            :P2026_DIMX_MIN := l_metadata( 2 );',
'            :P2026_DIMX_MAX := l_metadata( 3 );',
'            :P2026_DIMX_TOL := l_metadata( 4 );',
'            :P2026_DIMY_MIN := l_metadata( 5 );',
'            :P2026_DIMY_MAX := l_metadata( 6 );',
'            :P2026_DIMY_TOL := l_metadata( 7 );',
'        end if;',
'    else',
'        :P2026_SRID     := ''4326'';',
'        :P2026_DIMX_MIN := ''-180'';',
'        :P2026_DIMX_MAX := ''180'';',
'        :P2026_DIMX_TOL := 0.05;',
'        :P2026_DIMY_MIN := ''-90'';',
'        :P2026_DIMY_MAX := ''90'';',
'        :P2026_DIMY_TOL := 0.05;',
'    end case;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>5612393413023848.4501
);
end;
