wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(4400702843942462.4501)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Run DDL'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_db_link_name varchar2(128);',
'begin',
'    :P2070_OBJECT_TYPE := ''DATABASE_LINK'';',
'    ',
'    -- depending on DB settings, we may need to append domain name to db link name',
'    -- in UI it''s not possible to append domain name, because it will throw invalid object name error',
'    -- if we just pass db-link name with-out domain name, Oracle will automatically append it for us',
'    -- we need this full name before, so we can compute object id and also we can use it to set P2070_NAME item value',
'    l_db_link_name := wwv_flow_f4500_ob_wiz_dev.get_full_db_link_name(:P2070_NAME);',
'    ',
'    :P2070_OBJECT_ID := wwv_flow_f4500_ob_wiz_dev.create_object(',
'                            p_object_name     => l_db_link_name,',
'                            p_object_type     => :P2070_OBJECT_TYPE,',
'                            p_parsing_schema  => :P2070_PARSING_SCHEMA,',
'                            p_ddl             => :P2070_DDL );',
'',
'    if :P2070_OBJECT_ID is not null then',
'        :P2070_NAME := l_db_link_name;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2738356251375186.4501)
,p_process_success_message=>'El enlace de base de datos se ha creado correctamente.'
,p_internal_uid=>4400702843942462.4501
);
