wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(1621706117834617.4501)
,p_name=>'Datos Analizados'
,p_region_name=>'preview_table'
,p_parent_plug_id=>wwv_flow_imp.id(1697074737214101.4501)
,p_template=>wwv_flow_imp.id(385770331595976651.4501)
,p_display_sequence=>50
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--staticRowColors:a-Report--horizontalBorders:a-Report--stretch'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select line_number, ',
'       substr( col001, 1, 500 ) col001, ',
'       substr( col002, 1, 500 ) col002, ',
'       substr( col003, 1, 500 ) col003, ',
'       substr( col004, 1, 500 ) col004, ',
'       substr( col005, 1, 500 ) col005, ',
'       substr( col006, 1, 500 ) col006, ',
'       substr( col007, 1, 500 ) col007, ',
'       substr( col008, 1, 500 ) col008, ',
'       substr( col009, 1, 500 ) col009, ',
'       substr( col010, 1, 500 ) col010 ',
'from wwv_flow_temp_files f, ',
'     table( wwv_flow_data_parser.parse(',
'                p_content               => f.blob_content,',
'                p_file_name             => f.filename,',
'                --   ',
'                p_add_headers_row       => ''Y'',',
'                -- please *always* set p_max_rows as a safeguard against fully parsing large files',
'                p_max_rows              => nullif(:P3100_MAX_ROW_COUNT, ''0''),',
'                -- for parser to return p_return_rows, region max rows must be > p_return_rows',
'                p_return_rows           => 5,',
'                p_xlsx_sheet_name       => ( case when :P3100_FILE_TYPE = 1 and :P3100_XLSX_SHEET is not null then :P3100_XLSX_SHEET end ),',
'                p_csv_col_delimiter     => replace(:P3100_CSV_COL_DELIMITER, ''tab'', chr(9) ),',
'                p_file_charset          => coalesce( :P3100_FILE_CHARSET, ''AL32UTF8'' ),',
'                p_csv_enclosed          => nullif( :P3100_CSV_ENCLOSED, ''None'' ),',
'                p_force_trim_whitespace => :P3120_TRIM_WHITESPACE,',
'                p_nullif                => :P3120_NULLIF )',
'                )',
'where f.name = :P3100_FILE',
'and :P3100_SOURCE_TYPE = ''FILE''',
'union all',
'select line_number, ',
'       substr( col001, 1, 500 ) col001, ',
'       substr( col002, 1, 500 ) col002, ',
'       substr( col003, 1, 500 ) col003, ',
'       substr( col004, 1, 500 ) col004, ',
'       substr( col005, 1, 500 ) col005, ',
'       substr( col006, 1, 500 ) col006, ',
'       substr( col007, 1, 500 ) col007, ',
'       substr( col008, 1, 500 ) col008, ',
'       substr( col009, 1, 500 ) col009, ',
'       substr( col010, 1, 500 ) col010 ',
'from wwv_flow_collections c, ',
'     table( wwv_flow_data_parser.parse(',
'                p_content               => c.blob001,',
'                p_file_type             => 2,',
'                --   ',
'                p_add_headers_row       => ''Y'',',
'                p_max_rows              => nullif(:P3100_MAX_ROW_COUNT, ''0''),',
'                -- for parser to return p_return_rows, region max rows must be > p_return_rows',
'                p_return_rows           => 5,',
'                p_csv_col_delimiter     => replace(:P3100_CSV_COL_DELIMITER, ''tab'', chr(9) ),',
'                p_file_charset          => coalesce( :P3100_FILE_CHARSET, ''AL32UTF8'' ),',
'                p_force_trim_whitespace => :P3120_TRIM_WHITESPACE,',
'                p_csv_enclosed          => nullif( :P3100_CSV_ENCLOSED, ''None'' ),',
'                p_nullif                => :P3120_NULLIF )',
'                )',
'where c.collection_name=''CLOB_CONTENT''',
'and :P3100_SOURCE_TYPE = ''COPY_PASTE'';',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_num_rows=>150
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_row_count_max=>150
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'N'
);
