wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(1753932155870113.4501)
,p_plug_name=>'get file profile and save'
,p_region_name=>'getFileProfile'
,p_parent_plug_id=>wwv_flow_imp.id(1697074737214101.4501)
,p_component_template_options=>'#DEFAULT#'
,p_plug_display_sequence=>60
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_profile             clob;',
'    l_file_content        blob;',
'    l_profile_record      wwv_flow_data_parser.t_file_profile;',
'begin',
'    l_profile        := wwv_flow_data_parser.get_file_profile;',
'    l_profile_record := wwv_flow_data_parser.json_to_profile( l_profile );',
'  ',
'    if :P3100_FIRST_LINE is null or :P3100_FIRST_LINE != ''HEADERS'' then',
'        for i in 1 .. l_profile_record.file_columns.count loop',
'            l_profile_record.file_columns( i ).name := ''COL'' || lpad( i,3,''0'');',
'        end loop;',
'        l_profile := wwv_flow_data_parser.profile_to_json(l_profile_record);',
'    end if;',
'    ',
'    -- save file profile in collection for later use',
'    wwv_flow_collection.create_or_truncate_collection( ''APEX$DATALOAD'' );',
'    wwv_flow_collection.add_member( ''APEX$DATALOAD'', p_clob001 => l_profile );',
'    ',
'    :P3100_FILE_TYPE           := l_profile_record.file_type;',
'    :P3100_CSV_COL_DELIMITER   := l_profile_record.csv_delimiter;',
'    :P3100_NEW_COL_DELIMITER   := ( case when l_profile_record.csv_delimiter = chr(9) then ''tab'' else l_profile_record.csv_delimiter end );',
'    :P3100_PARSED_ROW_COUNT    := l_profile_record.parsed_rows;',
'    ',
'    if l_profile_record.file_columns.count <= 10 then',
'        :P3100_PARSED_COLUMN_COUNT := l_profile_record.file_columns.count;',
'    else',
'        :P3100_PARSED_COLUMN_COUNT := 10;',
'    end if;',
'',
'    :P3100_FILE_COLUMN_COUNT   := l_profile_record.file_columns.count;',
'    :P3100_FILE_INVALID        := case when l_profile_record.file_columns.count > 0 ',
'                                      then ''N'' ',
'                                      else ''Y'' ',
'                                  end;',
'exception',
'    when others then',
'        :P3100_FILE_INVALID := ''Y'';',
'        wwv_flow_collection.create_or_truncate_collection( ''APEX$DATALOAD'' );',
'end;'))
,p_plug_source_type=>'NATIVE_PLSQL'
,p_translate_title=>'N'
,p_plug_query_options=>'DERIVED_REPORT_COLUMNS'
);
