,p_function_body_language=>'PLSQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_info           varchar2(32767);',
'    l_mapped_col_cnt number;',
'    l_file_col_cnt   number;',
'begin',
'    l_mapped_col_cnt := to_number(:P3100_MAPPED_COLUMN_COUNT);',
'    l_file_col_cnt := to_number(:P3100_FILE_COLUMN_COUNT);',
'    ',
'    if :P3100_LOAD_TO = ''EXISTING'' then',
'        if l_mapped_col_cnt = 0 then',
'            l_info := wwv_flow_lang.system_message( ''DATA.LOAD.DEFINE_COL_MAPPING'', wwv_flow_escape.html(:P3100_EXISTING_TABLE ));',
'        else',
'            if l_mapped_col_cnt = l_file_col_cnt then',
'                l_info := wwv_flow_lang.system_message( ''DATA.LOAD.ALL_COL_MAPPED'', :P3100_FILE_COLUMN_COUNT, wwv_flow_escape.html(:P3100_EXISTING_TABLE ) );',
'            elsif l_mapped_col_cnt < l_file_col_cnt then',
'                l_info := wwv_flow_lang.system_message( ''DATA.LOAD.MAP_REMAINING_COLS'', :P3100_MAPPED_COLUMN_COUNT, :P3100_FILE_COLUMN_COUNT, wwv_flow_escape.html(:P3100_EXISTING_TABLE ) );',
'            end if;',
'        end if;',
'    else',
'        l_info := wwv_flow_lang.system_message(''DATA.LOAD.SELECT_COLS'');',
'    end if;',
'',
'    return ''select ''||wwv_flow_assert.enquote_literal(l_info)||'' info from sys.dual'';',
'end;'))
