,p_computation_point=>'AFTER_HEADER'
,p_computation_type=>'STATIC_ASSIGNMENT'
,p_compute_when=>'P3100_FIRST_LINE'
,p_compute_when_text=>'CHANGE_TO_NULL'
,p_compute_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
