wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(2829413078927250.4501)
,p_validation_name=>'cannot load until other jobs finish'
,p_validation_sequence=>100
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_running_job_cnt number;',
'begin',
'',
'    select count(*) into l_running_job_cnt',
'     from user_scheduler_jobs j, wwv_flow_companies c',
'    where job_name like ''ORACLE_APEX_DTLD$%''',
'      --',
'      and c.provisioning_company_id = regexp_substr( comments, ''(\:)(.*?)(\:)'',1,1,''i'',2 )',
'      and c.display_name = :COMPANY  ',
'      -- ',
'      and state   = ''RUNNING''',
'      and rownum <= ( wwv_flow_data_loader.c_max_jobs_per_apex_session + 1 ) ;',
'    ',
'    if l_running_job_cnt >= wwv_flow_data_loader.c_max_jobs_per_apex_session then',
'        return false;',
'    else',
'        return true;',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('Todav\00EDa se est\00E1n ejecutando otros trabajos para la carga de datos. Espere a que terminen de ejecutarse.')
,p_when_button_pressed=>wwv_flow_imp.id(1620874202834608.4501)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(74472471070949601.4501)
,p_validation_name=>'uploaded file is too large'
,p_validation_sequence=>110
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_size         number;',
'    l_overall_file_size number := wwv_flow_platform.get_preference(''DATA_LOADING_MAX_FILE_SIZE'');',
'begin',
'    begin',
'        select sys.dbms_lob.getlength( blob_content )',
'          into l_file_size',
'          from wwv_flow_temp_files',
'         where name = :P3100_FILE;',
'    exception ',
'        when NO_DATA_FOUND then',
'            return null;',
'        when TOO_MANY_ROWS then',
'            return null;',
'    end;',
'    ',
'    -- overall file size limit, configured in instance settings',
'    if l_overall_file_size is not null and l_file_size > l_overall_file_size then',
'        :P3100_FILE := null;',
'        return wwv_flow_lang.system_message( p_name => ''WWV_FLOW_DATA_PARSER.FILE_TOO_LARGE'',',
'                                             p0     => '''',',
'                                             p1     => round( l_overall_file_size / 1048576 ) );    ',
'    end if;',
'    ',
'    -- specific file size limits',
'    if :P3100_FILE like ''%xml'' then',
'        if l_file_size > 104857600 then',
'            :P3100_FILE := null;',
'            return wwv_flow_lang.system_message( p_name => ''WWV_FLOW_DATA_PARSER.FILE_TOO_LARGE'',',
'                                                 p0     => ''XML'',',
'                                                 p1     => ''100'');',
'        end if;',
'    elsif :P3100_FILE like ''%xlsx'' then',
'        if l_file_size > 52428800 then',
'            :P3100_FILE := null;',
'            return wwv_flow_lang.system_message( p_name => ''WWV_FLOW_DATA_PARSER.FILE_TOO_LARGE'',',
'                                                 p0     => ''XLSX'',',
'                                                 p1     => ''50'' );',
'        end if;',
'    end if;',
'    ',
'    return null;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'UPLOAD_FILE'
,p_validation_condition_type=>'REQUEST_EQUALS_CONDITION'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_validation_comment=>'this safeguards against uploading too large XML and XLSX files. Both are processed by database XML functions which consume too much PGA memory for large files.'
);
