wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(82704685257738119.4501)
,p_validation_name=>'CLOB column must be mapped to CLOB'
,p_validation_sequence=>160
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_profile     wwv_flow_data_parser.t_file_profile;',
'    l_profile          clob;',
'begin',
'    select clob001 into l_profile ',
'    from wwv_flow_collections ',
'    where collection_name =''APEX$DATALOAD''',
'    and rownum = 1;',
'',
'    l_file_profile := wwv_flow_data_parser.json_to_profile( p_json => l_profile );',
'    ',
'    for i in 1 .. l_file_profile.file_columns.count',
'    loop',
'        -- if data contains CLOB column',
'        if l_file_profile.file_columns( i ).data_type = wwv_flow_exec_api.c_data_type_clob then',
'            -- get user configured mapping',
'            for l_configure in (',
'                select',
'                    c002   mapped_column',
'                from wwv_flow_collections',
'                where collection_name = ''APEX$DATALOAD_COLUMNS''',
'                and c001 = l_file_profile.file_columns( i ).name )',
'            loop',
'                -- get mapped column data type',
'                -- if CLOB column not mapped to CLOB column, raise error',
'                for l_mapped_column in (',
'                    select data_type',
'                    from sys.dba_tab_columns',
'                    where owner = :P3100_TABLE_OWNER',
'                    and table_name = :P3100_EXISTING_TABLE',
'                    and column_name = l_configure.mapped_column )',
'                loop',
'                    if l_mapped_column.data_type != ''CLOB'' then',
'                       return false;',
'                    end if;',
'                end loop;',
'            end loop;',
'        end if;',
'    end loop;',
'',
'    -- if there are no user configured mapping and not clob column, pass the validation',
'    return true;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>'La columna CLOB se ha asignado al tipo de datos de columna incorrecto. Asigne la columna a otra columna CLOB.'
,p_validation_condition=>'P3100_LOAD_TO'
,p_validation_condition2=>'EXISTING'
,p_validation_condition_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_when_button_pressed=>wwv_flow_imp.id(1620874202834608.4501)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
