wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(4093314800018707.4501)
,p_event_id=>wwv_flow_imp.id(4093020088018704.4501)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// replace column count placeholders in header text of parsed data preview region',
'$( "#placeholder_P3100_PARSED_COLUMN_COUNT" ).text( $v( "P3100_PARSED_COLUMN_COUNT" ) );',
'$( "#placeholder_P3100_PARSED_ROW_COUNT"    ).text( $v( "P3100_PARSED_ROW_COUNT"    ) );',
'',
'// set the column delimiter radio group to the actual value, which ',
'// is being determined *after* the item has been rendered, so the browser does not have the correct state.',
'$s( "P3100_CSV_COL_DELIMITER", $v("P3100_NEW_COL_DELIMITER") );',
'',
'// if the file has less than 10 columns: Adjust the header text and hide the "expand preview" button',
'// if ( parseInt( $v( "P3100_PARSED_COLUMN_COUNT" ) ) <= 10 ) {',
'//     $( "span#placeholder_gt10_columns" ).css( "display", "none" );',
'//     $( "#bt-full-preview"              ).css( "display", "none" );',
'// }',
'',
'// if the Invalid File Item is set (wrong extension, parser errors), hide the "Load into Table Region"',
'if ( $v( "P3100_FILE_INVALID" ) === "Y" ) {',
'    $( "#load-to-table"        ).css( "display", "none" );',
'    $( "#preview_table p.desc" ).css( "display", "none" );',
'   // $( "#settings"             ).css( "display", "none" );',
'    $( "#bt-full-preview"      ).css( "display", "none" );',
'}',
'',
'// shared functions',
'var getColId = function( id ){',
'    var int = parseInt( id ), i;',
'    if ( int <= 9 ) {',
'            i = ''COL00'' + int;',
'        } else if ( int > 9 && int <= 99 ) {',
'            i = ''COL0'' + int;',
'        } else {',
'            i = ''COL'' + int;',
'        }',
'    return i;',
'};',
'',
'var toggleCol = function ( columnId, isShowing ) {',
'    if ( columnId ) {',
'        var header$  = $( ''#'' + columnId ),',
'            body$    = $( ''td[headers='' + columnId + '']'' );',
'',
'        if ( isShowing ) {',
'            header$.show();',
'            body$.show();',
'        } else {',
'            header$.hide();',
'            body$.hide();',
'        }',
'    }',
'};',
'',
'// hide empty columns',
'( function () {',
'    var hideGreaterThan = parseInt( $v(''P3100_PARSED_COLUMN_COUNT'') ) + 1,',
'        emptyColId;',
'',
'        for ( i = hideGreaterThan; i <= 100; i++ ) {',
'            emptyColId = getColId( i );',
'            toggleCol( emptyColId, false );',
'        }',
'',
'})();'))
);
