wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(212735502054785616.4501)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'copy and paste load change clob to blob'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_seq_id number;',
'    l_clob   clob;',
'begin',
'    select seq_id, ',
'           clob001',
'      into l_seq_id, ',
'           l_clob',
'      from wwv_flow_collections',
'     where collection_name = ''CLOB_CONTENT'';',
'    ',
'    wwv_flow_collection.update_member(',
'        p_collection_name => ''CLOB_CONTENT'',',
'        p_seq             => l_seq_id,',
'        p_clob001         => l_clob,',
'        p_blob001         => wwv_flow_utilities.clob_to_blob( p_clob => l_clob ) );',
'end;         ',
'            ',
'    '))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'NEXT'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_internal_uid=>212735502054785616.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3511555467397550.4501)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load to New Table'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_dummy_message varchar2(32767);',
'begin',
'    wwv_flow_data_loader_dev.load_to_new_table(',
'        p_source_type       => :P3100_SOURCE_TYPE,',
'        p_file_name         => :P3100_FILE,',
'        --',
'        p_target_schema     => :P3100_TABLE_OWNER,',
'        p_target_name       => :P3100_TABLE_NAME,',
'        p_error_table_name  => :P3100_ERROR_TABLE,',
'        --',
'        p_add_id_column     => true,',
'        p_force_sysguid_id  => :P3100_FORCE_SYSGUID_ID = ''Y'',',
'        p_skip_rows         => ( case when :P3100_FIRST_LINE     = ''HEADERS'' and :P3100_FILE_TYPE in ( ''1'', ''2'' ) then 1    else 0     end ),',
'        p_use_column_names  => ( case when :P3100_FIRST_LINE     = ''HEADERS''                                      then true else false end ),',
'        p_use_data_types    => ( case when :P3100_USE_DATA_TYPES = ''Y''                                            then true else false end ),',
'        -- ',
'        p_load_id           => :P3100_LOAD_ID,',
'        p_message           => l_dummy_message );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(1620874202834608.4501)
,p_process_when=>'P3100_LOAD_TO'
,p_process_when_type=>'VAL_OF_ITEM_IN_COND_EQ_COND2'
,p_process_when2=>'NEW'
,p_internal_uid=>3511555467397550.4501
);
