wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1624133201834641.4501)
,p_process_sequence=>30
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Get File Info'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_profile_record wwv_flow_data_parser.t_file_profile;',
'begin',
'    if not :P3100_FILE like ''[Downloaded_File]%'' then',
'        -- get the file name',
'        select filename, sys.dbms_lob.getlength( blob_content) as file_size',
'        into :P3100_FILE_NAME, :P3100_FILE_SIZE',
'        from wwv_flow_temp_files ',
'        where name = :P3100_FILE;',
'    else',
'        :P3100_FILE_NAME := :P3100_FILE;',
'    end if;',
'    ',
'    if :P3100_SOURCE_TYPE is null then',
'        wwv_flow_collection.create_or_truncate_collection( ''APEX$DATALOAD_COLUMNS'' );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>1624133201834641.4501
);
