wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(212736324940785624.4501)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'get_sample_csv'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'  sys.owa_util.mime_header(''text/plain'', true );',
'  if :P3100_LOAD_SAMPLE = ''DEPT_EMP'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_emp_data);',
'  elsif :P3100_LOAD_SAMPLE = ''PROJECTS'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_project_data);',
'  elsif :P3100_LOAD_SAMPLE = ''SPEED'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_vehical_speed_data);',
'  elsif :P3100_LOAD_SAMPLE = ''SALES'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_sales_data);',
'  elsif :P3100_LOAD_SAMPLE = ''WORLD'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_country_population_data);',
'  elsif :P3100_LOAD_SAMPLE = ''ACADEMIC'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_ACADEMIC_data);',
'  elsif :P3100_LOAD_SAMPLE = ''JSON_TEST'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_json_test_data);',
'  elsif :P3100_LOAD_SAMPLE = ''JSON'' then',
'      sys.htp.prn(wwv_flow_define_app_v3.get_json_only_data);',
'  --elsif :P3100_LOAD_SAMPLE = ''TENNIS'' then',
'  --    sys.htp.prn(wwv_flow_define_app_v3.get_tennis_data);',
'  --elsif :P3100_LOAD_SAMPLE = ''WORLDCUP'' then',
'  --    sys.htp.prn(wwv_flow_define_app_v3.get_worldcup_data);',
'  --    wwv_htp.print_clob(wwv_flow_define_app_v3.get_worldcup_data);',
'  --elsif :P3100_LOAD_SAMPLE = ''F1'' then',
'  --    sys.htp.prn(wwv_flow_define_app_v3.get_f1_data);',
'  --elsif :P3100_LOAD_SAMPLE = ''MOVIE'' then',
'  --    sys.htp.prn(wwv_flow_define_app_v3.get_movie_data);',
'  end if;',
'  :P3100_FIRST_LINE := ''HEADERS'';',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>212736324940785624.4501
);
end;
