prompt --application/pages/page_03110
begin
wwv_flow_imp_page.create_page(
 p_id=>3110.4501
,p_name=>'Cargar Datos'
,p_alias=>'LOAD-DATA4'
,p_page_mode=>'MODAL'
,p_step_title=>'Cargar Datos'
,p_autocomplete_on_off=>'OFF'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'var lSpinner$ = apex.util.showSpinner( $( "#loadInProgress" ) );',
'',
'var showFinished = function(){',
'    // Hide Table Information',
'    apex.region("table_info").element.hide();',
'',
'    var lLoadTo = apex.item("P3110_LOAD_TO").getValue();',
'    var lTableCreated = apex.item( "P3110_TABLE_CREATED" ).getValue();',
'    var lBadRowCnt = apex.item( "P3110_BAD_ROW_CNT" ).getValue();',
'    var lSuccessRowCnt = apex.item("P3110_GOOD_ROW_CNT").getValue();',
'    var lProcessedRowCnt = apex.item( "P3110_PROCESSED_ROW_CNT" ).getValue();',
'    ',
'    var lBadRowCntDisp = apex.item( "P3110_BAD_ROW_CNT_DISP" ).getValue();',
'    var lSuccessRowCntDisp = apex.item("P3110_GOOD_ROW_CNT_DISP").getValue();',
'    var lProcessedRowCntDisp = apex.item( "P3110_PROCESSED_ROW_CNT_DISP" ).getValue();',
'    ',
'    if (lLoadTo === "NEW") {',
'        if (lTableCreated === "Y") {',
'            apex.jQuery("#viewTableBtn").show();',
'            apex.jQuery("#btn_cancel").hide();',
'        }',
'    } else if (lLoadTo === "EXISTING") {',
'        apex.jQuery("#viewTableBtn").show();',
'    }',
'    ',
'    if ( apex.item("P3110_LOAD_STATUS").getValue() === ''FAILED'' ) {',
'        // show failure region',
'',
'        apex.jQuery("#incompl_success_row_count").text( lSuccessRowCntDisp );',
'        apex.jQuery("#incompl_fail_row_count").text( lBadRowCntDisp );',
'        apex.jQuery("#imcompl_load_error").text( apex.item( "P3110_LOAD_ERROR" ).getValue() );        ',
'        apex.region("loadIncomplete").element.show();',
'        if (lTableCreated === "Y") {',
'                apex.jQuery("#dropTableBtn").show();',
'            };',
'        if (lBadRowCnt > "0") {',
'            apex.region("failed_rows").refresh()',
'            apex.region("failed_rows").element.show();',
'        }',
'    } else {',
'        ',
'        if ( lBadRowCnt === "0" ) {',
'            // show success region',
'            apex.jQuery("#success_row_count").text( lSuccessRowCntDisp );',
'            apex.region("loadSuccess").element.show();',
'            apex.jQuery("#createAppBtn").show();',
'            apex.jQuery("#btn_previous").hide();',
'        } else if ( lSuccessRowCnt > "0" && lBadRowCnt > "0" ) {',
'            // show error region',
'            apex.jQuery("#err_success_row_count").text( lSuccessRowCntDisp );',
'            apex.jQuery("#err_fail_row_count").text( lBadRowCntDisp );',
'            apex.region("loadError").element.show();',
'            apex.region("failed_rows").refresh()',
'            apex.region("failed_rows").element.show();',
'            apex.jQuery("#createAppBtn").show();',
'            if (lTableCreated === "Y") {',
'                apex.jQuery("#dropTableBtn").show();',
'            };',
'',
'        } else if ( lBadRowCnt === lProcessedRowCnt ) {',
'            // show failure region',
'            apex.jQuery("#fail_row_count").text( lBadRowCntDisp );',
'            apex.region("loadFail").element.show();',
'            apex.region("failed_rows").refresh()',
'            apex.region("failed_rows").element.show();',
'            if (lTableCreated === "Y") {',
'                apex.jQuery("#dropTableBtn").show();',
'            };',
'        }',
'    }',
' };',
'',
'var triggerRefresh = function(){ ',
'    apex.event.trigger( apex.jQuery("#timer-container"), "job_timer" );',
'};',
'',
'var refreshInterval = setInterval( triggerRefresh, 1000);'))
,p_inline_css=>wwv_flow_string.join(wwv_flow_t_varchar2(
'.a-Region-headerItems--buttons { white-space: nowrap; }',
'.a-Region-bodyHeader { padding: 12px; margin: 0; border-bottom: 1px solid rgba(0, 0, 0,0.1); background-color: #FFF8E1; color: #202020; }',
''))
,p_step_template=>wwv_flow_imp.id(690784265136803192.4501)
,p_page_css_classes=>'ui-dialog--stretch'
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(46619710624049700)
,p_dialog_height=>'800'
,p_dialog_width=>'960'
);
