wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(1825642177529546.4501)
,p_event_id=>wwv_flow_imp.id(3531075388543848.4501)
,p_event_result=>'TRUE'
,p_action_sequence=>30
,p_execute_on_page_init=>'N'
,p_name=>'Track status of scheduler job'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_job_is_running boolean := false;',
'begin',
'    --',
'    -- Step 1: Determine whether the scheduler job is running',
'    --',
'    for j in (',
'        select 1',
'          from sys.user_scheduler_jobs',
'         where job_name like ''ORACLE_APEX_DTLD$%''',
'           and regexp_substr( comments, ''(\:)(.*?)(\:)'',1,5,''i'',2 ) = ''APEX$DATALOAD_STATUS''||:P3100_LOAD_ID',
'           and state    = ''RUNNING'' ',
'           and rownum   = 1 )',
'    loop',
'        l_job_is_running := true;',
'    end loop;',
'',
'    --',
'    -- Step 2: Determine the current status from the status collection',
'    --',
'    for l_load in (',
'        select c001 as status,',
'               c002 as error_message,',
'               n001 as rows_processed ',
'        from wwv_flow_collections ',
'        where collection_name=''APEX$DATALOAD_STATUS''||:P3100_LOAD_ID)',
'    loop',
'        :P3110_LOAD_STATUS       := l_load.status;',
'        :P3110_LOAD_ERROR        := l_load.error_message;',
'        :P3110_PROCESSED_ROW_CNT := l_load.rows_processed;',
'    end loop;',
'',
'    if :P3110_LOAD_STATUS = ''RUNNING'' and not l_job_is_running then',
'        :P3110_LOAD_STATUS       := ''FAILED'';',
'        :P3110_LOAD_ERROR        := wwv_flow_lang.system_message(''DATA.LOAD.JOB_INTERMITTENTLY_FAILED'');',
'    end if;',
'    ',
'    :P3110_PROCESSED_ROW_CNT_DISP := to_char( :P3110_PROCESSED_ROW_CNT, ''999G999G999G999G999G999G990'' );',
'end;'))
,p_attribute_03=>'P3110_LOAD_STATUS,P3110_PROCESSED_ROW_CNT,P3110_LOAD_ERROR,P3110_PROCESSED_ROW_CNT_DISP'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(1825966086529549.4501)
,p_event_id=>wwv_flow_imp.id(3531075388543848.4501)
,p_event_result=>'TRUE'
,p_action_sequence=>40
,p_execute_on_page_init=>'N'
,p_name=>'Calculate good / bad row count'
,p_action=>'NATIVE_EXECUTE_PLSQL_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_error_table_exists boolean := false;',
'    l_context wwv_flow_exec.t_context;',
'    q varchar2(32767);',
'begin',
'    if :P3110_LOAD_STATUS in (''FAILED'', ''FINISHED'' ) then',
'        if :P3100_LOAD_TO = ''NEW'' then',
'            for l_table in (',
'                select table_name',
'                from sys.dba_tables',
'                where table_name = :P3100_TABLE_NAME',
'                and owner = :P3100_TABLE_OWNER )',
'            loop',
'                :P3110_TABLE_CREATED := ''Y'';',
'            end loop;',
'        end if;',
'        ',
'        for l_table in (',
'            select table_name',
'            from sys.dba_tables',
'            where table_name = :P3100_ERROR_TABLE',
'            and owner = :P3100_TABLE_OWNER )',
'        loop',
'            l_error_table_exists := true;',
'        end loop;',
'        ',
'        q := ''with'';',
'        q := q||'' success_data as (select count(*) as cnt from ''||',
'             wwv_flow_assert.enquote_name(',
'                 case when :P3100_LOAD_TO = ''NEW'' then',
'                     :P3100_TABLE_NAME',
'                 when :P3100_LOAD_TO = ''EXISTING'' then',
'                     :P3100_EXISTING_TABLE',
'                 end )',
'                 || '')'';',
'        if l_error_table_exists then',
'            q := q||'', failed_data as (select count(*) as cnt from ''||wwv_flow_assert.enquote_name( :P3100_ERROR_TABLE ) || '')'';',
'        end if;',
'        q := q||'' select s.cnt as success_count'';',
'        if l_error_table_exists then',
'            q := q||'', e.cnt as error_count'';',
'        end if;',
'        q:=q||'' from'';',
'        q:=q||'' success_data s'';',
'        if l_error_table_exists then',
'            q:=q||'', failed_data e'';',
'        end if;',
'     ',
'        wwv_flow_exec.open_query_context(',
'            p_context     => l_context,',
'            p_location    => wwv_flow_exec_api.c_location_local_db,',
'            p_query_type  => wwv_flow_exec_api.c_query_type_sql_query,',
'            p_sql_query   => q,',
'            p_parse_as_schema_override => :P3100_TABLE_OWNER );',
'            ',
'        if wwv_flow_exec.next_row( p_context => l_context ) then',
'            :P3110_GOOD_ROW_CNT := wwv_flow_exec.get_number( p_context => l_context, p_column_idx => 1 );',
'            if l_error_table_exists then',
'                :P3110_BAD_ROW_CNT := wwv_flow_exec.get_number( p_context => l_context, p_column_idx => 2 );',
'            else',
'                :P3110_BAD_ROW_CNT := 0;',
'            end if;',
'        end if;',
'        ',
'        if :P3100_LOAD_TO = ''EXISTING'' then',
'            :P3110_GOOD_ROW_CNT := :P3110_PROCESSED_ROW_CNT - :P3110_BAD_ROW_CNT;',
'        end if;',
'        ',
'        :P3110_GOOD_ROW_CNT_DISP := to_char( :P3110_GOOD_ROW_CNT, ''999G999G999G999G999G999G990'' );',
'        :P3110_BAD_ROW_CNT_DISP  := to_char( :P3110_BAD_ROW_CNT,  ''999G999G999G999G999G999G990'' );',
'        ',
'        wwv_flow_exec.close_context( p_context => l_context );',
'    end if;',
'exception ',
'    when others then',
'        wwv_flow_exec.close_context( p_context => l_context );',
'        raise;',
'end;'))
,p_attribute_02=>'P3110_LOAD_STATUS'
,p_attribute_03=>'P3110_GOOD_ROW_CNT,P3110_BAD_ROW_CNT,P3110_TABLE_CREATED,P3110_TAB_OBJ_ID,P3110_GOOD_ROW_CNT_DISP,P3110_BAD_ROW_CNT_DISP'
,p_attribute_04=>'N'
,p_attribute_05=>'PLSQL'
,p_wait_for_result=>'Y'
);
wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(10802374370735845.4501)
,p_event_id=>wwv_flow_imp.id(3531075388543848.4501)
