,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'drop table'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_drop1 sys.dbms_sql.varchar2a;',
'    l_drop2 sys.dbms_sql.varchar2a;',
'begin',
'    l_drop1(1) := ''drop table ''||wwv_flow_assert.enquote_name(:P3100_TABLE_NAME);',
'    l_drop2(1) := ''drop table ''||wwv_flow_assert.enquote_name(:P3100_ERROR_TABLE);',
'    ',
'    wwv_flow_dynamic_exec.run_ddl (',
'        p_sql  => l_drop1,',
'        p_user => :P3100_TABLE_OWNER );',
'   ',
'   wwv_flow_dynamic_exec.run_ddl (',
'        p_sql  => l_drop2,',
'        p_user => :P3100_TABLE_OWNER );',
'end;',
''))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(207424077958369637.4501)
,p_internal_uid=>207425026686369647.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(207424671147369643.4501)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'get object ID'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'for l_object in (',
'    select object_id, object_name',
'    from sys.dba_objects',
'    where object_name in (:P3100_TABLE_NAME, :P3100_EXISTING_TABLE, :P3100_ERROR_TABLE)',
'    and owner = :P3100_TABLE_OWNER )',
'loop',
'    if l_object.object_name = :P3100_TABLE_NAME and :P3100_LOAD_TO = ''NEW'' then',
'        :P3110_TAB_OBJ_ID := l_object.object_id;',
'    elsif l_object.object_name = :P3100_EXISTING_TABLE and :P3100_LOAD_TO = ''EXISTING'' then',
'        :P3110_TAB_OBJ_ID := l_object.object_id;',
'    elsif l_object.object_name = :P3100_ERROR_TABLE then',
'        :P3110_ERR_TAB_OBJ_ID := l_object.object_id;',
'    end if;',
'end loop;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>'P3110_TAB_OBJ_ID'
,p_process_when_type=>'ITEM_IS_NULL'
,p_internal_uid=>207424671147369643.4501
);
end;
