wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(20163613189354601.4501)
,p_name=>'Columnas que cargar'
,p_region_name=>'tab_columns'
,p_template=>wwv_flow_imp.id(385770331595976651.4501)
,p_display_sequence=>70
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_css_classes=>'a-DataLoad-previewColumns'
,p_region_template_options=>'#DEFAULT#'
,p_component_template_options=>'#DEFAULT#:a-Report--staticRowColors:a-Report--horizontalBorders:a-Report--stretch'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'with ',
'    l_columns as (',
'        select ',
'            fc.column_position,    ',
'            case when :P3120_FIRST_LINE = ''HEADERS'' then fc.column_name else ''COL'' || lpad( rownum,3,''0'') end as column_name, ',
'            regexp_replace( fc.data_type, ''\(\d+\)'','''') data_type,',
'            case when substr( fc.data_type, 1, 8 ) = ''VARCHAR2''',
'               then replace( substr( fc.data_type, 10 ), '')'' )',
'               else null',
'           end as max_length,',
'            fc.format_mask,',
'            fc.detected_group_char group_char,',
'            fc.detected_decimal_char decimal_char',
'        from wwv_flow_collections c,',
'             table( wwv_flow_data_parser.get_columns( c.clob001 ) ) fc',
'        where c.collection_name =''APEX$DATALOAD'' ),',
'    l_config_columns as (',
'        select',
'            to_number(s.c001) column_position,',
'            s.c002 column_name,',
'            s.c003 format_mask,',
'            s.c004 group_char,',
'            s.c005 decimal_char,',
'            s.c006 data_type,',
'            s.c007 max_length',
'        from wwv_flow_collections s',
'        where collection_name = ''APEX$DATALOAD_COLUMNS'' )',
'select',
'    c.column_position,',
'    htmldb_item.hidden(',
'        p_idx            => 6,',
'        p_value          => c.column_position )||',
'    htmldb_item.hidden(',
'        p_idx            => 2,',
'        p_value          => c.column_name )||',
'    htmldb_item.checkbox2(',
'        p_idx            => 1,',
'        p_value          => c.column_position, ',
'        p_attributes     => ''aria-label="Select Row: ''||wwv_flow_escape.html_attribute(c.column_name)||''"'',',
'        p_checked_values => cf.column_position ) as select_column,   ',
'    c.column_name,',
'    case when cf.data_type = ''CLOB'' then',
'        htmldb_item.display_and_save(',
'            p_idx            => 7,',
'            p_value          => cf.data_type,',
'            p_item_label     => wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.COLUMN_TYPE'', wwv_flow_escape.html_attribute(c.column_name)) )',
'    else',
'        htmldb_item.select_list_from_lov(',
'            p_idx            => 7,',
'            p_value          => cf.data_type,',
'            p_lov            => ''DATA.LOAD.DATA_TYPES'',',
'            p_show_null      => ''NO'',',
'            p_show_extra     => ''NO'',',
'            p_attributes     => case when cf.data_type = ''CLOB'' then ''disabled '' end ||',
'                                ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.COLUMN_TYPE'', wwv_flow_escape.html_attribute(c.column_name))||''"'')',
'    end as column_type,',
'    htmldb_item.text(',
'        p_idx            => 8,',
'        p_value          => cf.max_length,',
'        p_size           => 5,',
'        p_maxLength      => 5,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.MAX_LENGTH'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as max_length,',
'    htmldb_item.text(',
'        p_idx            => 3,',
'        p_value          => cf.format_mask,',
'        p_size           => 20,',
'        p_maxLength      => 1000,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.FORMAT_MASK'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as format_mask,',
'    htmldb_item.text(',
'        p_idx            => 4,',
'        p_value          => cf.group_char,',
'        p_size           => 2,',
'        p_maxLength      => 2,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.GROUP_SEPARATOR'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as group_char,',
'    htmldb_item.text(',
'        p_idx            => 5,',
'        p_value          => cf.decimal_char,',
'        p_size           => 2,',
'        p_maxLength      => 2,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.DECIMAL_CHARACTER'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as decimal_char',
'from l_columns c, l_config_columns cf',
'where wwv_flow_collection.collection_member_count( p_collection_name => ''APEX$DATALOAD_COLUMNS'' ) > 0',
'and  c.column_position = cf.column_position (+)',
'union',
'select',
'    c.column_position,',
'    htmldb_item.hidden(',
'        p_idx            => 6,',
'        p_value          => c.column_position )||',
'    htmldb_item.hidden(',
'        p_idx            => 2,',
'        p_value          => c.column_name )||',
'    htmldb_item.checkbox2(',
'        p_idx            => 1,',
'        p_value          => c.column_position, ',
'        p_attributes     => ''aria-label="Select Row: ''||wwv_flow_escape.html_attribute(c.column_name)||''"'',',
'        p_checked_values => c.column_position) as select_column,    ',
'    c.column_name,',
'    case when c.data_type = ''CLOB'' then',
'        htmldb_item.display_and_save(',
'            p_idx            => 7,',
'            p_value          => c.data_type,',
'            p_item_label     => wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.COLUMN_TYPE'', wwv_flow_escape.html_attribute(c.column_name)) )',
'    else',
'        htmldb_item.select_list_from_lov(',
'            p_idx            => 7,',
'            p_value          => c.data_type,',
'            p_lov            => ''DATA.LOAD.DATA_TYPES'',',
'            p_show_null      => ''NO'',',
'            p_show_extra     => ''NO'',',
'            p_attributes     => ( case when c.data_type = ''CLOB'' then ''disabled '' end )||',
'                                ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.COLUMN_TYPE'', wwv_flow_escape.html_attribute(c.column_name))||''"'')',
'    end as column_type,',
'    htmldb_item.text(',
'        p_idx            => 8,',
'        p_value          => c.max_length,',
'        p_size           => 5,',
'        p_maxLength      => 5,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.MAX_LENGTH'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as max_length,',
'    htmldb_item.text(',
'        p_idx            => 3,',
'        p_value          => c.format_mask,',
'        p_size           => 20,',
'        p_maxLength      => 1000,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.FORMAT_MASK'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as format_mask,',
'    htmldb_item.text(',
'        p_idx            => 4,',
'        p_value          => c.group_char,',
'        p_size           => 2,',
'        p_maxLength      => 2,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.GROUP_SEPARATOR'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as group_char,',
'    htmldb_item.text(',
'        p_idx            => 5,',
'        p_value          => c.decimal_char,',
'        p_size           => 2,',
'        p_maxLength      => 2,',
'        p_attributes     => ''aria-label="''||wwv_flow_lang.system_message(''DATA_WORKSHOP.CONFIGURE.DECIMAL_CHARACTER'', wwv_flow_escape.html_attribute(c.column_name))||''"'') as decimal_char',
'from l_columns c',
'where wwv_flow_collection.collection_member_count( p_collection_name => ''APEX$DATALOAD_COLUMNS'' ) = 0',
'order by 1'))
,p_display_when_condition=>'coalesce( :P3100_LOAD_TO, ''NEW'') = ''NEW'''
,p_display_when_cond2=>'PLSQL'
,p_display_condition_type=>'EXPRESSION'
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>wwv_flow_imp.id(717436155076828097.4501)
,p_query_num_rows=>500
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_query_no_data_found=>'No se ha encontrado ninguna columna.'
,p_query_num_rows_type=>'NEXT_PREVIOUS_LINKS'
,p_pagination_display_position=>'BOTTOM_RIGHT'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_plug_query_strip_html=>'N'
);
