wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(81742731063478601.4501)
,p_validation_name=>'check group and decimal char'
,p_validation_sequence=>20
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_load_to      varchar2(10);',
'    ',
'    l_group_char   varchar2(4);',
'    l_decimal_char varchar2(4);',
'    l_column_name  varchar2(128);',
'    l_error_msg    varchar2(4000);',
'',
'    function validate_group_decimal_char',
'    return varchar2',
'    is',
'        l_msg varchar2(4000);',
'    begin',
'        -- if group separator defined, decimal character must be defined',
'        if l_group_char is not null then',
'            if l_decimal_char is null then',
'                l_msg := wwv_flow_lang.system_message( ',
'                            ''DATA_LOAD.DECIMAL_CHAR_REQUIRED'',',
'                            l_column_name );',
'            end if;',
'        end if;',
'',
'        -- group and decimal chars cannot be same',
'        if l_group_char = l_decimal_char then',
'            l_msg := wwv_flow_lang.system_message(',
'                         ''DATA_LOAD.SAME_GROUP_DECIMAL_CHARS'',',
'                         l_column_name );',
'        end if;',
'        ',
'        return l_msg;',
'    end validate_group_decimal_char;',
'begin',
'    l_load_to := coalesce( :P3100_LOAD_TO, ''NEW'');',
'',
'    if l_load_to = ''NEW'' then',
'        -- loop through all column postions',
'        for i in 1 .. wwv_flow.g_f06.count',
'        loop',
'            for j in 1 .. wwv_flow.g_f01.count',
'            loop',
'                -- if column checked to load, validate',
'                if wwv_flow.g_f01( j ) = wwv_flow.g_f06( i ) then',
'                    l_column_name  := wwv_flow.g_f02( i );',
'                    l_group_char   := wwv_flow.g_f04( i );',
'                    l_decimal_char := wwv_flow.g_f05( i );',
'',
'                    l_error_msg := validate_group_decimal_char;',
'                    if l_error_msg is not null then',
'                        return l_error_msg;',
'                    end if;',
'',
'                    exit;',
'                end if;',
'            end loop;',
'        end loop;',
'    elsif l_load_to= ''EXISTING'' then',
'        for i in 1 .. wwv_flow.g_f02.count',
'        loop',
'            -- if column mapped, check group and decimal char',
'            if wwv_flow.g_f02(i) is not null then',
'                l_column_name  := wwv_flow.g_f02( i );',
'                l_group_char   := wwv_flow.g_f04( i );',
'                l_decimal_char := wwv_flow.g_f05( i );',
'',
'                l_error_msg := validate_group_decimal_char;',
'                if l_error_msg is not null then',
'                    return l_error_msg;',
'                end if;',
'            end if;',
'        end loop;',
'    end if;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_when_button_pressed=>wwv_flow_imp.id(3942483089766704.4501)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(285737382733666601.4501)
,p_validation_name=>'table columns not mapped multiple times'
,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_column_names  wwv_flow_global.vc_map;',
'    l_col_name_idx  pls_integer;',
'begin',
'    l_col_name_idx := wwv_flow.g_f02.first;',
'    while l_col_name_idx is not null loop',
'        if wwv_flow.g_f02( l_col_name_idx ) is not null then',
'            if l_column_names.exists( wwv_flow.g_f02( l_col_name_idx ) ) then',
'                return wwv_flow_lang.system_message ( ''DATA_LOAD.DUPLICATE_MAPPING'', wwv_flow.g_f02( l_col_name_idx ) );',
'            else',
'                l_column_names( wwv_flow.g_f02( l_col_name_idx ) ) := null;',
'            end if;',
'        end if;',
'',
'        l_col_name_idx := wwv_flow.g_f02.next( l_col_name_idx );',
'    end loop;',
'    return null;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_validation_condition=>'coalesce( :P3100_LOAD_TO, ''NEW'') = ''EXISTING'''
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_when_button_pressed=>wwv_flow_imp.id(3942483089766704.4501)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(94756065775727904.4501)
,p_validation_name=>'check max length'
,p_validation_sequence=>40
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_data_type    wwv_flow_global.t_dbms_id;',
'    l_max_length   number;',
'begin',
'    ',
'    -- loop through all column postions',
'    for i in 1 .. wwv_flow.g_f06.count',
'    loop',
'',
'        for j in 1 .. wwv_flow.g_f01.count',
'        loop',
'            -- if column checked to load, validate',
'            if wwv_flow.g_f01( j ) = wwv_flow.g_f06( i ) then',
'',
'                l_data_type  := wwv_flow.g_f07( i );',
'',
'                begin',
'                    l_max_length := to_number( wwv_flow.g_f08( i ) );',
'                exception when others then',
'                    if l_data_type = ''VARCHAR2'' then',
'                        -- if not number, validation fails',
'                        return false;',
'                    end if;',
'                end;',
'',
'                if l_data_type = ''VARCHAR2'' then',
'                    -- if null, validation fails',
'                    if l_max_length is null then',
'                        return false;',
'                    else',
'                        -- varchar2 data type max length must be between 1 and allowed max varchar2 size',
'                        if l_max_length < 1 or ',
'                           l_max_length > case when wwv_flow_db_version.c_has_extended_string_size then 32767 else 4000 end',
'                        then',
'                            return false;',
'                        end if;',
'                    end if;',
'                end if;',
'',
'                exit;',
'            end if;',
'        end loop;',
'    end loop;',
'',
'    return true;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('La longitud m\00E1xima es obligatoria para las columnas VARCHAR2 y debe ser un n\00FAmero entre 1 y el tama\00F1o m\00E1ximo permitido de VARCHAR2.')
,p_validation_condition=>'coalesce( :P3100_LOAD_TO, ''NEW'') = ''NEW'''
,p_validation_condition2=>'PLSQL'
,p_validation_condition_type=>'EXPRESSION'
,p_when_button_pressed=>wwv_flow_imp.id(3942483089766704.4501)
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
