'apex.theme.stretchDialog( apex.util.getTopApex().jQuery( ''#'' + window.frameElement.parentNode.id ), 90 );',
'// RDS icons',
'var icon$ = $(''<span class="a-Icon icon-tree-attributes" aria-hidden="true"></span>'');',
'var rdsTab$ = $(''.apex-rds-item:last-child a:first-child span'');',
'var rdsId = $( ''#preview_selector > .apex-rds-container'' ).find( ''ul'' ).attr( ''id'' ).slice(0, -4);',
'icon$.prependTo(rdsTab$);',
'// shared functions',
'var getColId = function( id ){',
'    var int = parseInt( id ), i;',
'    if ( int <= 9 ) {',
'            i = ''COL00'' + int;',
'        } else if ( int > 9 && int <= 99 ) {',
'            i = ''COL0'' + int;',
'        } else {',
'            i = ''COL'' + int;',
'        }',
'    return i;',
'};',
'',
'var toggleCol = function ( columnId, isShowing ) {',
'    if ( columnId ) {',
'        var header$  = $( ''#'' + columnId ),',
'            body$    = $( ''td[headers='' + columnId + '']'' );',
'',
'        if ( isShowing ) {',
'            header$.show();',
'            body$.show();',
'        } else {',
'            header$.hide();',
'            body$.hide();',
'        }',
'    }',
'};',
'',
'var getRds = function(){',
'    return apex.widget.regionDisplaySelector( rdsId );',
'};',
'',
'// hide empty columns',
'( function () {',
'    var hideGreaterThan = parseInt( $v(''P3120_PARSED_COLUMN_COUNT'') ) + 1,',
'        emptyColId;',
'',
'        for ( i = hideGreaterThan; i <= 100; i++ ) {',
'            emptyColId = getColId( i );',
'            toggleCol( emptyColId, false );',
'        }',
'',
'})();',
'',
'// replace column count placeholders in header text of parsed data preview region',
'$( "#placeholder_P3120_PARSED_COLUMN_COUNT" ).text( $v( "P3120_PARSED_COLUMN_COUNT" ) );',
'$( "#placeholder_P3120_PARSED_ROW_COUNT" ).text( $v( "P3120_PARSED_ROW_COUNT" ) );',
'',
'// Setting items hide/show based on RDS',
'var s_col$ = $(''.tab-columns''),',
'    s_prev$ = $(''.tab-preview'');',
'',
'$( ''body'' ).on( ''atabsactivate'', function(){',
'    var id = getRds().getActiveTab().href;',
'    ',
'    if ( id.indexOf( ''columns'' ) > 0 ) {',
'        s_col$.show();',
'        s_prev$.hide();',
'    } else {',
'        s_col$.hide();',
'        s_prev$.show();',
'    }',
'});',
'',
'// checkboxes',
'( function () {',
'',
'    var checkboxes$ = $( ''input[name=f01]'' ),',
'        checkAll$   = $( ''#toggle-select-all-columns'' );',
'',
'    var checkAllState = function(){',
'        checkAll$.prop( ''checked'', checkboxes$.length === $( ''input[name=f01]:checked'' ).length );',
'    };',
'',
'    checkAll$.on( ''click'', function () {',
'        var isAllChecked = checkAll$.is( '':checked'' );',
'        checkboxes$.prop( ''checked'', isAllChecked )',
'    });',
'',
'    // init check state on load',
'    checkAllState();',
'})();',
'',
'$( apex.gPageContext$ ).on( ''apexreadyend'', function() {',
'    setTimeout(function(){',
'       var rds$ = getRds(),',
'        selection = ''#'' + apex.item(''P3120_ACTION'').getValue();',
'        tab$ = rds$.tabs[ selection ];',
'        if ( tab$ ) {',
'            tab$.makeActive();',
'        } ',
'    }, 250);',
'});'))
);
