wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3942624774766706.4501)
,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'New Table - Save Column Load Checkbox'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_profile           clob;',
'    l_col_selected      boolean := false;',
'    l_mapped_col_cnt    pls_integer := 0;',
'begin',
'    wwv_flow_collection.create_or_truncate_collection( p_collection_name => ''APEX$DATALOAD_COLUMNS'' );',
'    -- loop through all column postions',
'    for i in 1 .. wwv_flow.g_f06.count',
'    loop',
'        ',
'        for j in 1 .. wwv_flow.g_f01.count',
'        loop',
'            -- if column checked to load, save the column configuration',
'            if wwv_flow.g_f01( j ) = wwv_flow.g_f06( i ) then',
'',
'                wwv_flow_collection.add_member(',
'                    p_collection_name => ''APEX$DATALOAD_COLUMNS'',',
'                    p_c001            => wwv_flow.g_f06( i ), -- column position',
'                    p_c002            => wwv_flow.g_f02( i ), -- column name',
'                    p_c003            => wwv_flow.g_f03( i ), -- format mask',
'                    p_c004            => wwv_flow.g_f04( i ), -- group char',
'                    p_c005            => wwv_flow.g_f05( i ), -- decimal char',
'                    p_c006            => wwv_flow.g_f07( i ), -- column type',
'                    p_c007            => case when wwv_flow.g_f07( i ) = ''VARCHAR2'' then wwv_flow.g_f08( i ) end  -- max length',
'                    );',
'',
'                exit;',
'            end if;',
'        end loop;',
'    end loop;',
'        ',
'    select clob001',
'    into l_profile ',
'    from wwv_flow_collections ',
'    where collection_name = ''APEX$DATALOAD'' ',
'    and rownum = 1;',
'    ',
'    for i in (',
'        select column_position, column_name',
'        from table( wwv_flow_data_parser.get_columns( l_profile ) ) c ) ',
'    loop',
'        if wwv_flow_collection.collection_member_count( p_collection_name => ''APEX$DATALOAD_COLUMNS'' ) = 0 then',
'            l_col_selected := true;',
'        else',
'            l_col_selected := false;',
'            for l_select_col in (',
'                select c001 idx ',
'                from wwv_flow_collections',
'                where collection_name = ''APEX$DATALOAD_COLUMNS'' )',
'            loop',
'                begin',
'                    if to_number( l_select_col.idx ) = i.column_position then',
'                        l_col_selected := true;',
'                        exit;',
'                    end if;',
'                exception when invalid_number then null; ',
'                end;',
'            end loop;',
'        end if;',
'        ',
'        if l_col_selected then',
'            l_mapped_col_cnt := l_mapped_col_cnt + 1;',
'        end if;',
'    end loop;',
'    ',
'    :P3100_MAPPED_COLUMN_COUNT := l_mapped_col_cnt;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3942483089766704.4501)
,p_process_when=>'coalesce( :P3100_LOAD_TO, ''NEW'') = ''NEW'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>3942624774766706.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(82703578316738108.4501)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Existing Table - Save Column Mapping'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_column_map    wwv_flow_global.vc_map := wwv_flow_global.c_empty_vc_map;',
'begin    ',
'    wwv_flow_collection.create_or_truncate_collection( p_collection_name => ''APEX$DATALOAD_COLUMNS'' );',
'    wwv_flow_collection.add_members(',
'        p_collection_name => ''APEX$DATALOAD_COLUMNS'',',
'        p_c001            => wwv_flow.g_f01,  -- column_name',
'        p_c002            => wwv_flow.g_f02,  -- mapped column',
'        p_c003            => wwv_flow.g_f03,  -- format mask',
'        p_c004            => wwv_flow.g_f04,  -- group char',
'        p_c005            => wwv_flow.g_f05   -- decimal char           ',
'        );',
'    ',
'    -- get column mapping user configured',
'    for l_configure in (',
'        select',
'            c001   column_name,',
'            c002   mapped_column',
'        from wwv_flow_collections',
'        where collection_name = ''APEX$DATALOAD_COLUMNS''',
'        and c002 is not null )',
'    loop',
'        l_column_map( l_configure.column_name ) := l_configure.mapped_column;',
'    end loop;',
'',
'    --',
'    -- if no column has been mapped, clear the collection, so that APEX can automatically',
'    -- map columns again when "save" changes is clicked. This prevents columns from being',
'    -- doubled in the collection (bug #32405712)',
'    --',
'    if l_column_map.count = 0 then',
'        wwv_flow_collection.truncate_collection( p_collection_name => ''APEX$DATALOAD_COLUMNS'' );',
'    end if;         ',
'    ',
'    :P3100_MAPPED_COLUMN_COUNT := l_column_map.count;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3942483089766704.4501)
,p_process_when=>'coalesce( :P3100_LOAD_TO, ''NEW'') = ''EXISTING'''
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_internal_uid=>82703578316738108.4501
);
