,p_process_sequence=>30
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load Using APEX'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_name varchar2(32767);',
'begin',
'    l_name := wwv_dbms_cloud.download_file_to_apex(',
'                  p_schema            => :P3130_SCHEMA,',
'                  p_remote_server_id  => :P3130_REMOTE_SERVER_ID,',
'                  p_filename          => :P3130_FILE_NAME );',
'                  ',
'    :P3130_DOWNLOADED_FILE := l_name;',
'    ',
'    wwv_flow_collection.create_or_truncate_collection( ''APEX$DATALOAD_COLUMNS'' );',
'    wwv_flow_session_state.clear_state_for_page( p_page_id => 3100 );',
'    wwv_flow_session_state.clear_state_for_page( p_page_id => 3110 );',
'    wwv_flow_session_state.clear_state_for_page( p_page_id => 3120 );',
'    ',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2877017327080421.4501)
,p_process_success_message=>'Se ha descargado el archivo.'
