wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2104599819493940.4501)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Save Object Store Reference'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_remote_server_id number;',
'begin',
'    if :P3131_REMOTE_SERVER_ID is not null and :P3131_KEEP_CREDENTIALS = ''N'' then',
'        wwv_dbms_cloud.drop_objectstore_reference(',
'            p_schema           => :P3130_SCHEMA,',
'            p_remote_server_id => :P3131_REMOTE_SERVER_ID );',
'    end if;',
'',
'    if :P3131_REMOTE_SERVER_ID is not null and :P3131_KEEP_CREDENTIALS = ''Y'' then',
'        update wwv_remote_servers ',
'           set name     = :P3131_SERVER_NAME,',
'               base_url = :P3131_SERVER_URL',
'         where security_group_id = :WORKSPACE_ID',
'           and id                = :P3131_REMOTE_SERVER_ID;',
'    end if;',
'    ',
'    if :P3131_REMOTE_SERVER_ID is null or :P3131_KEEP_CREDENTIALS = ''N'' then',
'',
'        if :P3131_CREDENTIAL_TYPE = ''USERPASS'' then',
'            l_remote_server_id := wwv_dbms_cloud.create_objectstore_reference(',
'                p_schema                => :P3130_SCHEMA,',
'                p_server_name           => :P3131_SERVER_NAME,',
'                p_server_url            => :P3131_SERVER_URL,',
'                --',
'                p_create_web_credential => ( :P3131_CREATE_WEB_CREDENTIAL = ''Y'' ),',
'                --',
'                p_username              => :P3131_USERNAME,',
'                p_password              => :P3131_PASSWORD ); ',
'        elsif :P3131_CREDENTIAL_TYPE = ''OCI'' then',
'            l_remote_server_id := wwv_dbms_cloud.create_objectstore_reference(',
'                p_schema                => :P3130_SCHEMA,',
'                p_server_name           => :P3131_SERVER_NAME,',
'                p_server_url            => :P3131_SERVER_URL,',
'                --',
'                p_create_web_credential => ( :P3131_CREATE_WEB_CREDENTIAL = ''Y'' ),',
'                --',
'                p_user_ocid             => :P3131_USER_OCID,',
'                p_tenancy_ocid          => :P3131_TENANCY_OCID,',
'                p_private_key           => :P3131_PRIVATE_KEY,',
'                p_fingerprint           => :P3131_FINGERPRINT );         ',
'        elsif :P3131_CREDENTIAL_TYPE = ''USER_CREDENTIALS'' then',
'            l_remote_server_id := wwv_dbms_cloud.create_objectstore_reference(',
'                p_schema                => :P3130_SCHEMA,',
'                p_server_name           => :P3131_SERVER_NAME,',
'                p_server_url            => :P3131_SERVER_URL,',
'                --',
'                p_credential_name       => :P3131_USER_CREDENTIAL_NAME );                ',
'        else',
'            l_remote_server_id := wwv_dbms_cloud.create_objectstore_reference(',
