begin
wwv_flow_imp_page.create_page(
 p_id=>3142.4501
,p_name=>'Asignar columnas'
,p_alias=>'MAP-COLUMNS'
,p_page_mode=>'MODAL'
,p_step_title=>'Asignar columnas'
,p_autocomplete_on_off=>'ON'
,p_javascript_code=>wwv_flow_string.join(wwv_flow_t_varchar2(
'( function () {',
'',
'    var checkboxes$ = $( ''input[name=f01]'' ),',
'        checkAll$   = $( ''#toggle-select-all-columns'' );',
'',
'    var checkAllState = function(){',
'        checkAll$.prop( ''checked'', checkboxes$.length === $( ''input[name=f01]:checked'' ).length );',
'    };',
'',
'    checkboxes$.on( ''click'', function () {',
'        var that$ = $( this ),',
'            colId = getColId( that$.val() ),',
'            isChecked = that$.prop( ''checked'' );',
'',
'        toggleCol( colId, isChecked );',
'',
'        checkAllState();',
'    });',
'',
'    checkAll$.on( ''click'', function () {',
'        var isAllChecked = checkAll$.is( '':checked'' );',
'',
'        checkboxes$',
'            .prop( ''checked'', isAllChecked )',
'            .each(function(){',
'                var cb$ = $( this );',
'                toggleCol( getColId( cb$.val() ), cb$.prop( ''checked'' ) );  ',
'            });',
'    });',
'',
'    // init check state on load',
'    checkAllState();',
'})();'))
,p_step_template=>wwv_flow_imp.id(690782249755803171.4501)
,p_page_css_classes=>'a-Page--DataLoadPreview'
,p_page_template_options=>'#DEFAULT#'
,p_required_role=>wwv_flow_imp.id(46619710624049700)
