wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(3203712454656831.4501)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load data to collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_file_content blob;',
'    l_file_type    pls_integer;',
'    ',
'    l_row_selector varchar2(255);',
'begin',
'    select blob_content',
'      into l_file_content',
'      from wwv_flow_temp_files',
'     where name = :P3150_FILE;',
'     ',
'    if :P3150_FILE_NAME like ''%.zip'' then',
'        l_file_type := wwv_flow_soda_dev.c_file_type_zip;',
'    elsif  :P3150_FILE_NAME like ''%.js'' or :P3150_FILE_NAME like ''%json'' or :P3150_FILE_NAME like ''%txt'' then',
'        l_file_type := wwv_flow_soda_dev.c_file_type_json_collection;',
'    end if;',
'    ',
'    if l_file_type = wwv_flow_soda_dev.c_file_type_json_collection then',
'        l_row_selector := case when :P3150_AUTO_DETECT_SELECTOR = ''N''  then :P3150_ROW_SELECTOR',
'                               when :P3150_AUTO_DETECT_SELECTOR = ''CR'' then chr( wwv_flow_soda_dev.c_row_selector_chr_jsonlist )',
'                               when :P3150_AUTO_DETECT_SELECTOR = ''Y''  then null',
'                          end;',
'    end if;',
'    ',
'    :P3150_LOAD_ID := wwv_flow_id.next_val;',
'    ',
'    if l_file_type = wwv_flow_soda_dev.c_file_type_zip and :P3150_LOAD_NON_JSON = ''Y'' then',
'        :P3150_RELATIONAL_VIEW := null;',
'    end if;',
'',
'    if :P3150_LOAD_TO = ''NEW'' then',
'        wwv_flow_soda_dev.load_into_new_collection(',
'            p_content              => l_file_content,',
'            p_content_type         => l_file_type,',
'            --',
'            p_collection_name      => :P3150_NEW_COLL_NAME,',
'            p_relational_view_name => :P3150_RELATIONAL_VIEW,',
'            p_handle_nonjson_files => case when :P3150_AUTO_DETECT_SELECTOR = ''CR'' ',
'                                          then',
'                                              case when :P3150_SKIP_NON_JSON = ''N'' then wwv_flow_soda_dev.c_allow_nonjson_files else wwv_flow_soda_dev.c_skip_nonjson_files end',
'                                          else ',
'                                              case when :P3150_LOAD_NON_JSON = ''Y'' then wwv_flow_soda_dev.c_allow_nonjson_files else wwv_flow_soda_dev.c_skip_nonjson_files end',
'                                      end,',
'            p_convert_xml_to_json  => :P3150_CONVERT_XML_FILES = ''Y'',',
'            -- ',
'            p_row_selector         => l_row_selector,',
'            -- ',
'            p_commit_interval      => 200,',
'            p_status_collection    => ''APEX$DATALOAD_STATUS''||:P3150_LOAD_ID,',
'            -- ',
'            p_run_in_background    => true,',
'            -- ',
'            p_execute_as_schema    => :P3150_PARSING_SCHEMA );',
'    else',
'        wwv_flow_soda_dev.load_into_existing_collection(',
'            p_content              => l_file_content,',
'            p_content_type         => l_file_type,',
'            --',
'            p_handle_nonjson_files => case when :P3150_AUTO_DETECT_SELECTOR = ''CR'' ',
'                                          then',
'                                              case when :P3150_SKIP_NON_JSON = ''N'' then wwv_flow_soda_dev.c_allow_nonjson_files else wwv_flow_soda_dev.c_skip_nonjson_files end',
'                                          else ',
'                                              case when :P3150_LOAD_NON_JSON = ''Y'' then wwv_flow_soda_dev.c_allow_nonjson_files else wwv_flow_soda_dev.c_skip_nonjson_files end',
'                                      end,',
'            p_convert_xml_to_json  => :P3150_CONVERT_XML_FILES = ''Y'',',
'            p_collection_name      => :P3150_EXISTING_COLL_NAME,',
'            p_relational_view_name => null,',
'            -- ',
'            p_row_selector         => l_row_selector,',
'            p_truncate             => ( :P3150_APPEND_METHOD = ''REPLACE'' ),',
'            -- ',
'            p_commit_interval      => 200,',
'            p_status_collection    => ''APEX$DATALOAD_STATUS''||:P3150_LOAD_ID,',
'            -- ',
'            p_run_in_background    => true,',
'            -- ',
'            p_execute_as_schema    => :P3150_PARSING_SCHEMA );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(3201857722656812.4501)
,p_internal_uid=>3203712454656831.4501
);
