'        :P3151_OBJECT_ID := l_object.object_id;',
'        :P3151_NAME      := l_object.object_name;',
'    elsif l_object.object_name = :P3150_EXISTING_COLL_NAME and :P3150_LOAD_TO = ''EXISTING'' then',
'        :P3151_OBJECT_ID := l_object.object_id;',
