'    l_count     number;',
'begin',
'    for q in',
'    (',
'        select name ',
'          from wwv_dg_blueprint_tables ',
'         where blueprint_id = :P4005_BLUEPRINT_ID',
'    )',
'    loop',
'        select count(*) into l_count ',
'          from sys.dba_objects',
'         where object_type in (''TABLE'')',
'           and object_name = upper(q.name)',
'           and owner = :DATAGEN_SCHEMA;',
'        if l_count > 0 then',
'            return true;',
'        else',
'            return false;',
'        end if;',
'    end loop;',
'end;'))
