wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(9840770374941624.4501)
,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Add to Collection'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_errors      clob;',
'    l_error_txt   varchar2(32767);',
'    l_error_table varchar2(32767);',
'    l_error_msg   varchar2(32767);',
'    l_parse_json  wwv_flow_json.t_values;',
'begin',
'',
'    wwv_dg_blueprint_util_int.g_current_schema := :DATAGEN_SCHEMA;',
'    ',
'    wwv_dg_blueprint_util_int.generate_data_into_collection (',
'        p_blueprint       => :P4005_BLUEPRINT_NAME,',
'        p_format          => :P4005_FILE_FORMAT,',
'        p_row_scaling     => :P4005_ROW_SCALING,',
'        p_errors          => l_errors );',
'',
'    if sys.dbms_lob.getlength( l_errors ) > 0 then ',
'        wwv_flow_json.parse( ',
'            p_values => l_parse_json, ',
'            p_source => l_errors );',
'',
'        l_error_txt := wwv_flow_json.get_varchar2(',
'            p_values => l_parse_json,',
'            p_path => ''odgOutputErrors[1].errors[1].errorText'' );',
'',
'        l_error_table := wwv_flow_json.get_varchar2(',
'            p_values => l_parse_json,',
'            p_path => ''odgOutputErrors[1].errors[1].table'' );',
'',
'        if l_error_table is not null then',
'            l_error_msg := wwv_flow_lang.runtime_message( ',
'                p_name => ''ODG.BLUEPRINT.TABLE_ERROR'', ',
'                p0     => l_error_table, ',
'                p1     => l_error_txt );',
'        else',
'            l_error_msg := l_error_txt;',
'        end if;',
'        raise_application_error( -20001, l_error_msg );',
'    end if;',
'',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2821762946655512.4501)
,p_internal_uid=>9840770374941624.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2822013141655515.4501)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DL_DOC'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_mimetype    varchar2(200);',
'    l_name        varchar2(200) := wwv_flow_escape.html( p_string => :P4005_BLUEPRINT_NAME );',
'    l_filename    varchar2(200);',
'    l_error_check varchar2(100);',
'    l_data_output blob;',
'    l_error_json  clob;',
'begin',
'',
'    for c1 in (select ',
'                      -- Generated data:',
'                      blob001 generated_data,',
'                      c006    file_extension,',
'                      c007    mime_type,',
'                      -- Error handling:',
'                      c001    error_check,',
'                      clob001 error_json',
'                 from wwv_flow_collections',
'                where collection_name = ''APEX$DG$'' || :P4005_BLUEPRINT_NAME',
'                  and seq_id = 1 )',
'    loop',
'        l_mimetype    := c1.mime_type;',
'        l_filename    := lower( replace(l_name, '' '', ''_'') ) || ''.'' || c1.file_extension;',
'        l_data_output := c1.generated_data;',
'        l_error_json  := c1.error_json;',
'        l_error_check := c1.error_check;',
'    end loop;',
'',
'    if nvl( l_error_check, '''' ) = ''ERROR'' then',
'        wwv_flow_json.parse( p_source => l_error_json );',
'        raise_application_error( -20001, wwv_flow_json.get_varchar2(',
'            p_path => ''odgOutputErrors[1].errors[1].errorText''',
'        ) );',
'    else',
'        sys.htp.init;',
'        sys.owa_util.mime_header( l_mimetype, FALSE );',
'        sys.htp.p(''Content-length: '' || sys.dbms_lob.getlength( l_data_output ));',
'        sys.htp.p(''Content-Disposition: attachment; filename="'' || lower( l_filename ) || ''"'' );',
'        sys.owa_util.http_header_close;',
'        sys.wpg_docload.download_file( l_data_output );',
'',
'        wwv_flow.stop_apex_engine;',
'',
'    end if;',
'',
'exception when wwv_flow.e_stop_apex_engine then',
'    NULL;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Se ha producido un error al generar los datos.',
'',
'#SQLERRM#'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_success_message=>'Los datos se han generado correctamente.'
,p_internal_uid=>2822013141655515.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2101605684042616.4501)
,p_process_sequence=>30
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'INSERT_INTO_TABLES'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_output      blob;',
'    l_file_ext    varchar2(100);',
'    l_mime_type   varchar2(200);',
'    l_errors      clob;',
'    l_parse_json  wwv_flow_json.t_values;',
'    l_error_msg   varchar2(32767);',
'    l_error_txt   varchar2(32767);',
'    l_error_table varchar2(32767);',
'begin',
'',
'    wwv_dg_blueprint_util_int.g_current_schema := :DATAGEN_SCHEMA;',
'',
'    wwv_dg_blueprint_util_int.generate_data (',
'            p_blueprint   => replace( WWV_FLOW.g_x01, ''+'', '' ''),',
'            p_format      => replace( WWV_FLOW.g_x02, ''+'', '' ''),',
'            p_row_scaling => WWV_FLOW.g_x03,',
'            p_output      => l_output,',
'            p_file_ext    => l_file_ext,',
'            p_mime_type   => l_mime_type,',
'            p_errors      => l_errors);',
'',
'    if sys.dbms_lob.getlength( l_errors ) > 0 then',
'',
'        wwv_flow_json.parse( ',
'            p_values => l_parse_json, ',
'            p_source => l_errors );',
'',
'        l_error_txt := wwv_flow_json.get_varchar2(',
'            p_values => l_parse_json,',
'            p_path => ''odgOutputErrors[1].errors[1].errorText'' );',
'',
'        l_error_table := wwv_flow_json.get_varchar2(',
'            p_values => l_parse_json,',
'            p_path => ''odgOutputErrors[1].errors[1].table'' );',
'',
'        if l_error_table is not null then',
'            l_error_msg := wwv_flow_lang.runtime_message( ',
'                p_name => ''ODG.BLUEPRINT.TABLE_ERROR'', ',
'                p0     => l_error_table, ',
'                p1     => l_error_txt );',
'        else',
'            l_error_msg := l_error_txt;',
'        end if;',
'',
'        wwv_flow_json.open_object;',
'        wwv_flow_json.write( ''success'', false );',
'        wwv_flow_json.write( ''message'', l_error_msg );',
'        wwv_flow_json.close_object;',
'    else',
'        wwv_flow_json.open_object;',
'        wwv_flow_json.write( ''success'', true );',
'        wwv_flow_json.write( ''message'', wwv_flow_lang.system_message( ''ODG.BLUEPRINT.SUCCESS_INSERTING_DATA'' ) );',
'        wwv_flow_json.close_object;',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>'x'
,p_process_success_message=>'x'
,p_internal_uid=>2101605684042616.4501
);
end;
