'    default_col_3_id   number;',
'    default_col_4_id   number;',
'    default_col_5_id   number;',
'    default_col_6_id   number;',
'    default_col_7_id   number;',
'    default_col_8_id   number;',
'begin',
'    begin',
'        wwv_dg_data_gen_api.remove_blueprint(',
'            p_name => :P4007_NAME',
'            );',
'    exception when no_data_found then null;',
'    end;',
' ',
'    wwv_dg_data_gen_api.add_blueprint(',
'        p_name           => :P4007_NAME,',
'        p_display_name   => :P4007_NAME,',
'        p_description    => :P4007_DESCRIPTION,',
'        p_default_schema => nvl( :P4007_SCHEMA, :DATAGEN_SCHEMA ),',
'        p_lang           => nvl(:P4007_LANGUAGE, ''en'' ),',
'        p_blueprint_id   => :P4007_BLUEPRINT_ID',
'    );',
'',
'    if :P4007_SETUP_STARTER = ''Y'' then',
'',
'        -- Create a default data source (Query-based as we might not have any tables in the current schema).',
'        wwv_dg_data_gen_api.add_data_source(',
'            p_blueprint        => :P4007_NAME,',
'            p_name             => default_ds_name,',
'            p_data_source_type => ''SQL_QUERY'',',
'            p_sql_query        => q''[select ''S'' shirt_size,''18'' width,''28'' length from sys.dual union all select ''M'' shirt_size,''20'' width,''29'' length from sys.dual union all select ''L'' shirt_size,''22'' width,''30'' length from sys.dual]'',',
'            p_data_source_id   => default_ds_id',
'        );',
'',
'        -- Create a default table from scratch with sample columns.',
'        wwv_dg_data_gen_api.add_table(',
'            p_blueprint    => :P4007_NAME,',
'            p_sequence     => 10,',
'            p_table_name   => default_tbl_name,',
'            p_display_name => initcap( lower( default_tbl_name ) ),',
'            p_rows         => 50,',
'            p_table_id     => default_tbl_id',
'        );',
'',
'        -- Create a default sample columns.',
'        wwv_dg_data_gen_api.add_column(',
'            p_blueprint           => :P4007_NAME,',
'            p_sequence            => 10,',
'            p_table_name          => default_tbl_name,',
'            p_column_name         => default_col_1_name,',
'            p_display_name        => initcap( lower( default_col_1_name ) ),',
'            p_data_source_type    => ''SEQUENCE'',',
'            p_sequence_start_with => 0,',
'            p_sequence_increment  => 1,',
'            p_column_id           => default_col_1_id',
'        );',
'        ',
'        wwv_dg_data_gen_api.add_column(',
'            p_blueprint           => :P4007_NAME,',
'            p_sequence            => 20,',
