'            p_data_source_type    => ''BUILTIN'',',
'            p_data_source         => ''person.last_name'',',
'            p_column_id           => default_col_3_id',
'        );',
'',
'        wwv_dg_data_gen_api.add_column(',
'            p_blueprint           => :P4007_NAME,',
'            p_sequence            => 40,',
'            p_table_name          => default_tbl_name,',
'            p_column_name         => default_col_4_name,',
'            p_display_name        => initcap( lower( default_col_4_name ) ),',
'            p_data_source_type    => ''FORMULA'',',
'            p_formula             => q''[lower( {FIRST_NAME} || ''.'' || {LAST_NAME} ) || ''@company.com'']'',',
'            p_column_id           => default_col_4_id',
'        );',
'',
'        wwv_dg_data_gen_api.add_column(',
'            p_blueprint           => :P4007_NAME,',
'            p_sequence            => 50,',
'            p_table_name          => default_tbl_name,',
'            p_column_name         => default_col_5_name,',
'            p_display_name        => initcap( lower( default_col_5_name ) ),',
'            p_data_source_type    => ''BUILTIN'',',
