'declare',
'    l_clob clob;',
'begin',
'    for c1 in (',
'        select name',
'        from wwv_dg_blueprints',
'        where id = :P4009_BLUEPRINT_ID',
'    )',
'    loop',
'        :P4009_BLUEPRINT_NAME := c1.name;',
'    end loop;',
'',
'    l_clob := wwv_dg_data_gen_api.export_blueprint( p_name => :P4009_BLUEPRINT_NAME );',
'',
'    if length(l_clob) < 32767 then',
'      :P4009_BLUEPRINT_JSON := l_clob;',
'    else',
'      :P4009_BLUEPRINT_JSON := wwv_flow_lang.system_message( ''ODG.BLUEPRINT.EXPORT_FILE_LIMIT'', :P4009_BLUEPRINT_NAME );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P4009_BLUEPRINT_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_internal_uid=>2707757903590130.4501
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2708914974590142.4501)
,p_process_sequence=>10
,p_process_point=>'ON_DEMAND'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'DL_DOC'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_json      clob;',
'    l_file_ext  varchar2(4)   := ''json'';',
'    l_mime_type varchar2(30)  := ''application/json'';',
'    l_name      varchar2(200) := wwv_flow_escape.html( p_string => :P4009_BLUEPRINT_NAME );',
'    l_offset    number        := 1;',
'    l_buffer    pls_integer   := 20000;',
'    l_filename  varchar2(255) := lower( replace( l_name, '' '', ''_'' ) ) || ''.'' || l_file_ext;',
'begin',
'',
'    l_json := wwv_dg_data_gen_api.export_blueprint( p_name => l_name );',
'',
'    sys.htp.init;',
'    ',
'    sys.owa_util.mime_header( l_mime_type, false );',
'    sys.htp.p( ''content-length: '' || sys.dbms_lob.getlength( l_json ) );',
'    sys.htp.p( ''content-disposition: attachment; filename="'' || l_filename || ''"'');',
'    sys.owa_util.http_header_close;',
'',
'    -- looping prints > 32k',
'    loop',
'        exit when l_offset > sys.dbms_lob.getlength( l_json );',
'        sys.htp.prn( sys.dbms_lob.substr( l_json, l_buffer, l_offset ) );',
'        l_offset := l_offset + l_buffer;',
'    end loop;',
'    ',
'    wwv_flow.stop_apex_engine;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Se ha producido un error al descargar el JSON del blueprint.',
'',
'#SQLERRM#'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2707670938590129.4501)
,p_process_success_message=>'El JSON del blueprint se ha descargado correctamente.'
,p_internal_uid=>2708914974590142.4501
);
end;
