,p_validation_sequence=>30
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_blob_content blob;',
'    l_clob_content clob;',
'begin',
'    if :P4010_BP_TYPE = ''COPY_PASTE'' then',
'',
'        return :P4010_BLUEPRINT is json ( strict );',
'    elsif :P4010_BP_TYPE = ''FILE'' and :P4010_BLUEPRINT_FILE is not null then',
'',
'        select blob_content',
'          into l_blob_content',
'          from wwv_flow_temp_files',
'         where name = :P4010_BLUEPRINT_FILE;',
'    ',
'        if sys.dbms_lob.getlength( l_blob_content ) > 0 then',
'            l_clob_content := wwv_flow_utilities.blob_to_clob(l_blob_content);',
'    ',
'            return l_clob_content is json ( strict );',
'        end if;',
'    end if;',
'',
'    return true;',
'end;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_BOOLEAN'
,p_error_message=>unistr('El blueprint debe ser un JSON v\00E1lido.')
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
);
