wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(1624591707558003.4501)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Import Blueprint File'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_blob_content blob;',
'    l_clob_content clob;',
'begin',
'    begin',
'        select blob_content',
'        into l_blob_content',
'        from wwv_flow_temp_files',
'        where name = :P4010_BLUEPRINT_FILE;',
'    exception',
'        when no_data_found then',
'            raise;',
'    end;',
'',
'    -- The code below is temporary and will work with the existing wwv_dg_data_gen_api.import_blueprint()',
'    -- procedure (that only accepts a clob). An overloaded procedure will soon be provided by Insum that',
'    -- accepts a blob. Once that overloaded version of the import_blueprint() procedure is available,',
'    -- the uncommented code below should be removed and the commented out call to',
'    -- wwv_dg_data_gen_api.import_blueprint() (that uses a p_blob parameter) should be uncommented.',
'    -- Allan 9-JUL-2021',
'    if sys.dbms_lob.getlength(l_blob_content) > 0 then',
'        l_clob_content := wwv_flow_utilities.blob_to_clob(l_blob_content);',
'        wwv_dg_blueprint_util_int.g_current_schema := :DATAGEN_SCHEMA;',
'        wwv_dg_data_gen_api.import_blueprint (',
'            p_clob          => l_clob_content,',
'            p_override_name => :P4010_OVERRIDE_NAME,',
'            p_replace       => case when :P4010_REPLACE_YN = ''Y'' then true',
'                                    when :P4010_REPLACE_YN = ''N'' then false end,',
'            p_blueprint_id  => :P4010_BLUEPRINT_ID',
'        );',
'    end if;',
'',
'',
'    /*',
'    wwv_dg_data_gen_api.import_blueprint (',
'        p_blob          => l_blob_content,',
'        p_override_name => :P4010_OVERRIDE_NAME,',
'        p_replace       => case when :P4010_REPLACE_YN = ''Y'' then true',
'                                when :P4010_REPLACE_YN = ''N'' then false end,',
'        p_blueprint_id  => :P4010_BLUEPRINT_ID',
'    );',
'    */',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
'Se ha producido un error al intentar importar el blueprint.',
'',
'#SQLERRM_TEXT#'))
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(2644840985134533.4501)
