'begin',
'',
'    if wwv_flow_collection.collection_exists( p_collection_name => ''PREVIEW_DATA'' ) then ',
'        wwv_flow_collection.delete_collection(',
'            p_collection_name => ''PREVIEW_DATA'' );',
'    end if;',
'',
'    if wwv_flow_collection.collection_exists( p_collection_name => ''PREVIEW_DATA_HEADERS'' ) then',
'        wwv_flow_collection.delete_collection (',
'            p_collection_name => ''PREVIEW_DATA_HEADERS'' );',
'    end if;',
'',
'    -- This variable must be set (Again) before running the preview.',
'    wwv_dg_blueprint_util_int.g_current_schema := :DATAGEN_SCHEMA;',
'',
'    wwv_dg_blueprint_util_int.preview_blueprint(',
'        p_blueprint         => :P4014_BP_NAME,',
'        p_table_name        => :P4014_TABLE_NAME,',
'        p_number_of_rows    => 10,',
'        p_data_collection   => ''PREVIEW_DATA'',',
'        p_header_collection => ''PREVIEW_DATA_HEADERS''',
'    );',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select null',
'  from wwv_dg_blueprint_tables a',
' where not exists ( select * from wwv_dg_blueprint_tab_columns where blueprint_table_id = a.id )',
'   and a.blueprint_id = :P4014_BP_ID',
'   and a.security_group_id = :flow_security_group_id'))
,p_process_when_type=>'NOT_EXISTS'
,p_internal_uid=>3845874609303967.4501
);
