wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(1718338441293533.4501)
,p_event_id=>wwv_flow_imp.id(1718240832293532.4501)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'// Clear previous selections, if any',
'$s("P4020_SELECTED_ROWS", "");',
'',
'let gridView = apex.region("validTables").call("getViews").grid,',
'    records = gridView.getSelectedRecords(),',
'    invalidTables = [],',
'    tableName,',
'    selRecords;',
'',
'if (records.length > 0) {',
'    selRecords  = records.map( function(r) {',
'        var num_rows = gridView.model.getValue( r, "NUM_ROWS" ),',
'            table_name = gridView.model.getValue( r, "TABLE_NAME");',
'        if ( num_rows && num_rows > 0 ) {',
'            return table_name + '':'' + num_rows;',
'        } else {',
'            invalidTables.push(table_name);',
'        }',
'    });',
'    ',
'    if ( invalidTables.length === 0 ) {',
'        apex.page.submit({',
'            request: "CREATE_BLUEPRINT",',
'            set: {',
'                "P4020_SELECTED_ROWS": selRecords',
'            },',
'            showWait: true',
'        });',
'    } else {',
'        apex.message.alert( apex.lang.getMessage("ODG.MESSAGE.INVALID_ROWS", invalidTables.join('', '') ) );',
'    }',
'} else {',
'    apex.message.alert( apex.lang.getMessage("ODG.MESSAGE.SELECT_ONE_TABLE") );',
'}'))
);
