,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create Blueprint Copy Paste'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_tables_arr           wwv_flow_t_varchar2;',
'    l_excluded_columns_arr wwv_flow_t_varchar2;',
'begin',
'    if :P4020_TABLES_LIST_INPUT is not null then',
'        l_tables_arr := wwv_flow_string.split( :P4020_TABLES_LIST_INPUT, '','' );',
'        ',
'        if :P4020_EXCLUDED_COLUMNS is not null then',
'            l_excluded_columns_arr := wwv_flow_string.split( :P4020_EXCLUDED_COLUMNS, '','' );',
'        end if;',
'',
'        wwv_dg_blueprint_util_int.g_current_schema := :DATAGEN_SCHEMA;',
'',
'        wwv_dg_blueprint_util_int.add_blueprint_from_tables(',
'            p_name            => :P4020_BLUEPRINT_NAME,',
'            p_description     => ''Generated using existing tables.'',',
'            p_tables          => l_tables_arr,',
'            p_preserve_case   => ''N'',',
'            p_exclude_columns => l_excluded_columns_arr,',
'            p_blueprint_id    => :P4020_BLUEPRINT_ID,',
'            p_default_schema  => :DATAGEN_SCHEMA',
'        );',
'    end if;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_error_message=>wwv_flow_string.join(wwv_flow_t_varchar2(
