 p_id=>wwv_flow_imp.id(2630427431305703.4501)
,p_event_id=>wwv_flow_imp.id(2630391999305702.4501)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attribute_01=>wwv_flow_string.join(wwv_flow_t_varchar2(
'apex.message.clearErrors();',
'',
'const showUrlError = errm => {',
'    apex.message.showErrors( {',
'        type: "error",',
'        location: "page",',
'        message: errm',
'    } );',
'};',
'',
'const submit = () => {',
'    apex.page.submit( {',
'        request: "CREATE"',
'    } );',
'};',
'',
'if( apex.items.P5015_SOURCE_OPTIONS.value === "URL" ) {',
'    const url = apex.items.P5015_SOURCE_URL.value;',
'    if( !url) {',
'        apex.message.showErrors( {',
'            type: "error",',
'            location: "inline",',
'            pageItem: "P5015_SOURCE_URL",',
'            message: apex.lang.getMessage( "OB.MLE.URL_MUST_BE_PROVIDED" )',
'        } );',
'    } else {',
'        fetch( url )',
'            .then( res => {',
'                if( !res.ok ) {',
'                    throw new Error( apex.lang.getMessage( "OB.MLE.URL_COULD_NOT_FETCH" ) );',
'                }',
'                return res.text();',
'            })',
'            .then( text => {',
'                apex.items.P5015_SOURCE_TEXT.value = text;',
'                submit();',
'            } )',
'            .catch( e => {',
'                apex.message.showErrors( {',
'                    type: "error",',
'                    location: "page",',
'                    message: e.message',
'                } );',
'            } );',
'    }',
'} else {',
'    submit();',
'}'))
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(2984396387654501.4501)
,p_process_sequence=>20
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'On Create Click - Create Module'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'declare',
'    l_clob clob;',
'begin',
'    wwv_flow_sw_api.check_priv( :P5015_PARSING_SCHEMA );',
'',
'    if :P5015_SOURCE_OPTIONS = ''FILE'' then',
'        select wwv_flow_utilities.blob_to_clob( blob_content )',
'          into l_clob',
'          from wwv_flow_temp_files',
'         where name = :P5015_SOURCE_FILE;',
'    elsif :P5015_SOURCE_OPTIONS in ( ''TEXT'', ''URL'' ) then',
'        l_clob := :P5015_SOURCE_TEXT;',
'    end if;',
'',
'    wwv_flow_code_exec_mle_dev.create_module (',
'        p_schema        => :P5015_PARSING_SCHEMA,',
'        p_module_name   => :P5015_NAME,',
'        p_language      => wwv_flow_code_exec.c_javascript,',
'        p_version       => :P5015_MODULE_VERSION,',
'        p_source        => l_clob );',
'',
'    -- set return item values to OB page 2000',
'    :P5015_OBJECT_TYPE := ''MLE_MODULE'';',
'',
'    select object_id,',
'           status',
'      into :P5015_OBJECT_ID,',
'           :P5015_OBJECT_STATUS',
'      from sys.dba_objects',
'     where object_name = :P5015_NAME',
'       and object_type = ''MLE MODULE''',
'       and owner       = :P5015_PARSING_SCHEMA;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_process_when_button_id=>wwv_flow_imp.id(1694304467472737.4501)
,p_process_success_message=>unistr('Se ha creado el m\00F3dulo')
,p_internal_uid=>2984396387654501.4501
);
